_SECTION_ANALYTICS_VALUES = {"config", "prompt", "both", "setup"}


def _get_onboarding_state(org_id: str) -> dict:
    """Read onboarding_state — Supabase ``teams.onboarding_state`` (jsonb,
    migration 0006) in Supabase mode, registry Org node (JSON string) for
    selfhost.

    Auto-initializes to defaults if missing. Supabase mode: ``teams`` rows
    default onboarding_state to '{}', so reads return the merged default
    shape without writing (the first patch materializes the full state).
    """
    from tortoise.supabase_control import (
        get_control_plane,
        is_supabase_enabled,
    )
    from tortoise.supabase_control import (
        org_onboarding_state as _sb_state,
    )
    if is_supabase_enabled():
        stored = _sb_state(get_control_plane(), org_id)
        # None = org row missing — mirror the registry MATCH-no-op: read as
        # defaults, don't write.
        return stored if stored is not None else _onboarding_defaults()
    import json as _json
    sdk = _make_sdk(namespace="registry")
    rows = sdk._get_registry().query(
        "MATCH (t:Team {id: $id}) RETURN t.onboarding_state",
        params={"id": org_id},
    ).result_set
    if not rows or rows[0][0] is None:
        state = _onboarding_defaults()
        _write_onboarding_state(org_id, state)
        return state
    try:
        stored = _json.loads(rows[0][0]) if isinstance(rows[0][0], str) else rows[0][0]
    except (TypeError, ValueError):
        stored = {}
    state = _onboarding_defaults()
    state.update(stored)
    return state


def _graph_recording_override(org: dict) -> bool | None:
    """C6 #2115 (D-C6-3): the session_recording override for the graph the
    auth dict targets.

    - graph-bound key (``graph_id`` set) → that graph's override (registry
      Graph node recording prop / supabase graphs row). FAIL-CLOSED: a
      vanished graph (graph_id set but no node/row) raises 403
      GRAPH_NOT_FOUND — never demote a ghost key to the org default (the
      C5 backups_create lesson; _data_sdk opens the same graph, so the
      capture would fail downstream anyway).
    - org-wide / session (``graph_id`` None) → the DEFAULT graph's
      override (registry kind='default' node / supabase kind='default'
      row — graph 0 is settable per §6.3).
    - None = inherit the org default (#1927 default-ON preserved — a
      per-graph NULL never flips an org ON).
    """
    from tortoise.supabase_control import (
        get_control_plane,
        is_supabase_enabled,
    )
    org_id = org["org_id"]
    gid = org.get("graph_id")  # None → the default graph
    try:
        if is_supabase_enabled():
            cp = get_control_plane()
            if gid:
                rows = cp.query(
                    "graphs", select=["recording"],
                    filters=[("id", "eq", gid), ("org_id", "eq", org_id),
                             ("status", "eq", "active")],
                )
                if not rows:
                    raise HTTPException(
                        status_code=403,
                        detail={"error_code": "GRAPH_NOT_FOUND",
                                "message": "graph not found for key"})
                return rows[0].get("recording")
            rows = cp.query(
                "graphs", select=["recording"],
                filters=[("org_id", "eq", org_id), ("kind", "eq", "default"),
                         ("status", "eq", "active")],
            )
            return rows[0].get("recording") if rows else None
        sdk = _make_sdk(namespace="registry")
        if gid:
            rows = sdk._get_registry().query(
                "MATCH (g:Graph {id:$gid, org_id:$tid}) "
                "WHERE coalesce(g.status, 'active') <> 'deleted' "
                "RETURN g.recording",
                params={"gid": gid, "tid": org_id},
            ).result_set
            if not rows:
                # Active-node lookup missed — the node may be absent (vanish,
                # 403) OR a tombstone (soft-deleted — also fail closed; a
                # ghost key on a deleted graph must not capture).
                raise HTTPException(
                    status_code=403,
                    detail={"error_code": "GRAPH_NOT_FOUND",
                            "message": "graph not found for key"})
            return rows[0][0]
        rows = sdk._get_registry().query(
            "MATCH (g:Graph {org_id:$tid, kind:'default'}) "
            "WHERE coalesce(g.status, 'active') <> 'deleted' "
            "RETURN g.recording",
            params={"tid": org_id},
        ).result_set
        return rows[0][0] if rows else None
    except HTTPException:
        raise
    except Exception:
        # Drift-safe (round-1 P2): a graphs-table read failure (migration
        # one behind — the graph_metadata/graph_count convention) or a
        # registry hiccup must NEVER 500 every capture — degrade to
        # inherit-org-default for this request. A graph-bound key on a
        # genuinely vanished ACTIVE node still 403s above (row-absent, not
        # query-failure).
        return None


def _session_recording_allowed(org: dict) -> tuple[bool, str]:
    """C6 #2115 (D-C6-3): the EFFECTIVE session_recording for a capture.

    Resolution order: the graph's override (D-C6-1 storage) → when None the
    org default (onboarding_state.session_recording — the #1927 flag the
    dashboard toggle + MCP tortoise_onboarding_session_recording write).
    Returns (allowed, surface) where surface names the deciding layer for
    the 409 message (``graph`` vs ``org``).
    """
    state = _get_onboarding_state(org["org_id"])
    if not state.get("session_recording"):
        # #1927 master kill (round-1 decision c2): the org-level OFF is
        # the user's explicit opt-out — a per-graph override NEVER re-enables
        # it (R9: opt-out never silently re-enabled). Overrides may only
        # RESTRICT when the org is ON.
        #
        # Round-2b P3 (cause layering): a GRAPH-BOUND key on a dead graph
        # still surfaces ITS OWN 403 (GRAPH_NOT_FOUND) even on an opted-out
        # org — probe the override (which fails closed on vanish/tombstone)
        # and ignore its value, so remediation points at the dead key, not
        # the org toggle. Org-wide keys short-circuit (no extra read).
        if org.get("graph_id"):
            _graph_recording_override(org)
        return False, "team"
    override = _graph_recording_override(org)
    if override is not None:
        return bool(override), "graph"
    return True, "team"


async def _session_recording_allowed_off_loop(org: dict) -> tuple[bool, str]:
    """`_session_recording_allowed` off the event loop (#4625, leg 12).

    The helper is synchronous END TO END and both of its legs block: its
    ``_get_onboarding_state`` read goes through the blocking
    ``SupabaseControlPlane`` transport in hosted mode (and the registry Team
    node in selfhost), and ``_graph_recording_override`` opens a graph handle.
    Called inline from ``_capture_session_impl`` it held the single event loop
    for the whole resolution — one of the py-spy MainThread legs #4625 was
    measured on.

    The unit of offload is the RESOLUTION (the #3498 design), so the org
    default read and the per-graph override probe stay in ONE worker. The pool
    is ``graph`` and the bound is the seam's standard REQUEST bound — the same
    contract its sibling read wrapper keeps
    (``_get_onboarding_projection_off_loop``): a capture must not park a graph
    worker for the lane's cold-start allowance, and an over-bound read fails
    closed (503) rather than hanging the capture.

    Read-MOSTLY, not read-only (the #4625 work order §2): in the selfhost lane
    ``_get_onboarding_state`` auto-materializes defaults, but that write is
    idempotent, so abandoning the worker on a bound miss is safe.
    """
    return await _graph_offload(
        lambda: _session_recording_allowed(org),
        op="session_recording_allowed",
        timeout=_monitoring.CONTROL_PLANE_OFFLOAD_TIMEOUT_S,
    )


def _onboarding_defaults() -> dict:
    """Fresh default-state dict (code-review P2): the list-typed keys
    (github_issues_scope / github_docs_scope) must NOT be shared across orgs
    — a shallow ``dict()`` copy shares the same list objects, so an in-place
    mutation (``append``/``remove``) on one org's state would leak into
    every org's defaults. List values are copied per-read; scalars are
    immutable and safe to share."""
    return {k: (list(v) if isinstance(v, list) else v)
            for k, v in _ONBOARDING_DEFAULT_STATE.items()}


def _write_onboarding_state(org_id: str, state: dict) -> None:
    """Persist onboarding state — Supabase ``teams.onboarding_state`` (jsonb —
    no string-wrapping, 0006) or the registry Org node (JSON string —
    #498 fix: FalkorDB node properties must be primitives, not dicts).

    #2001 (W5): defensively STRIPS FLOW keys (fork/status/version/step
    edges/member_progress/last_decide_attempt/compact) before persisting —
    jsonb NEVER holds FLOW state (the router branches before the allowlist
    filter; this is the belt-and-braces backstop the registration-split
    negatives pin)."""
    _stripped_flow = {k for k in state
                      if k in _os.FLOW_KEYS or k in _os.STEP_IDS}
    if _stripped_flow:
        # #3821: this is the last chance to learn the router leaked a FLOW
        # key. The strip itself is unchanged (jsonb NEVER holds FLOW state);
        # the drop is now reported instead of silent — it was the
        # "defensive" backstop with no observer.
        _report_unregistered(
            "onboarding_state", "flow_keys_stripped_at_write", _stripped_flow)
        state = {k: v for k, v in state.items()
                 if k not in _os.FLOW_KEYS and k not in _os.STEP_IDS}
    from tortoise.supabase_control import (
        get_control_plane,
        is_supabase_enabled,
    )
    from tortoise.supabase_control import (
        update_onboarding_state as _sb_write,
    )
    if is_supabase_enabled():
        _sb_write(get_control_plane(), org_id, state)
        return
    import json as _json
    sdk = _make_sdk(namespace="registry")
    sdk._get_registry().query(
        "MATCH (t:Team {id: $id}) SET t.onboarding_state = $state",
        params={"id": org_id, "state": _json.dumps(state)},
    )


def _org_proj(org_id: str):
    """Tenant-graph projection handle for onboarding writes/reads."""
    return _make_sdk(namespace=org_id)._get_proj()


def _maybe_apply_completion(org_id: str) -> bool:
    """Post-write gate eval (scope pin 12): reads the fresh node + step
    edges, evaluates the fork-aware gate, and writes status 'complete' when
    satisfied. MONOTONIC: complete can never regress; a grandfathered org's
    first FLOW write evals to no-op (status stays complete — never
    re-onboarded). Returns True when the org transitioned to complete
    (the caller invalidates the MCP TTL cache)."""
    try:
        proj = _org_proj(org_id)
        node = _os.read_onboarding_node(proj, org_id)
        if node is None:
            return False
        if node.get("status") == _os.STATUS_COMPLETE:
            return False
        steps = _os.completed_steps(proj, org_id)
        if _os.completion_gate_satisfied(
                steps, node.get("fork"), bool(node.get("compact")),
                fork_unsure_at=bool(node.get("fork_unsure_at"))):
            _os.write_status(proj, org_id, _os.STATUS_COMPLETE)
            try:  # created-signal invalidates the 60s MCP TTL cache (pin 18)
                from tortoise import mcp_server as _mcp
                # C5 #2114 (accepted residual, re-review P2): the cache pop
                # only reaches THIS worker's in-process cache — a multi-worker
                # deploy serves stale onboarding state from the other workers
                # for up to the 60s TTL. Bounded + fail-open (state reads
                # degrade to a fresh read, never a wrong authorization).
                _mcp._onboarding_state_cache.pop(org_id, None)
            except Exception:
                pass
            return True
        return False
    except Exception:
        return False


def _maybe_file_harness_connected(org_id: str) -> None:
    """#3670: file ``harness-connected`` off a server-observed AGENT write.

    The completion signal was MCP-tool-only (``mcp_server
    ._maybe_onboarding_auto_complete``), so a REST-first / build-fork org —
    whose only in-flow write is the wizard's ``POST /v1/points`` curl — could
    never reach the connected screen (#3670). An AGENT-credentialed graph
    write IS the observation the step claims: the agent's own credential was
    used, so "your agent connected" is literally true.

    Callers MUST gate on ``_credential_is_agent`` AND on the key NOT being
    graph-bound — a session-JWT (dashboard/browser) write observes no agent
    and must never file this (the #3670 design constraint: filing generically
    would re-create the exact false claim lane B3 deleted, merely moved from
    the client into the server), and a graph-bound key writing org-DEFAULT
    graph state would be a cross-graph write (C5 #2114). Step write is
    FWW/keyed-MERGE (replay is a no-op). Fail-open: a graph/state hiccup must
    never fail the agent's committed write — the precedent is
    ``mcp_server._maybe_onboarding_auto_complete``'s fail-open ``except``."""
    try:
        legacy_mirror = bool(
            _get_onboarding_state(org_id).get("onboarding_complete"))
        # review P2: own the SDK handle and close it. `_org_proj` opens a
        # fresh SDK per call and leaks a connection otherwise (the same leak
        # the PATCH handler documents at #1997); this runs on the hot
        # point-write path, so it must not add a per-write leak.
        #
        # Open the LISTED org-graph name (the same selection
        # `_get_onboarding_projection` reads through) and SKIP on None. This
        # STEP WRITE must never MINT a graph name that was never observed: do
        # NOT pre-check existence with `_graph_available` — that helper builds
        # `_make_sdk(namespace=org_id)._get_proj()`, whose constructor runs
        # `_ensure_indexes()` (CREATE INDEX) and so MATERIALIZES the very
        # `org_{org_id}` this write must not create; the subsequent
        # `_open_org_graph_sdk` then re-probes the listing it just polluted
        # and files the step into the graph its own guard minted.
        # `_open_org_graph_sdk` selects from `_registry_existing_graphs`,
        # which reads `list_graphs()` off the registry projection; it can
        # therefore materialize only the REGISTRY graph, never an org graph.
        # None means NEITHER name is listed, or the registry probe failed.
        # Skip, loudly — the caller's point write is never touched by this
        # function.
        #
        # Scope of the no-mint claim: it covers THIS step write's own graph
        # selection, which never constructs an org namespace. It does NOT
        # cover the completion gate below — `_maybe_apply_completion` opens
        # the org DEFAULT projection via `_org_proj(org_id)` (canonical
        # `org_{org_id}`), whose constructor materializes that name by design.
        # That is the pre-existing #3670 legacy-name gap, a separate
        # behaviour, not a step-write mint, and out of scope here.
        _sdk = _open_org_graph_sdk(org_id)
        if _sdk is None:
            _logger.warning(
                "onboarding auto-file (harness-connected) skipped: no listed "
                "org graph to write (org=%s, step not filed)", org_id)
            return
        try:
            _os.write_completed_step(
                _sdk._get_proj(), org_id, "harness-connected",
                status_from_mirror=legacy_mirror)
        finally:
            _sdk.close()
        _maybe_apply_completion(org_id)
    except Exception:
        _logger.exception(
            "onboarding auto-file (harness-connected) failed (non-fatal, "
            "org=%s)", org_id)


# ── #2006 (W11): onboarding funnel telemetry ──────────────────────────
# The emission gate is the COMPLETED_STEP edge's NEW CREATION — the
# ``created`` flag ``onboarding.state.write_completed_step`` already returns
# for exactly this purpose. That transition is the domain fact itself, so
# one event per edge creation falls out of it by construction: restart-safe
# and multi-worker-safe, with NO second dedup store, NO threshold and NO
# in-process set. Every writer of a W11 step maps its own edge result
# through ``_emit_onboarding_step_events``; a non-creating replay never
# reaches the emitter. (``decide-completed`` is the one W11 edge
# with a sanctioned removal path — the #3912 repair — after which a genuine
# re-completion re-emits; see ``analytics.onboarding_decide_complete``.)
#
# Deliberately NOT instrumented: ``harness-connected`` (the funnel keys off
# seed/decide), ``catalog-presented`` (the build fork's display row has
# no W11 event), and ``connection-written`` (#3451 — a client-observed trace
# of the config WRITE, not a funnel transition).
_ONBOARDING_STEP_EVENTS = {
    "first-points-filed": onboarding_seed_complete,
    "decide-completed": onboarding_decide_complete,
}


def _onboarding_distinct_id(org_id: str, org: dict | None = None,
                            *, user_id: str | None = None) -> str:
    """Funnel identity for the W11 onboarding events (#2006).

    The Supabase user UUID wherever one is RESOLVABLE, falling back to the
    org id — matching ``analytics.py``'s identity contract so these server
    events join the web funnel's ``user_signed_up`` (distinct_id = user
    UUID, never an email).

    Every candidate passes the SAME predicate the #2600 ``actor_user_id``
    alias uses (``_is_uuid_shape``): the repo documents that a raw
    ``created_by`` is NOT always a human id — production mints store the
    literal ``"api"``, ``st_``-prefixed recovery ids, and registry-lane
    EMAIL self-signup creators (``tortoise/sdk.py``). Emitting one of those
    as ``distinct_id`` would push PII into PostHog and collapse unrelated
    orgs onto one pseudo-person, so a non-UUID candidate is DROPPED."""
    from tortoise.sdk import _current_actor_user_id, _is_uuid_shape
    candidates = [user_id]
    if org is not None:
        candidates += [org.get("actor_user_id"),
                       org.get(_SESSION_USER_ID_KEY),
                       org.get("created_by")]
    candidates.append(_current_actor_user_id.get())
    for uid in candidates:
        if _is_uuid_shape(uid):
            return uid
    return org_id


def _emit_onboarding_step_events(created_steps, *, distinct_id: str,
                                 org_id: str, source: str) -> None:
    """Emit the W11 funnel event for each step edge a write NEWLY created.

    ``created_steps`` must carry ONLY the steps whose ``created`` was True —
    that filtering is the caller's gate, so a replay is silent and the
    event is exact-once per edge creation. Fail-safe: ``capture()`` never
    raises, and each emit is guarded here too, so telemetry can never turn a
    committed write into an error."""
    for step in created_steps:
        emit = _ONBOARDING_STEP_EVENTS.get(step)
        if emit is None:
            continue
        try:  # noqa: SIM105
            emit(distinct_id, org_id, source)
        except Exception:
            pass  # telemetry must never break the write path (R19)


def _update_onboarding_state(org_id: str, _echo: bool = True,
                             **fields) -> dict:
    """Per-key-type router (#2001 W5): OPERATIONAL keys → jsonb RMW (the
    legacy whole-dict merge — its non-atomicity caveat is pre-existing
    infra); FLOW step-edge keys → graph keyed MERGE; other FLOW scalar keys
    → graph writers. Branches BEFORE the allowlist filter so FLOW keys can
    never round-trip into jsonb. Unknown keys are dropped (fail-closed,
    never default-to-FLOW) and the drop is REPORTED (raised instead under
    strict mode). Returns the MERGED PROJECTION — the writer echo
    can never diverge from GET.

    ``_echo=False`` is the WRITE-ONLY contract for callers that DISCARD that
    return (#4625): the writes above still happen; only the projection read is
    skipped, so it cannot change what was written. It exists because the
    projection is not free — ``_get_onboarding_projection`` probes the
    registry UP TO TWICE (one probe when the org graph is ABSENT, which
    returns early in ``_get_onboarding_projection``; two when it is present),
    and in URI mode each probe builds a fresh registry SDK and
    opens a NEW FalkorDB connection (TCP + TLS handshake + ``INFO`` +
    ``list_graphs``), synchronously, on the event loop. Returns ``{}`` when
    skipped: a caller that discards the value cannot tell the difference.
    Callers that need the echo (GET/PATCH) keep the default.

    NOTE: this router's step-edge branch is NOT on the PATCH catalog path —
    `patch_onboarding_state` pops `catalog_presented` and writes the edge +
    evals itself, and the checkpoint path calls the state.py writers directly.
    Any other caller that hands a step id to this router does get the
    post-write gate eval."""
    jsonb_fields: dict[str, object] = {}
    wrote_step = False
    # #2006 (W11): the steps whose COMPLETED_STEP edge THIS call created —
    # the only steps a funnel event may be emitted for.
    created_steps: list[str] = []
    for k, v in fields.items():
        if k in _os.STEP_IDS:
            if _os.write_completed_step(
                    _org_proj(org_id), org_id, k).get("created"):
                created_steps.append(k)
            wrote_step = True
        elif k in _os.FLOW_KEYS:
            # only step-edge keys are routable here; scalar FLOW keys are
            # rejected by the PATCH surface / checkpoint before reaching
            # this point (never default-to-jsonb). #3821: the rejection is
            # reported with its OWN reason, so a scalar FLOW key stays
            # distinguishable from a typo'd operational key.
            _report_unregistered(
                "onboarding_state", "flow_scalar_rejected_at_router", {k})
        elif k in _ALLOWED_STATE_KEYS:
            jsonb_fields[k] = v
        else:
            # #3821: the negative branch that used to be nothing. An
            # unregistered key matched no arm and vanished with no observer.
            _report_unregistered("onboarding_state", "unknown_key", {k})
    if jsonb_fields:
        state = _get_onboarding_state(org_id)
        for k, v in jsonb_fields.items():
            state[k] = v
        _write_onboarding_state(org_id, state)
    if wrote_step:
        _maybe_apply_completion(org_id)
        # #2006 (W11): emit for the edges this call NEWLY created (empty on a
        # replay). No production caller routes a W11 step here today — the
        # PATCH boundary 422s first-points-filed/decide-completed — but this
        # generic router accepts any STEP_IDS key, so it is instrumented so a
        # future routing change cannot silently lose the funnel event.
        if created_steps:
            _emit_onboarding_step_events(
                created_steps, distinct_id=_onboarding_distinct_id(org_id),
                org_id=org_id, source="state_router")
    # Echo = the MERGED PROJECTION (writer-return-composed — GET/PATCH can
    # never diverge), overlaid with the just-written jsonb fields: the
    # pre-#2001 echo returned the in-memory merged state, and a missing
    # Org row (no-op jsonb write) must not silently flip the client's
    # just-ACKed value (test-seam + pre-existing echo semantics). The
    # overlay is never FLOW — operational keys only.
    #
    # #4625: the echo is NOT free, and callers that DISCARD it must say so.
    # ``_get_onboarding_projection`` reaches ``_registry_existing_graphs()``
    # UP TO TWICE (one probe when the org graph is absent — it returns early
    # there; two when present, the per-capture case), and in URI mode each
    # probe builds a fresh
    # ``_make_sdk(namespace="registry")`` and opens a NEW FalkorDB connection
    # (TCP + TLS handshake + ``Is_Sentinel``'s ``INFO`` + ``list_graphs``).
    # An AGENT capture (the fleet case) calls this router twice — the receipt
    # write, then the last-error clear — and discards both returns, so the
    # discarded reads alone open four fresh connections per capture. (A
    # no-harness capture — a session-JWT/dashboard caller — writes the bare
    # receipt but has no last-error key, so it makes one call, two
    # connections.) All of it runs synchronously ON the event loop, which stalls
    # every read in flight and drives the transport-bound 504s. Measured by
    # py-spy on the live machine: the loop thread sitting in
    # ``do_handshake (ssl.py:1319)`` <- ``_registry_existing_graphs`` <-
    # ``_get_onboarding_projection`` <- ``_record_capture_last_error`` <-
    # ``_capture_session_impl``.
    #
    # Scope: #4625 names "the capture path and install-probe", and exactly the
    # sites on those two endpoints pass ``_echo=False``. The onboarding, demo,
    # GitHub-callback and indexing callers also discard the echo, but they are
    # NOT per-capture — they keep the default so this stays bounded to the
    # frequency the issue is about.
    #
    # ``_echo=False`` is the write-only contract for those callers. The
    # projection is a strictly read-only graph leg (see
    # ``_get_onboarding_projection``), so skipping it cannot change what was
    # written; it changes only what is computed. Default True keeps every
    # GET/PATCH writer-echo caller byte-identical.
    if not _echo:
        return {}
    echo = _get_onboarding_projection(org_id)
    if jsonb_fields:
        echo.update(jsonb_fields)
    return echo


class OnboardingStateResponse(BaseModel):
    onboarding: dict
    # E2E-5 (plan Task 6): the org email is read from the control plane
    # alongside onboarding state — additive, backward-compatible (None when
    # the org has no email yet). #764 review P2: wires the email seam so it
    # is not dead code.
    email: str | None = None


# #2001 (W5): node-aware wire completion is LIVE; accept-and-drop for
# PATCH onboarding_complete on node-present orgs lands AFTER W1 (#1997)
# removes wizardComplete (cross-PR ordering pin) — until then the legacy
# jsonb writer stays active and the grandfathered-window guard in
# resolve_wire_completion keeps wizard-completed orgs complete.
_ACCEPT_AND_DROP = True  # W1 (#1997) landed — PATCH onboarding_complete is dropped on node-present orgs (plan T7)


def _graph_has_org_namespace(org_id: str) -> bool:
    """Existence check WITHOUT constructing the ORG projection (constructing
    org_{tid} would materialize an absent org graph — a read-path write,
    banned by pin 4). Probes the server-wide graph list via the registry
    seam's projection (list_graphs never mints org_{tid}).

    A bare bool is NOT sufficient for a caller that then OPENS the graph:
    this is True when either tenant prefix is listed, so True does not say
    WHICH name is real. Such callers must open through `_open_org_graph_sdk`
    — `_make_sdk(namespace=org_id)` re-derives `org_{org_id}` from the
    namespace rule and would therefore open, and so MINT, a different, absent
    graph for a legacy `team_{org_id}` org, defeating this function's purpose.
    Callers that only need the verdict (accept-and-drop gates) keep using
    this."""
    # #3543: both tenant prefixes are probed — a graph minted before the
    # rename is `team_{org_id}`, and no data migration rewrites it. Probing
    # only `org_` reported "node absent" for every pre-rename org, which made
    # the onboarding projection take the no-write FLOW-defaults path.
    graphs = _registry_existing_graphs()
    if graphs is None:
        # connection failure — treat as graph-up-unknown → the projection
        # falls through to the read (which raises → 'unavailable' markers)
        return True
    return any(name in graphs for name in (f"org_{org_id}", f"team_{org_id}"))


def _registry_existing_graphs() -> set[str] | None:
    """Server-wide existing graph names via the registry seam (best-effort).

    list_graphs() is a read that never mints a graph (pin-4) and never
    auto-recreates the deleted registry_control_plane in Supabase mode
    (#669) — the single probe behind _graph_has_org_namespace (onboarding hot
    path) and _open_org_graph_sdk (the graph-opening callers). Used as a
    probe-before-purge gate by the retention sweep (#2251 review P2): purging
    an ABSENT org_{tid} graph (orphan registry row from a partial provision
    between the Org-node create and the graph mint) would silently
    materialize an empty graph, flipping the onboarding existence verdict for
    orgs whose graph never existed. None = probe failed → caller skips the
    sweep this cycle (best-effort; the per-org SDK lazy hook still purges
    per-org graphs).

    #2251 (was #2179 follow-up): the old bare TortoiseSDK(namespace=
    "registry") resolved config.resolve_db_path() → ~/.tortoise/tortoise.db
    when TORTOISE_DB_PATH was unset while the anchored writers use
    /data-or-tempdir — the existence verdict probed the WRONG (likely empty)
    db. _make_sdk(namespace="registry") is byte-identical to the bare
    construction in URI mode (returns a fresh TortoiseSDK before any anchor
    logic — no keepalive, no _get_registry, so the deleted
    registry_control_plane is never auto-recreated in Supabase mode) and
    resolves the ANCHORED path in embedded mode (the db writers use). The
    fresh handle is closed explicitly below (its close only drops the
    connection — the keepalive anchor holds the daemon, #493/#1607). The
    construction sits INSIDE the try so a cross-process
    EmbeddedStoreBusyError keeps the never-raise contract.
    """
    try:
        sdk = _make_sdk(namespace="registry")
        try:
            graphs = sdk._get_proj().db.list_graphs() or []
        finally:
            sdk.close()
        return set(graphs)
    except Exception:
        return None


def _open_org_graph_sdk(org_id: str) -> TortoiseSDK | None:
    """SDK on the org's DEFAULT graph, or None when the server lists neither
    the canonical nor the pre-rename name.

    Addresses the LISTED name explicitly, mirroring _require_graph_scope's
    custom-graph branch: `_make_sdk(namespace=org_id)` re-derives
    `org_{org_id}` from the namespace rule, so for a legacy `team_{org_id}`
    graph it would open — and so MINT — a different, absent graph (the
    read-path write pin 4 bans) and read an empty one. When the canonical
    name is listed the namespace form is used unchanged, so the embedded
    keepalive key and every downstream `sdk._namespace` consumer stay
    byte-identical to before this helper existed.

    None means "not listed" OR "the registry probe failed" —
    ``_registry_existing_graphs`` returns None on a probe failure, and
    ``if not listed`` treats that the same as an empty listing, so the two
    are NOT distinguishable here without a second probe. READ callers keep
    their `_make_sdk(namespace=org_id)` fallback (the read must proceed and
    raise → 'unavailable'); a WRITE caller must instead SKIP, because minting
    a name the probe never observed is exactly the pin-4 violation this
    helper exists to prevent.
    """
    listed = _registry_existing_graphs()
    if not listed:
        return None
    if f"org_{org_id}" in listed:
        return _make_sdk(namespace=org_id)
    if f"team_{org_id}" in listed:
        return _make_sdk(graph_name=f"team_{org_id}")
    return None


def _graph_available(org_id: str) -> bool:
    """Fail-loud graph-down guard for FLOW WRITES (503 before any write).
    Biased opposite to the READ path: a connection failure → False (the
    write must not half-land jsonb-side without the graph leg)."""
    try:
        _make_sdk(namespace=org_id)._get_proj().db.list_graphs()
        return True
    except Exception:
        return False


def _get_onboarding_projection(org_id: str) -> dict:
    """Merged onboarding state — OPERATIONAL keys from jsonb (the raw
    reader, byte-unchanged) + FLOW keys from the OnboardingState node
    (strictly read-only graph leg; the read path NEVER writes).

    Resolution order (pin 4/13):
    - graph exception/slow → FLOW 'unavailable' markers (200; operational
      keys still served; gate fails open).
    - graph up, node ABSENT (orphan / grandfathered pre-backfill) → FLOW
      defaults, no write (banned READ-side materialization).
    - node present → node FLOW keys + node-aware wire completion.

    ONE projection site for GET + PATCH echo + the MCP gate/tool — they
    cannot diverge."""
    raw = _get_onboarding_state(org_id)
    if not _graph_has_org_namespace(org_id):
        state = dict(raw)
        state.update(_os.flow_defaults())
        state["onboarding_complete"] = _os.resolve_wire_completion(
            None, bool(raw.get("onboarding_complete")), [])
        # #3451: no namespace → no steps → not restart-pending (False, never
        # the bare absence of the key, which a reader could confuse with
        # 'unknown').
        state["restart_pending"] = _os.restart_pending([])
        return state
    try:
        # Open the name the guard actually verified. `_make_sdk(namespace=)`
        # re-derives `org_{org_id}`, so for a legacy `team_{org_id}` org it
        # would MINT a different, absent graph (the read-path write pin 4
        # bans) and read an empty one — the guard's True would then be about a
        # name this line never opens. None comes back when the probe failed
        # (fail-open) or neither name is listed: fall back to the inline
        # construction so the read proceeds and raises → 'unavailable'.
        proj = (_open_org_graph_sdk(org_id)
                or _make_sdk(namespace=org_id))._get_proj()
        node = _os.read_onboarding_node(proj, org_id)
        steps = _os.completed_steps(proj, org_id) if node is not None else []
    except Exception:
        state = dict(raw)
        state.update(_os.flow_unavailable())
        # graph-down must NEVER fabricate a completion verdict from stale
        # legacy jsonb — 'unavailable' keeps the wire honest and the MCP
        # gate fail-open (non-bool → tools stay visible during outages).
        state["onboarding_complete"] = "unavailable"
        # #3451: a graph-down read does not know the step set, so it must not
        # claim either direction — 'unavailable', exactly like the FLOW keys
        # (never a fabricated False that would read as 'not restart-pending').
        state["restart_pending"] = "unavailable"
        return state
    state = dict(raw)
    if node is None:
        state.update(_os.flow_defaults())
        state["onboarding_complete"] = _os.resolve_wire_completion(
            None, bool(raw.get("onboarding_complete")), [])
        state["restart_pending"] = _os.restart_pending([])
        return state
    state.update({
        "fork": node.get("fork"),
        "status": node.get("status", _os.STATUS_ACTIVE),
        "version": node.get("version", 1),
        "completed_steps": steps,
        "member_progress": _os.parse_member_progress(
            node.get("member_progress")),
        "last_decide_attempt": node.get("last_decide_attempt"),
        "compact": node.get("compact", False),
        "fork_unsure_at": node.get("fork_unsure_at"),
    })
    state["onboarding_complete"] = _os.resolve_wire_completion(
        node.get("status"), bool(raw.get("onboarding_complete")), steps)
    # #3451: DERIVED from the step edges — config written, harness not yet
    # verified. The one definition lives in state.py (no second stored field).
    state["restart_pending"] = _os.restart_pending(steps)
    return state


async def _get_onboarding_projection_off_loop(org_id: str) -> dict:
    """The onboarding projection read, off the event loop (#2924).

    ``_get_onboarding_projection`` is synchronous END TO END, and both of its
    legs block:

    * the jsonb leg — ``_get_onboarding_state`` reads
      ``teams.onboarding_state`` through the blocking ``SupabaseControlPlane``
      transport (``httpx.Client``, ``supabase_control.py:454``);
    * the graph leg — ``_graph_has_org_namespace`` / ``_open_org_graph_sdk``
      reach ``_registry_existing_graphs`` / ``_get_proj()``, which CONSTRUCT a
      fresh ``FalkorProjection`` per call (``ssl.create_default_context`` →
      ``load_default_certs`` → TLS handshake → ``Is_Sentinel`` INFO), then
      issue the query.

    Called inline from a coroutine that is a periodic hot path, it blocks the
    single event loop for the WHOLE resolution. That is the #2924 stall:
    ``async def list_tools`` (``mcp_server.py``) calls the synchronous gate
    ``_org_onboarding_complete()``, and a ``py-spy`` MainThread dump taken while
    ``GET /health`` was stalled 1.08 s captured the loop parked in exactly
    these frames (``read`` ← ``httpx`` sync backend ← ``query`` ←
    ``org_onboarding_state`` ← ``_get_onboarding_state`` ←
    ``_get_onboarding_projection``; and ``create_default_context`` ←
    ``_registry_existing_graphs`` ← ``_graph_has_org_namespace`` ← the same
    function). Loopback ``GET /health`` answered in ~4 ms across 178 probes
    while the public path stalled 0.9–2.2 s on 10 of them, and the app's own
    heartbeat recorded ``loop_lag_max_ms`` of 2033 ms — so the stall is the
    loop, not the transport.

    The unit of offload is the RESOLUTION, not an individual HTTP call (the
    #3498 design): one hop keeps the projection's internal ordering (the jsonb
    read feeds the merge) inside one worker. The pool is ``graph`` because the
    resolution's cold-start-prone leg is the projection open, and the graph
    lane's wait bound is derived from ``probe_setup_timeout()`` precisely so a
    cold projection is not false-degraded (#3773). Failures propagate: callers
    that must fail open (the MCP gate) already coerce to ``False``.
    """
    return await _graph_offload(
        lambda: _get_onboarding_projection(org_id),
        op="onboarding_projection",
        # #2924: the gate's contract is fail-open, so a hung or cold graph must
        # not park a graph worker for the lane's cold-start allowance — the
        # seam's standard REQUEST bound is the right price here.
        # #2924 review: read the constant at CALL time, not import time — the
        # seam's bound tests monkeypatch ``monitoring``, and the lane bound
        # (``graph_offload_timeout_s()``) resolves at call time for the same
        # reason.
        timeout=_monitoring.CONTROL_PLANE_OFFLOAD_TIMEOUT_S)


# #1727 (Slice 2, Task 11): PATCH-field → state-key translation for the
# per-harness capture keys. Pydantic field names cannot carry hyphens, but
# the STATE keys are hyphenated per Literal member (session_capture_receipt_
# claude-desktop etc.) — the PATCH handler must translate underscore fields
# back to their hyphenated state keys, else the allowlist filter silently
# drops them (the parametrized registration test catches exactly this).
_PATCH_FIELD_TO_STATE_KEY: dict[str, str] = {
    "session_capture_receipt_claude_desktop": "session_capture_receipt_claude-desktop",
    "session_capture_receipt_claude_web": "session_capture_receipt_claude-web",
    "session_capture_last_error_claude_desktop": "session_capture_last_error_claude-desktop",
    "session_capture_last_error_claude_web": "session_capture_last_error_claude-web",
}


class OnboardingStatePatchRequest(BaseModel):
    github_connected: bool | None = None
    # #1924: per-source enable intent — the off-toggles write THESE, never
    # github_connected (which is the connection, shared by both sources).
    issues_enabled: bool | None = None
    docs_enabled: bool | None = None
    github_indexed: bool | None = None
    github_indexed_at: str | None = None  # #1894: last github index completion (ISO timestamp, server-stamped)
    demo_created: bool | None = None
    session_recording: bool | None = None
    org_created: bool | None = None
    prompt_pasted: bool | None = None
    onboarding_complete: bool | None = None
    # #1725 (Slice 0): registered state keys (see the registration table) —
    # the cursor is server-written; the fields exist so the keys round-trip
    # through the PATCH surface like every other registered key.
    github_index_cursor: dict | None = None
    github_legacy_backfill_done: bool | None = None
    # #1727 (Slice 2, Task 11): capture-surface registration-table members —
    # the server writes receipts/probes; the fields exist so every registered
    # key round-trips through the PATCH surface (parametrized registration
    # test) and the dashboard can read them back.
    capture_revised: bool | None = None
    capture_ask_shown: bool | None = None
    session_capture_receipt: str | None = None
    session_capture_receipt_claude: str | None = None
    session_capture_receipt_claude_desktop: str | None = None
    session_capture_receipt_claude_web: str | None = None
    session_capture_receipt_codex: str | None = None
    session_capture_receipt_cursor: str | None = None
    session_capture_receipt_pi: str | None = None
    session_capture_last_error_claude: str | None = None
    session_capture_last_error_claude_desktop: str | None = None
    session_capture_last_error_claude_web: str | None = None
    session_capture_last_error_codex: str | None = None
    session_capture_last_error_cursor: str | None = None
    session_capture_last_error_pi: str | None = None
    install_probe_claude: str | None = None
    install_probe_pi: str | None = None
    # #1726 (Slice 1): docs staged + ingested — server-written; registered so
    # the key round-trips through the PATCH surface.
    github_docs_indexed: bool | None = None
    github_docs_indexed_at: str | None = None  # #1894: last docs index completion (ISO timestamp, server-stamped)
    # E2E-5 (plan Task 6): email read-patch from the control plane (orgs
    # row in Supabase mode, Org node in registry mode). #764 review P2.
    email: str | None = None
    # Epic #529 copy-attribution beacon (analytics-only, NEVER persisted):
    # welcome.html fires this on copy with the displayed key. Enums match
    # #235's artifact_copied schema verbatim (align cycle-3 conformance).
    harness: str | None = None   # "claude"|"codex"|"cursor"|"pi"
    section: str | None = None   # "config"|"prompt"|"both"|"setup"
    # #1893: persisted GitHub source-scope keys — registered so the keys
    # round-trip through the PATCH surface (parametrized registration test)
    # and the dashboard can persist + rehydrate the scope selectors.
    # [] = explicit clear (all repos) — a VALID value, never dropped.
    # (appended at class end for #1894 merge hygiene — keep append-only)
    github_issues_scope: list[str] | None = None
    github_docs_scope: list[dict] | None = None
    # #2001 (W5): FLOW keys DECLARED on the PATCH surface so a stray client
    # send is REJECTED loudly (403/422) instead of silently dropped — and
    # catalog-presented, the ONE step key a client may still PATCH (step-edge
    # MERGE — an optional record, never a completion requirement). Since #3913
    # (owner ruling 2026-09-20) NO dashboard path sends it: the fork card writes
    # only the fork (or its unsure marker), never a step, and the id stays
    # accepted for agent/external callers and for existing orgs' completed_steps. All other FLOW keys are
    # server-owned / checkpoint-owned on this surface.
    catalog_presented: bool | None = None
    harness_connected: bool | None = None
    first_points_filed: bool | None = None
    decide_completed: bool | None = None
    capture_disclosed: bool | None = None
    org_named: bool | None = None
    # #3451: ``connection-written`` is agent-only on the checkpoint surface —
    # declared here so a stray PATCH is REJECTED loudly (422
    # unknown_step_on_patch via _PATCH_REJECTED_STEP_FIELDS), never silently
    # dropped+reported like an unknown field.
    connection_written: bool | None = None
    fork: str | None = None
    compact: bool | None = None
    status: str | None = None
    version: int | None = None
    completed_steps: list[str] | None = None
    member_progress: dict | None = None
    last_decide_attempt: str | None = None
    # #2407: fork_unsure_at is a server-stamped FLOW key — declared here so
    # a stray PATCH is REJECTED loudly (403 server-owned) like the siblings.
    fork_unsure_at: str | None = None

    @model_validator(mode="before")
    @classmethod
    def _report_unknown_patch_fields(cls, data):
        """#3821 (the front door): pydantic's default ``extra='ignore'``
        drops an unknown PATCH field BEFORE `_update_onboarding_state` ever
        runs, so the router's new negative branch could never see it.

        This validator keeps the drop — it does NOT switch to
        ``extra='forbid'``, which would make an unknown client field an
        unconditional 422 (the owner ruled against unconditional
        user-facing refusals) — but makes it observable: the offending
        field name(s) are counted and reported through the same choke point.
        Strict mode raises."""
        if isinstance(data, dict):
            unknown = set(data) - set(cls.model_fields)
            if unknown:
                _report_unregistered("onboarding_state_patch",
                                     "unknown_field", unknown)
        return data


# #2001 (W5): PATCH-surface ownership table — which FLOW keys are rejected
# where (per-step write-surface ownership, scope pin 7/8).
#
# #3681: the capture-surface evidence keys are SERVER-OWNED. A receipt
# (``session_capture_receipt[_harness]``), a per-harness last-error, and an
# install probe are all observations the server stamps — a client PATCH could
# otherwise fabricate the receipt ``captureStatus.js`` reads to decide the
# capture sentence's TENSE, producing the present-tense claim with nothing
# filed (the same false-claim class as #3671, one key further down). Derived
# from the canonical harness value set so a new harness cannot silently
# re-open the surface; the bare (harness-less) receipt is the legacy
# no-harness hooks' member AND the session-JWT (browser) lane's member — a
# session capture proves a capture happened, not a harness.
def _capture_server_owned_keys() -> set[str]:
    """The DERIVATION behind ``_CAPTURE_SERVER_OWNED_KEYS`` (#3681).

    Kept CALLABLE (not inlined into the constant) so the registration-table
    derivation is testable: a test that merely compares two filters of the
    SAME frozen table cannot distinguish derivation from coincidence — a
    hand-listed pair would satisfy it. Re-running this over an EXTENDED
    registration table proves a newly registered harness becomes
    server-owned (``tests/test_onboarding_truth_surface.py``).

    The install probes are DERIVED from the registration table
    (``_ALLOWED_STATE_KEYS`` ← ``_ONBOARDING_DEFAULT_STATE``), so a harness
    that registers an ``install_probe_{h}`` key is server-owned the moment it
    is registered — a literal pair would silently re-open a client-writable
    evidence key for the next harness (review P2)."""
    return {
        "session_capture_receipt",
        *{f"session_capture_receipt_{h}" for h in _SESSION_HARNESS_VALUES},
        *{f"session_capture_last_error_{h}" for h in _SESSION_HARNESS_VALUES},
        *{k for k in _ALLOWED_STATE_KEYS if k.startswith("install_probe_")},
    }


_CAPTURE_SERVER_OWNED_KEYS = _capture_server_owned_keys()
_PATCH_SERVER_OWNED_KEYS = {
    "fork", "compact", "status", "version",
    "completed_steps", "member_progress", "last_decide_attempt",
    "fork_unsure_at",
} | _CAPTURE_SERVER_OWNED_KEYS
_PATCH_REJECTED_STEP_FIELDS = {
    "harness_connected", "first_points_filed", "decide_completed",
    "capture_disclosed", "org_named", "connection_written",
}


@app.get("/v1/capabilities", response_model=dict)
async def get_capabilities(org: dict = Depends(get_current_org_session_ungated)):  # noqa: B008
    """Return the pullable builder capability catalog (#2004 W8, epic I-7).

    The indexers+extractors registry rows from tool_registry.py
    ``CAPABILITY_CATALOG`` (R2-9 — no new infra): one canonical list for the
    registry endpoint AND the dashboard's build-path catalog read (W8
    replaced W1's static placeholder source with this endpoint; the BUILD
    fork pick records the FORK ONLY — since #3913 (owner ruling 2026-09-20)
    no dashboard path writes catalog-presented, and the id stays accepted for
    agent/external callers. Presentation only, never a billing gate, never a
    build-completion requirement). Org-independent static
    registry data (no graph
    touch — never 'unavailable'); dual-auth like the onboarding state reads.

    Contract: ``200 {modules: [{name, kind: indexer|extractor, description,
    available}]}`` — names/descriptions are the presented copy; every named
    module file carries the catalog-reference note (W8b sweep)."""
    from tortoise.tool_registry import capability_catalog
    del org  # auth-context presence only — the catalog is org-independent
    return {"modules": capability_catalog()}


@app.get("/v1/onboarding/state", response_model=OnboardingStateResponse)
async def get_onboarding_state(org: dict = Depends(get_current_org_session_ungated)):  # noqa: B008
    """Return the org's onboarding progress + org email.

    #1828: dual-auth (session JWT OR tt_ key) — the dashboard re-entry card
    reads on the session (it already calls this with useSession: true), so it
    renders without a fresh bootstrap mint. #1828 review P1: ungated — the
    #1148 dashboard-login gate stays scoped to the management set (this is
    an overview read)."""
    # C5 #2114: onboarding state reads the DEFAULT graph — org-level surface.
    _reject_graph_bound_org_surface(org, "onboarding")
    # #4625: this route is a declared READ of the issue, not the write-path
    # residual — BOTH of its legs block (the projection read opens the graph /
    # hits PostgREST; `_org_email` reads `teams.email`, or the registry Team
    # node in selfhost), so neither may run on the event loop. The projection
    # rides its #2924 off-loop wrapper; the email read rides `asyncio.to_thread`
    # — the same short-read hand-off `list_points` / the capture probe use,
    # which (unlike `_cp_offload`) does not put a registry graph open on the
    # auth pool nor impose its fail-closed 503 on this read.
    return {
        "onboarding": await _get_onboarding_projection_off_loop(org["org_id"]),
        "email": await asyncio.to_thread(_org_email, org["org_id"]),
    }


@app.patch("/v1/onboarding/state", response_model=OnboardingStateResponse)
async def patch_onboarding_state(body: OnboardingStatePatchRequest,
                                org: dict = Depends(get_current_org_session_ungated)):  # noqa: B008
    """Merge provided onboarding fields into the org's state.

    #1828 review P3: same non-gated dual-auth as GET /v1/onboarding/state —
    the dashboard calls this with useSession: true (session-only users got
    401 under the old get_current_org key-only auth)."""
    # C5 #2114: onboarding state lives on the DEFAULT graph + the registry
    # Org node — a graph-bound key writing it would be a cross-graph write.
    _reject_graph_bound_org_surface(org, "onboarding")
    updates = {k: v for k, v in body.model_dump().items() if v is not None}
    # #1727 (Task 11): translate underscore PATCH fields back to hyphenated
    # per-harness state keys (pydantic cannot carry hyphens; the allowlist
    # filter would silently drop the underscore form).
    for field, state_key in _PATCH_FIELD_TO_STATE_KEY.items():
        if field in updates:
            updates[state_key] = updates.pop(field)
    email = updates.pop("email", None)  # state keys only — email is a orgs column
    # #1877 (security P1): org_created is SERVER-authoritative — the
    # create_onboarding_org re-entry guard reads it, so the client must
    # never reset it via this PATCH surface (a reset would re-open the
    # unlimited-free-sub-org bypass). Stripped here, like email.
    updates.pop("org_created", None)
    # Epic #529 copy-attribution beacon: analytics-only fields — pop before
    # the state merge (email pattern) and emit artifact_copied for enum-valid
    # pairs; invalid values still emit no event and change no state, so IN
    # NORMAL MODE a stale or malformed beacon cannot pollute state. #3821:
    # the rejection is now REPORTED instead of vanishing without an observer —
    # and because this raise is in the endpoint BODY (not a pydantic
    # validator) strict mode turns it into a 500, which is why strict is off
    # by default and never set in production.
    harness = updates.pop("harness", None)
    section = updates.pop("section", None)
    if harness in _HARNESS_ANALYTICS_VALUES and section in _SECTION_ANALYTICS_VALUES:
        # #3498/#4015: the analytics write builds a fresh httpx.Client per
        # event — a blocking PostgREST call; off the loop via the shared entry
        # point.
        await _emit_analytics_off_loop(
            org["org_id"], "artifact_copied",
            {"harness": harness, "section": section})
    elif harness is not None or section is not None:
        # #3821: an enum-invalid beacon used to produce NO event and NO
        # observer — indistinguishable from a beacon that never fired. The
        # event still does not fire (the enum check is unchanged); the
        # rejected value(s) are now reported.
        _report_unregistered(
            "artifact_copied", "invalid_enum",
            {name for name, value, allowed in (
                ("harness", harness, _HARNESS_ANALYTICS_VALUES),
                ("section", section, _SECTION_ANALYTICS_VALUES))
             if value is not None and value not in allowed})
    # #1997 (W1): accept-and-drop (plan T7) — a client PATCH
    # onboarding_complete on a NODE-PRESENT org is DROPPED (accepted 200;
    # the echo is node-governed — the legacy jsonb flag is inert there).
    # Node-absent orgs (grandfathered pre-backfill) keep the jsonb writer
    # (their fallback). Graph-down → keep the jsonb writer: the node's
    # presence cannot be confirmed, and dropping would lose the client's
    # intent against the legacy fallback path.
    if (_ACCEPT_AND_DROP and "onboarding_complete" in updates
            # #3718 residual 2 (review): `_graph_has_org_namespace` reads the
            # server-wide graph list through the registry projection — sync
            # FalkorDB I/O on this hot PATCH path, so off-load it too.
            and await asyncio.to_thread(
                _graph_has_org_namespace, org["org_id"])):
        try:
            # review (#1997): the SDK is explicitly closed (the projection
            # handle leaks a connection per PATCH otherwise — the writers'
            # _org_proj leak is pre-existing, but this block is on the hot
            # PATCH path and must not add to it).
            # Open the name the guard verified — a legacy `team_{org_id}` org
            # would otherwise be read on a minted, absent `org_{org_id}` (pin
            # 4). None (probe failed / not listed) → the inline construction,
            # unchanged. Closed in the finally below either way.
            _node_sdk = (_open_org_graph_sdk(org["org_id"])
                         or _make_sdk(namespace=org["org_id"]))
            # The WORKER owns the close: it runs in the worker's own
            # ``finally``, so the SDK is closed exactly once there whether the
            # read succeeds, raises, or the request is cancelled (the worker
            # keeps running — CPython #87185). A loop-side ``finally: close()``
            # after the await would instead tear the projection down under a
            # worker still inside the read on cancellation, and gating that
            # close on a completion flag would leak the connection on the
            # cancel path (both regression shapes caught in #3718 review).
            def _read_node():
                try:
                    return _os.read_onboarding_node(
                        _node_sdk._get_proj(), org["org_id"])
                finally:
                    _node_sdk.close()

            _node = await asyncio.to_thread(_read_node)
        except Exception:
            _node = None
        if _node is not None:
            updates.pop("onboarding_complete")
    # #1893: validate the persisted source-scope keys at the PATCH boundary
    # (400 on invalid; valid values stored in NORMALIZED form — issues
    # strip/dedupe, docs ""/None branch → null; [] = explicit clear).
    updates = _validate_scope_payload(updates)
    # #2001 (W5): per-key-type write-surface ownership at the PATCH
    # boundary — server-owned FLOW keys 403, agent-step keys 422, the one
    # client-writable step (catalog-presented) MERGEs the step edge. Since
    # #3913 the dashboard no longer sends it; the surface stays open for
    # agent/external callers.
    _sent_owned = [k for k in _PATCH_SERVER_OWNED_KEYS if k in updates]
    if _sent_owned:
        raise HTTPException(
            status_code=403,
            detail={"message": "server_owned_key", "keys": _sent_owned},
        )
    _sent_steps = [k for k in _PATCH_REJECTED_STEP_FIELDS if k in updates]
    if _sent_steps:
        raise HTTPException(
            status_code=422,
            detail={"message": "unknown_step_on_patch", "keys": _sent_steps},
        )
    catalog = updates.pop("catalog_presented", None)
    if catalog is True and not _graph_available(org["org_id"]):
        # FLOW-bearing write: fail-loud when the graph is down (503 BEFORE
        # any write — retry-safe).
        raise HTTPException(
            status_code=503,
            detail="Onboarding graph unavailable — retry later",
        )
    # Mixed-key PATCH: jsonb-first, graph-second (scope pin 7) — a graph
    # failure after a jsonb success surfaces as a 500 fail-closed and the
    # retry converges (MERGE idempotent; no lost FLOW keys).
    state = _update_onboarding_state(org["org_id"], **updates)
    if catalog is True:
        try:
            # grandfathered no-re-onboarding: seed the create-on-write node's
            # status from the legacy jsonb flag (PATCH catalog is a FLOW
            # write and can be a grandfathered org's first one).
            legacy_mirror = bool(_get_onboarding_state(
                org["org_id"]).get("onboarding_complete"))
            _os.write_completed_step(
                _org_proj(org["org_id"]), org["org_id"],
                "catalog-presented", status_from_mirror=legacy_mirror)
            _maybe_apply_completion(org["org_id"])
        except Exception:
            raise HTTPException(
                status_code=500,
                detail="Onboarding update failed — retry-safe") from None
        # echo the POST-write projection (the router's echo was pre-write)
        state = _get_onboarding_projection(org["org_id"])
    # onboarding_complete stays a LEGACY jsonb key through the carve-out
    # (accept-and-drop activates post-W1, #1997) — the grandfathered-window
    # guard keeps wizard-completed orgs complete in the meantime.
    # #1765 review (onboarding dual-auth): a SESSION-authed call's email
    # belongs on the USER anchor (auth.users — managed via the profile
    # flow), never teams.email; only the KEY-authed (welcome beacon)
    # path keeps the sanctioned CONTACT-field write.
    if email is not None and not org.get("session_user_id"):
        _write_org_email(org["org_id"], email)
    return {
        "onboarding": state,
        "email": _org_email(org["org_id"]),
    }


# #2001 (W5): agent/internal checkpoint — the ONLY surface for the agent
# steps + fork/compact set-once + last_decide_attempt LWW + member_progress.
# Per-step write-surface ownership (scope pin 8): the PATCH surface accepts
# operational keys + catalog-presented (no dashboard path has sent the latter
# since #3913); agents checkpoint everything else.
#
# #3671: the steps a SESSION JWT (dashboard/browser) may checkpoint. A NAMED
# allowlist — not "everything except the server-observed set" — so a future
# step added to _CHECKPOINT_STEPS defaults to agent-only (fail-closed).
#
# It is EMPTY: no dashboard path has sent a STEP since the #3913 owner ruling
# (2026-09-20), and every ``step`` write now requires an agent credential —
# the fail-closed default this surface exists to establish. The mechanism
# stays (a future exemption, if one is ever decided, is declared HERE and
# nowhere else; the predicate below reads the allowlist, never the reverse).
_DASHBOARD_WRITABLE_STEPS: frozenset[str] = frozenset()
_CHECKPOINT_STEPS: frozenset[str] = frozenset({
    "connection-written",     # #3451: MCP config WRITTEN (client-observed;
                              # the server cannot see the user's config file)
    "harness-connected",      # W2: harness connected
    "first-points-filed",     # W3: org-anchor Subject filed (seed)
    "decide-completed",       # W3: real decide protocol
    "capture-disclosed",      # W6: memory-capture disclosure
    "catalog-presented",      # W8: catalog presented (agent path)
})


class OnboardingCheckpointRequest(BaseModel):
    """One FLOW operation per call (extra="forbid" — an unknown field is a
    422, never a silent ignore)."""
    step: str | None = None
    fork: str | None = None
    compact: bool | None = None
    last_decide_attempt: str | None = None
    member_progress: dict | None = None
    status: str | None = None
    # #2407: "not sure yet — decide later" fork-card answer — a MARKER
    # (true) that records fork_unsure_at server-side WITHOUT consuming the
    # set-once fork value. Never a timestamp from the client (server-stamped).
    fork_unsure_at: bool | None = None
    model_config = {"extra": "forbid"}


@app.post("/v1/onboarding/state/checkpoint",
          response_model=dict)
async def onboarding_checkpoint(body: OnboardingCheckpointRequest,
                                org: dict = Depends(get_current_org_session_ungated)):  # noqa: B008
    """Checkpoint a FLOW-state operation for the AUTH-CONTEXT org.

    Dual-auth (session JWT OR tt_ key) like GET/PATCH; the org ALWAYS
    comes from the auth context — the body never carries org_id (F2).

    Contract (scope pin 8):
    - step ∈ {connection-written, harness-connected, first-points-filed,
      decide-completed, capture-disclosed, catalog-presented} — keyed-MERGE,
      first-write-wins
      (replay → noop), unknown step → 422.
      #3671: EVERY step write requires an AGENT credential — a session-JWT
      step write is refused 403 ``agent_credential_required`` (no dashboard
      path has sent a step since the #3913 owner ruling; see
      ``_DASHBOARD_WRITABLE_STEPS``); the non-step FLOW ops below keep the
      dual-auth lane.
    - fork/compact → set-once (first write wins; same-value replay 200;
      changed → 409).
    - fork_unsure_at (true) → #2407 "not sure yet — decide later": records
      the fork-card deferral (server-stamped ISO timestamp) WITHOUT
      consuming the set-once fork — fork stays NULL so the card stays
      answerable; repeat → 200 (re-stamp); fork already set or compact org
      → 409 (never asked / already answered).
    - last_decide_attempt → LWW; 'failed' is SKIPPED once decide-completed
      exists (dismissal alone never completes).
    - member_progress → {user_id: [steps]} user-scoped map-merge;
      SESSION-only: a key-authed call (no session user) must send a
      UUID user_id, else 403 (no cross-user forgery).
    - status → 403 (server-owned; gate-written, monotonic).
    - graph down → 503 BEFORE any write (fail-loud, retry-safe).
    - response {created_steps, noop_steps} = the W11 edge-new-creation
      signal (#2001 exposes; #2006 emits events).
    - post-write fork-aware gate eval (monotonic; grandfathered no-op).
    """
    # C5 #2114 (re-review P2): checkpoint writes onboarding FLOW state into
    # the org's DEFAULT graph via _org_proj — a graph-bound key writing it
    # would be a cross-graph write (org-level surface, like the siblings).
    _reject_graph_bound_org_surface(org, "onboarding checkpoint")
    org_id = org["org_id"]
    # one operation per call
    present = [
        name for name, val in (
            ("step", body.step), ("fork", body.fork),
            ("compact", body.compact),
            ("last_decide_attempt", body.last_decide_attempt),
            ("member_progress", body.member_progress),
            ("fork_unsure_at", body.fork_unsure_at),
        ) if val is not None
    ]
    if len(present) > 1:
        raise HTTPException(status_code=400,
                            detail="One operation per checkpoint call")
    if body.status is not None:
        raise HTTPException(
            status_code=403,
            detail={"message": "server_owned_key", "keys": ["status"]})
    # #3671 (assertion ≠ observation): a SERVER-OBSERVED step is a fact only
    # the server can witness (an agent connected / filed / decided / was
    # disclosed). A session JWT is the dashboard/browser lane — it observes
    # no agent, so asserting one of those from it is exactly the false claim
    # lane B3 deleted, merely moved from the client into the server. Only an
    # AGENT credential (tt_/tk_ key, MCP/OAuth) may write them; a session
    # write is REFUSED loudly (403) rather than silently accepted.
    #
    # ``_DASHBOARD_WRITABLE_STEPS`` is empty, so the gate covers EVERY step —
    # ``catalog-presented`` included. Non-step FLOW ops
    # (fork/compact/member_progress/fork_unsure_at) keep their existing lanes
    # — the dashboard legitimately records the human's fork answer.
    if (body.step is not None
            and body.step not in _DASHBOARD_WRITABLE_STEPS
            and not _credential_is_agent(org)):
        raise HTTPException(
            status_code=403,
            detail={"message": "agent_credential_required",
                    "step": body.step})
    if not _graph_available(org_id):
        raise HTTPException(status_code=503,
                            detail="Onboarding graph unavailable — retry later")
    proj = _org_proj(org_id)
    created_steps: list[str] = []
    noop_steps: list[str] = []
    try:
        # grandfathered no-re-onboarding (pin 12): the legacy jsonb
        # onboarding_complete flag seeds the create-on-write node's status
        # so a legacy-wizard-completed org's FIRST FLOW write never flips
        # the wire to incomplete (the backfill alone is a race window).
        legacy_mirror = bool(_get_onboarding_state(org_id).get(
            "onboarding_complete"))
        if body.step is not None:
            if body.step not in _CHECKPOINT_STEPS:
                raise HTTPException(status_code=422,
                                    detail={"message": "unknown_step",
                                            "step": body.step})
            res = _os.write_completed_step(
                proj, org_id, body.step, status_from_mirror=legacy_mirror)
            (created_steps if res["created"] else noop_steps).append(body.step)
        elif body.fork is not None:
            if body.fork not in _os.FORK_VALUES:
                raise HTTPException(status_code=422,
                                    detail="fork must be 'self' or 'build'")
            outcome = _os.write_fork(proj, org_id, body.fork,
                                     status_from_mirror=legacy_mirror)
            if outcome == "conflict":
                raise HTTPException(
                    status_code=409,
                    detail={"message": "fork_already_set"})
            # #2407 invariant: the unsure marker is meaningful only while
            # fork IS NULL — a consumed fork clears it (the org answered).
            _os.clear_fork_unsure_at(proj, org_id)
        elif body.fork_unsure_at is not None:
            if body.fork_unsure_at is not True:
                raise HTTPException(
                    status_code=422,
                    detail={"message": "invalid_fork_unsure_at",
                            "expects": True})
            at = datetime.now(UTC).isoformat()
            outcome = _os.write_fork_unsure_at(
                proj, org_id, at, status_from_mirror=legacy_mirror)
            if outcome == "conflict":
                raise HTTPException(
                    status_code=409,
                    detail={"message": "fork_already_set"})
        elif body.compact is not None:
            outcome = _os.write_compact(proj, org_id, bool(body.compact),
                                        status_from_mirror=legacy_mirror)
            if outcome == "conflict":
                raise HTTPException(
                    status_code=409,
                    detail={"message": "compact_already_set"})
        elif body.last_decide_attempt is not None:
            if body.last_decide_attempt not in ("failed", "dismissed"):
                raise HTTPException(
                    status_code=422,
                    detail={"message": "invalid_last_decide_attempt"})
            _os.write_last_decide_attempt(
                proj, org_id, body.last_decide_attempt,
                status_from_mirror=legacy_mirror)
        elif body.member_progress is not None:
            # session-only: a key-authed call (no session user) must present
            # a UUID user_id; a SESSION-authed call must write ONLY its own
            # user_id (no cross-user forgery either way).
            import uuid as _uuid
            session_uid = org.get("session_user_id")
            for uid in body.member_progress:
                if session_uid:
                    if uid != session_uid:
                        raise HTTPException(
                            status_code=403,
                            detail={"message": "member_progress_self_only"})
                else:
                    try:
                        _uuid.UUID(uid)
                    except (ValueError, TypeError, AttributeError):
                        raise HTTPException(
                            status_code=403,
                            detail={"message": "key_auth_session_required"}) from None
                steps = body.member_progress[uid]
                if not isinstance(steps, list) or not all(
                        _os.validate_step_id(s) for s in steps):
                    raise HTTPException(
                        status_code=422,
                        detail={"message": "invalid_member_progress"})
            merged: dict = {}
            for uid, steps in body.member_progress.items():
                merged.update(_os.write_member_progress(
                    proj, org_id, uid, steps,
                    status_from_mirror=legacy_mirror))
        # post-write fork-aware gate eval (monotonic) — step/fork/compact
        # writes only (never member_progress; fork_unsure_at records no
        # progress and its gate is unsatisfiable-by-design until answered)
        if body.step is not None or body.fork is not None or body.compact is not None:
            _maybe_apply_completion(org_id)
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=500,
                            detail="Checkpoint failed — retry-safe") from None
    # #2006 (W11): funnel events for the step edges THIS call newly created.
    # ``created_steps`` already carries the structural gate — a replay
    # (created=False) is silent, and the edge-creation transition is
    # exact-once per edge creation, so this survives restarts and multiple
    # workers with no in-process set. Emission sits OUTSIDE the write-path
    # try/except above: telemetry can never turn a committed checkpoint into
    # a 500.
    if created_steps:
        # Off the loop (the analytics.py contract for async handlers) and
        # guarded HERE too: the write above has already committed, so even a
        # bug in the emitter itself must not turn a committed checkpoint into
        # a 500 (R19 — telemetry never degrades the API).
        try:  # noqa: SIM105
            await asyncio.to_thread(
                _emit_onboarding_step_events, created_steps,
                distinct_id=_onboarding_distinct_id(org_id, org),
                org_id=org_id, source="checkpoint")
        except Exception:
            pass
    return {
        "created_steps": created_steps,
        "noop_steps": noop_steps,
        "onboarding": _get_onboarding_projection(org_id),
    }


# ── #1999 (W3): interactive ontology-precise seed ─────────────────────
# POST /v1/onboarding/seed — files exactly two Subjects (Organization/
# organization + User/naturalPerson linked memberOf, DM-3) from auth-
# context anchor data (teams.name + org email + session user), with
# collision detection (never silent merge of distinct identities),
# person→naturalPerson normalization, never-invented identity (email-
# derived person name is a PROPOSAL requiring confirmation), and the
# fork-aware completion gate (WF-2). The seed core lives in
# tortoise/onboarding/seed.py (graph-agnostic — W12's self-hosted path
# reuses it); this module owns the hosted anchor-data resolution.


def _org_name(org_id: str) -> str | None:
    """Org display name from the control plane (teams.name / Org node)."""
    from tortoise.supabase_control import (
        get_control_plane,
        is_supabase_enabled,
    )
    from tortoise.supabase_control import (
        org_name as _sb_org_name,
    )
    if is_supabase_enabled():
        return _sb_org_name(get_control_plane(), org_id)
    sdk = _make_sdk(namespace="registry")
    try:
        rows = sdk._get_registry().query(
            "MATCH (t:Team {id: $id}) RETURN t.name",
            params={"id": org_id}).result_set
        return rows[0][0] if rows else None
    finally:
        sdk.close()


class _OrgSeedSurface:
    """Duck-typed seed surface over the org-scoped SDK: find_subject_by_name
    needs raw Cypher (projection), entity writes need the SDK (SubjectAdded
    events + journal + embedding + #452 name-MERGE)."""

    def __init__(self, sdk):
        self._sdk = sdk

    def query(self, cypher, **params):
        return self._sdk._get_proj().query(cypher, **params)

    def create_subject(self, name, subjectKind="other", **props):
        return self._sdk.create_subject(name, subjectKind=subjectKind, **props)

    def create_edge(self, relation, from_id, to_id):
        return self._sdk.create_edge(relation, from_id, to_id)


def _next_onboarding_step(org_id: str, proj) -> str | None:
    """First incomplete fork-aware step after the seed (the decide nudge
    target): self fork → decide; build/compact → harness-connected (the
    #3913 build gate is the two observed acts; first-points-filed is written
    by the seed itself, so after a successful seed only harness-connected can
    still be open). 'done' when the gate already satisfied the status."""
    node = _os.read_onboarding_node(proj, org_id)
    if node is None or node.get("status") == _os.STATUS_COMPLETE:
        return "done"
    steps = set(_os.completed_steps(proj, org_id))
    # #3913: build no longer trails catalog-presented — build and compact share
    # the reduced post-seed checklist (the seed files first-points-filed).
    if bool(node.get("compact")) or node.get("fork") == _os.FORK_BUILD:
        order = ("harness-connected",)
    else:
        order = ("harness-connected", "decide-completed")
    for step in order:
        if step not in steps:
            return step
    return "done"


def _run_onboarding_seed(org_id: str, *, org_name: str | None = None,
                         person_name: str | None = None,
                         person_user_id: str | None = None,
                         person_email: str | None = None) -> dict:
    """The W3 interactive seed runner (shared by the REST endpoint + the
    MCP tool). Hosted anchor data: org display name ← explicit org_name or
    teams.name; person ← explicit person_name (user-confirmed) or
    email-prefix derivation (PROPOSAL — never silently filed); user_id /
    email are the stable identity refs (DM-3).

    Contract (WF-2 / DM-3): gaps/collisions → NO graph writes
    (all-or-nothing — a disambiguation round never leaves a half-seed);
    seeded → two Subjects (compact: org-anchor seed-lite only) + memberOf
    + onboards edge/org_subject_id + first-points-filed step edge
    (created-signal) + fork-aware gate eval. Graph-down → 503 fail-loud
    (FLOW-bearing write, retry-safe)."""
    from tortoise.onboarding import seed as _seed
    if not _graph_available(org_id):
        raise HTTPException(status_code=503,
                            detail="Onboarding graph unavailable — retry later")
    proj = _org_proj(org_id)
    node = _os.read_onboarding_node(proj, org_id)
    compact = bool((node or {}).get("compact")) if node is not None else False

    org_display = (org_name or "").strip()
    org_source = "provided" if org_display else "teams.name"
    if not org_display:
        org_display = _org_name(org_id) or ""
    include_person = not compact
    person_provided = (person_name or "").strip()
    person_source = "provided" if person_provided else None

    # never-invented-identity gate: gaps → ask (zero writes)
    gaps: list[dict] = []
    if not org_display:
        gaps.append({"field": "org_name", "source": "ask",
                      "reason": "no org display name on the control plane"})
    if include_person and not person_provided:
        derived = (_seed.derive_display_name_from_email(person_email)
                   if person_email else None)
        if derived:
            person_source = "email-derived"
            gaps.append({
                "field": "person_name", "source": "email-derived",
                "derived": derived,
                "reason": ("display_name is not exposed — confirm the "
                            "email-prefix name before filing"),
            })
        else:
            gaps.append({"field": "person_name", "source": "ask",
                          "reason": "no email-prefix name derivable"})
    if gaps:
        return {"status": "needs_confirmation", "gaps": gaps,
                "org_name": org_display or None,
                "org_name_source": org_source if org_display else None,
                "person_name_source": person_source}

    sdk = _make_sdk(namespace=org_id)
    try:
        surface = _OrgSeedSurface(sdk)
        try:
            report = _seed.seed_onboarding_anchors(
                surface, org_name=org_display, org_id=org_id,
                person_name=person_provided or None,
                user_id=person_user_id, person_email=person_email,
                include_person=include_person)
        except _seed.SubjectCollision as exc:
            return {
                "status": "collision",
                "collisions": [{
                    "kind": exc.kind, "name": exc.name,
                    "existing_id": exc.existing_id, "reason": exc.reason,
                    "existing_refs": exc.refs,
                    "ambiguous": exc.ambiguous,
                }],
                "org_name": org_display,
                "org_name_source": org_source,
                "person_name_source": person_source,
                "question": (
                    (f"A Subject named {exc.name!r} is held by more than "
                     "one live Subject, so the seed cannot resolve it to a "
                     "single identity. Provide a disambiguated name "
                     "(suffix/canonical key) — a carrier is never picked "
                     "by guess.")
                    if exc.ambiguous else
                    (f"A Subject named {exc.name!r} already exists "
                     "and is not this org/user. Provide a "
                     "disambiguated name (suffix/canonical key) — "
                     "distinct identities are never merged.")),
            }
        # node ↔ anchor link (DM-1) + first-points-filed step edge + gate
        legacy_mirror = bool(_get_onboarding_state(org_id).get(
            "onboarding_complete"))
        org_subject = report["org_subject"]
        onboards = _os.write_onboards_edge(proj, org_id, org_subject["id"])
        step = _os.write_completed_step(
            proj, org_id, "first-points-filed",
            status_from_mirror=legacy_mirror)
        if step.get("created"):
            # #2006 (W11): the edge's new creation is the once-per-org fact
            # (a replay reports created=False and emits nothing).
            _emit_onboarding_step_events(
                ["first-points-filed"],
                distinct_id=_onboarding_distinct_id(
                    org_id, user_id=person_user_id),
                org_id=org_id, source="seed")
        _maybe_apply_completion(org_id)
    finally:
        sdk.close()
    return {
        "status": "seeded",
        "org_name": org_display,
        "org_name_source": org_source,
        "person_name_source": person_source,
        "org_subject": report["org_subject"],
        "user_subject": report["user_subject"],
        "org_created": report["org_created"],
        "person_created": report["person_created"],
        "org_kind_normalized": report["org_kind_normalized"],
        "person_kind_normalized": report["person_kind_normalized"],
        "member_of": report["member_of"],
        "onboards": onboards,
        "steps": {"first-points-filed": step},
        "next": _next_onboarding_step(org_id, _org_proj(org_id)),
        "onboarding": _get_onboarding_projection(org_id),
    }


class OnboardingSeedRequest(BaseModel):
    """Interactive seed — explicit (user-confirmed) names override anchor
    data. ``extra="forbid"``: unknown fields are a 422, never a silent
    ignore."""
    org_name: str | None = Field(default=None, max_length=200)
    person_name: str | None = Field(default=None, max_length=200)
    model_config = {"extra": "forbid"}


@app.post("/v1/onboarding/seed", response_model=dict)
async def onboarding_seed(body: OnboardingSeedRequest,
                          org: dict = Depends(get_current_org_session_ungated)):  # noqa: B008
    """File the two onboarding anchor Subjects (Organization/organization +
    User/naturalPerson linked memberOf) from auth-context anchor data.

    Interactive (WF-2): call without names to discover gaps (email-derived
    person name → needs_confirmation) or collisions (same-name Subject that
    is not this org/user → disambiguation); call with explicit
    user-confirmed names to file. Gaps/collisions write NOTHING — never
    invented identity, never silent merge. Seeded → two Subjects + memberOf
    + onboards edge + first-points-filed step edge + fork-aware gate eval.

    Dual-auth (session JWT OR tt_ key) like the checkpoint; the org always
    comes from the auth context. """
    org_id = org["org_id"]
    # C5 #2114: seed WRITES the two anchor Subjects into the DEFAULT graph
    # (org-level onboarding state, main-side #2156) — write scope required
    # + graph-bound keys rejected (cross-graph write prevention).
    _require_scope(org, "graphs:write", "onboarding seed")
    _reject_graph_bound_org_surface(org, "onboarding seed")
    # identity refs from the auth context (never client-supplied):
    # session_user_id is the JWT user UUID; created_by is a user UUID on
    # session-minted keys but the EMAIL on register-lane keys (legacy) — an
    # email must never ride the user_id ref (it would tag the person anchor
    # with a bogus identity and break the collision predicate).
    person_user_id = org.get("session_user_id") or org.get("created_by")
    if person_user_id in (None, "api") or "@" in str(person_user_id):
        person_user_id = None
    try:
        return _run_onboarding_seed(
            org_id, org_name=body.org_name, person_name=body.person_name,
            person_user_id=person_user_id,
            person_email=org.get("email"))
    except HTTPException:
        raise
    except Exception:
        import logging
        logging.getLogger("tortoise.api").exception(
            "onboarding seed failed (team=%s)", org_id)
        raise HTTPException(status_code=500,
                            detail="Onboarding seed failed — retry-safe") from None


# ── #2360: provisioning-time REAL starter seed (supersedes the demo auto-seed) ──
# The tenant-provision Edge Function used to auto-seed 12 fake demo Points +
# a _demo_sentinel into EVERY fresh org (/internal/demo) so new users "see a
# populated graph immediately" — sample content the Overview digest then
# counted as the user's own filings ('13 points filed' on a brand-new org).
# The #2360 re-spec replaces that sample data with REAL data that kickstarts
# the process: the signing-up user as a naturalPerson Subject and their
# Organization as an organization Subject, the two CONNECTED (memberOf) — the
# canonical two-anchor structure from tortoise/onboarding/seed.py (same
# module the interactive W3 seed uses; replay is idempotent and never
# merges a distinct identity). No demo Point is ever written on this path.
#
# Never-invented-identity (DM-3): the person anchor is filed ONLY when the
# provisioning context carries the user's own display name (auth metadata —
# user-provided at signup/OAuth). When only an email-prefix derivation would
# be available, the starter seed files the org-anchor Subject only (the org
# name IS user-confirmed at org-create) and leaves the first-points-filed
# step pending — the connect-time interactive W3 seed then files the person
# Subject + memberOf with a user-confirmed name. Both legs are REAL data;
# nothing is ever invented or silently derived on the provisioning path.

def _run_starter_seed(org_id: str, *, org_name: str | None = None,
                      person_name: str | None = None,
                      person_user_id: str | None = None,
                      person_email: str | None = None) -> dict:
    """The provisioning-time real starter seed (internal, #2360).

    W3-parity runner over the canonical seed core: files the org-anchor
    Subject (organization, org_id=org_id) ALWAYS (the org display name is
    user-confirmed at org-create), and the person-anchor Subject
    (naturalPerson, user_id/email) + the memberOf link WHEN a user-provided
    display name is present. On success links the onboarding node (onboards
    edge / org_subject_id) and — when the person anchor was filed too (the
    full starter structure) — marks the first-points-filed seed step (W3
    semantics: the org-anchor seed). A pending step otherwise stays with the
    connect-time interactive seed (never-invented-identity). Idempotent:
    replay reuses the canonical anchors (created=False). Graph-down → 503
    fail-loud (retry-safe), mirroring the W3 runner."""
    from tortoise.onboarding import seed as _seed
    if not _graph_available(org_id):
        raise HTTPException(status_code=503,
                            detail="Onboarding graph unavailable — retry later")
    org_display = (org_name or "").strip()
    if not org_display:
        org_display = _org_name(org_id) or ""
    person = (person_name or "").strip() or None
    # never-invented-identity guard: no org display name on the control
    # plane → zero writes (the caller must name the org first).
    if not org_display:
        return {"status": "org_name_required", "org_id": org_id}
    # the person user_id ref is a real user UUID only — 'api'/email-shaped
    # values never ride the identity ref (W3 parity).
    if person_user_id in (None, "api") or "@" in str(person_user_id):
        person_user_id = None
    include_person = person is not None
    sdk = _make_sdk(namespace=org_id)
    try:
        proj = sdk._get_proj()
        surface = _OrgSeedSurface(sdk)
        try:
            report = _seed.seed_onboarding_anchors(
                surface, org_name=org_display, org_id=org_id,
                person_name=person, user_id=person_user_id,
                person_email=person_email, include_person=include_person)
        except _seed.SubjectCollision as exc:
            # A same-name Subject that is NOT this org/user (rare on a fresh
            # org) → surfaced, zero writes for that anchor, retry-safe. The
            # provisioning caller logs + keeps the org usable (mirrors the
            # W3 runner's all-or-nothing contract).
            return {
                "status": "collision",
                "collisions": [{
                    "kind": exc.kind, "name": exc.name,
                    "existing_id": exc.existing_id, "reason": exc.reason,
                    "existing_refs": exc.refs,
                    "ambiguous": exc.ambiguous,
                }],
                "org_name": org_display,
                "person_name_source": "provided" if include_person else None,
            }
        legacy_mirror = bool(_get_onboarding_state(org_id).get(
            "onboarding_complete"))
        org_subject = report["org_subject"]
        onboards = _os.write_onboards_edge(proj, org_id, org_subject["id"])
        step = None
        if include_person:
            step = _os.write_completed_step(
                proj, org_id, "first-points-filed",
                status_from_mirror=legacy_mirror)
            if step.get("created"):
                # #2006 (W11): provisioning-time seed step — same structural
                # gate as the interactive seed (only ONE of the two writers
                # can ever see created=True for a given org).
                _emit_onboarding_step_events(
                    ["first-points-filed"],
                    distinct_id=_onboarding_distinct_id(
                        org_id, user_id=person_user_id),
                    org_id=org_id, source="starter_seed")
        _maybe_apply_completion(org_id)
    finally:
        sdk.close()
    resp = {
        "status": "seeded",
        "org_id": org_id,
        "org_name": org_display,
        "org_subject": report["org_subject"],
        "org_created": report["org_created"],
        "org_kind_normalized": report["org_kind_normalized"],
        "onboards": onboards,
        "onboarding": _get_onboarding_projection(org_id),
    }
    if include_person:
        resp.update({
            "user_subject": report["user_subject"],
            "person_created": report["person_created"],
            "person_kind_normalized": report["person_kind_normalized"],
            "member_of": report["member_of"],
            "steps": {"first-points-filed": step},
        })
    return resp


@app.post("/internal/starter-seed")
async def starter_seed(request: Request):
    """Provisioning-time REAL starter seed (#2360) — internal key only.

    Called by the tenant-provision Edge Function right after provisioning a
    fresh org (replacing the old demo auto-seed). Files the signing-up user
    as a naturalPerson Subject and their Organization as an organization
    Subject, connected memberOf (canonical two-anchor seed,
    tortoise/onboarding/seed.py). Idempotent; never writes demo Points;
    never silently derives the person name (person_name is the user's own
    display name from the auth context; absent → org-anchor seed only).
    """
    _check_internal(request)
    raw = await _read_capped_body(request, _BODY_MAX_BYTES, _BODY_413_DETAIL)
    try:
        body = _json.loads(raw)
    except Exception:
        raise HTTPException(status_code=400,
                            detail="Invalid JSON body") from None
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="Invalid JSON body")
    org_id = body.get("org_id")
    if not org_id:
        raise HTTPException(status_code=400, detail="Missing org_id")
    try:
        return _run_starter_seed(
            org_id,
            org_name=(body.get("org_name") or None),
            person_name=(body.get("person_name") or None),
            person_user_id=(body.get("person_user_id") or None),
            person_email=(body.get("person_email") or None))
    except HTTPException:
        raise
    except Exception:
        import logging
        logging.getLogger("tortoise.api").exception(
            "starter seed failed (team=%s)", org_id)
        raise HTTPException(status_code=500,
                            detail="Starter seed failed — retry-safe") from None


@app.post("/v1/onboarding/session-recording", response_model=OnboardingStateResponse)
async def set_session_recording(body: dict, org: dict = Depends(get_current_org_session_ungated)):  # noqa: B008
    """Toggle automatic session recording (Q3 / Memory-sources sessions toggle).

    #1927: session_recording is the OPTIONAL OFF-SWITCH (default ON,
    ToS-covered) — not a consent gate. Writing ``enabled`` here flips the
    flag the capture pipeline checks (409 when off); ``capture_revised`` is
    written for backward-compatibility with the registered state keys (the
    exactly-once re-ask machinery it fed was removed with the gate).

    #1859 P3-3: converted from get_current_org (key-only) to the same
    non-gated dual-auth as GET/PATCH /v1/onboarding/state — the dashboard
    was rewired by #1728 to PATCH /v1/onboarding/state (session JWT), while
    the MCP tool registry (tortoise_onboarding_session_recording) still
    drives this endpoint with a tt_ key; both must work."""
    # C5 #2114 (review P2): the toggle writes onboarding state (registry/org
    # node) — org-level surface; graph-bound keys rejected (cross-graph
    # write prevention).
    _reject_graph_bound_org_surface(org, "session recording toggle")
    enabled = body.get("enabled")
    if not isinstance(enabled, bool):
        raise HTTPException(status_code=400, detail="'enabled' must be a boolean")
    state = _update_onboarding_state(org["org_id"],
                                     session_recording=enabled,
                                     capture_revised=True)
    # #1927 semantic drift: the off-switch fires question_answered for
    # continuity with existing analytics — toggle-off is NOT a consent
    # answer (the consent/re-ask machinery was removed).
    await _track_onboarding_event(org, "question_answered",
                                  question_id="session_recording",
                                  answer="yes" if enabled else "no")
    return {"onboarding": state}


@app.post("/v1/onboarding/team")
async def create_onboarding_org(body: dict,
                               org: dict = Depends(get_current_org_session)):  # noqa: B008
    """Create a sub-org for the user (Q5 hosted equivalent of tortoise_org_create).

    #765 (plan Task 8 writer inventory: demo/onboarding): Supabase mode
    routes the write through the atomic provision_org RPC. #1716: the
    sub-org is provisioned KEYLESS in BOTH lanes — no tt_ mint, no
    api_keys row (the old per-call mint was an unrecoverable dead
    credential: plaintext never returned, hash-only at rest, counted
    against max_api_keys, unclaimable #1082). The sub-org stays keyless
    until a session-key mint (POST /v1/session/key writes the row itself).
    #1748: the sub-org is provisioned on the USER path — the session user
    becomes the OWNER member (p_user_id=<session user>, p_identity=None;
    registry lane: owner Membership for the same user). The old
    anon-{uuid} identity was a permanent dead end: session-key mint
    resolves memberships by the session user's user_id, which the
    NULL-user identity row never matched — no key, no claim, no list, no
    delete. The registry path stays for selfhost."""
    name = (body.get("name") or "").strip()
    if not name or len(name) > 64:
        raise HTTPException(status_code=400, detail="name is required (max 64 chars)")
    import re
    if not re.match(r"^[a-zA-Z0-9][a-zA-Z0-9_ -]{0,63}$", name):
        raise HTTPException(status_code=400, detail="Invalid organization name")
    # #1748: the session user owns the sub-org. Session JWT →
    # session_user_id (get_current_org_session); key-auth → created_by
    # (the key creator's user UUID — session-minted bootstrap/recovery
    # keys carry it; the dashboard onboarding wizard authenticates with
    # exactly such a key). "api" / None → no real user → fail loudly
    # rather than provision an owner-less orphan (the #1716 dead end).
    owner_user_id = org.get("session_user_id") or org.get("created_by")
    if not owner_user_id or owner_user_id == "api":
        raise HTTPException(
            status_code=403,
            detail="A session user is required to create a sub-team — "
                   "sign in or mint a session key first",
        )
    # #1954: the re-entry guard is read-then-write — the guard read + the
    # provision + the org_created write all run under the per-user lock so
    # a concurrent double-call cannot both read org_created absent and mint
    # two sub-orgs.
    # #2323 (Option B backstop): the person-level #1877 entitlement now binds
    # this lane too. A free user (>=1 active free membership) can no longer
    # mint a second org through the onboarding lane; paid users pass through
    # (the count helper excludes paid orgs) — the sanctioned org-B door
    # survives for subscribers. Order pinned: marker-409 (anti-re-entry) →
    # count-402 → dup-name → mint, all under the per-user lock. The lane
    # re-checks the marker (belt) but never the count (single source: here).
    async with _org_create_lock(owner_user_id):
        onboarding_state = _get_onboarding_state(org["org_id"])
        if onboarding_state.get("org_created"):
            raise HTTPException(status_code=409, detail="Sub-team already created")
        # #2323/#2789: mode-aware OWNERSHIP helper (supabase
        # subscription_status; registry tier='free' proxy) — the same gate
        # POST /v1/organizations enforces, lane-uniform and now ownership-based (a
        # collaborator on someone else's free org can still create their own).
        # STRUCTURED detail (#2789) so the wizard lane renders the same
        # three-option dialog from `code`.
        _free_org_ids = await _owned_free_org_ids(owner_user_id)
        if _free_org_ids:
            raise HTTPException(
                status_code=402,
                detail=_one_free_org_detail(_free_org_ids[0]),
            )
        return await _create_onboarding_org_lane(org, name, owner_user_id)


async def _create_onboarding_org_lane(org: dict, name: str,
                                 owner_user_id: str) -> dict:
    """#1954: the onboarding sub-org lane — re-entry guard + provision +
    org_created write. MUST be called holding the caller's
    _org_create_lock (the guard is read-then-write; the lock is what makes
    a concurrent double-call mint exactly one sub-org).

    #3498: async so its analytics emit can be offloaded (the emit is a
    blocking PostgREST write); the caller's ``asyncio.Lock`` is held across
    the await, which is safe."""
    # NOTE (second-model P2, plan deviation): the plan's "reject non-UUID
    # created_by" step is NOT applied — the test fixtures use non-UUID ids
    # by design, and the provision RPC already maps a non-UUID uuid-column
    # insert to a 400 (never a 500); the helper shape-gates internally so
    # no new 500 path exists. Documented, not implemented.
    # #1877 (P0 fix): the onboarding lane had NO re-entry guard — a session
    # user could mint unlimited free sub-orgs by calling this endpoint
    # repeatedly, bypassing POST /v1/organizations. The wizard creates the sub-org
    # ONCE (org_created=True in the MAIN org's PERSISTED onboarding
    # state); a second call is blocked (409). Read the persisted state
    # (teams.onboarding_state jsonb / Org node) — the dependency dict's
    # onboarding_state key is never populated by any production auth path
    # (review P0: reading the dict left the guard inert).
    # #2323: the person-level free-tier entitlement is enforced in the
    # caller (create_onboarding_org, count-402 under the lock) — this lane
    # keeps the one-shot marker as the anti-re-entry guard only. (The old
    # "sanctioned second org for Q5" carve-out is closed: /v1/onboarding/team
    # reached the entitlement parity of POST /v1/organizations; see #2323.)
    onboarding_state = _get_onboarding_state(org["org_id"])
    if onboarding_state.get("org_created"):
        raise HTTPException(status_code=409, detail="Sub-team already created")
    from tortoise.supabase_control import (
        get_control_plane,
        is_supabase_enabled,
        provision_org,
    )
    if is_supabase_enabled():
        import uuid as _uuid
        try:
            org_id = str(_uuid.uuid4().hex[:26])
            graph_name = f"org_{org_id}"  # stored name == data-plane namespace — parity with create_org/register_user/agent_signup (#1903)
            # #1716: keyless provisioning — all-NULL key params → the RPC
            # writes orgs + membership but NO api_keys row (all-or-none
            # guard, migration 20260825214233). #1748: USER path — the
            # session user is the owner member (p_user_id, identity NULL),
            # mirroring POST /v1/organizations (create_org).
            provision_org(get_control_plane(), **{
                "p_user_id": owner_user_id,
                "p_identity": None,
                "p_org_id": org_id,
                "p_org_name": name,
                "p_api_key": None,
                "p_key_hash": None,
                "p_lookup_hash": None,
                "p_key_prefix": None,
                "p_graph_name": graph_name,
                "p_tier": "free",
            })
        except Exception as e:
            # 0011 unique index: a duplicate org name surfaces as a
            # PostgREST 409 → 409 (registry sdk.org_create raises
            # ControlPlaneError → 400; 409 is the closer contract — review
            # P1, PR #874).
            if "HTTP 409" in str(e):
                raise HTTPException(status_code=409,  # noqa: B904
                                    detail="Organization name already exists")
            raise HTTPException(status_code=400, detail=f"Team create failed: {e}")  # noqa: B904
        _update_onboarding_state(org["org_id"], org_created=True)
        await _track_onboarding_event(org, "question_answered",
                                      question_id="create_team", answer="yes")
        return {"org_id": org_id, "name": name, "graph_name": graph_name}
    # #1748: the registry-lane SDK must be the CANONICAL control plane
    # (namespace="registry" → registry_control_plane). The old
    # namespace=org_id built a {org_id}_control_plane graph that NO other
    # registry path reads — the mint/list/delete/claim surfaces all read
    # registry_control_plane, so the sub-org's Org + Membership nodes were
    # invisible to them (orphan at the graph level, on top of the missing
    # membership).
    sdk = _make_sdk(namespace="registry")
    try:
        # #1716 keyless parity + #1748 owner Membership for the session
        # user (org_create now creates it — without it the keyless
        # sub-org is an unmintable orphan).
        result = sdk.org_create(name, mint_key=False,
                                 owner_user_id=owner_user_id)
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Team create failed: {e}")  # noqa: B904
    _update_onboarding_state(org["org_id"], org_created=True)
    await _track_onboarding_event(org, "question_answered",
                                  question_id="create_team", answer="yes")
    return {"org_id": result.get("id"), "name": name,
            "graph_name": result.get("graph_name")}


@app.post("/v1/demo")
async def public_demo(org: dict = Depends(get_current_org_gated)):  # noqa: B008
    """Public demo graph creation (Q4) — auth-gated, org-isolated.

    Reuses the same seeding logic as /internal/demo but requires a Bearer
    tt_ key instead of the internal key. Idempotent (sentinel check).
    """
    # C5 #2114 (code-review P1): the demo seed writes ~13 Points into the
    # org's DEFAULT graph — a graph-bound key seeding it would be a
    # cross-graph write; a graphs:read-only key seeding it would be a
    # read→write scope bypass. Demo is a default-graph org surface.
    _reject_graph_bound_org_surface(org, "demo seed")
    _require_scope(org, "graphs:write", "demo seed")
    sdk = _make_sdk(namespace=org["org_id"])
    proj = sdk._get_proj()
    existing = proj.g.query(
        "MATCH (p:Point {id: '_demo_sentinel'}) RETURN p.id"
    ).result_set
    if existing:
        _update_onboarding_state(org["org_id"], demo_created=True)
        await _track_onboarding_event(org, "first_memory_created",
                                      source="demo", point_count=15)
        return {"status": "already_seeded", "org_id": org["org_id"]}

    # #1922: quota-gate the seed like the MCP twin
    # (tortoise_onboarding_demo_create → _enforce_quota("points")). The demo
    # seed writes ~13 Points, so it must consume the points quota like any
    # other Point-creating write — the REST surface was the 0-quota bypass
    # (bug-hunt 2026-08-28 server P2-13). Idempotent re-calls short-circuit
    # above and skip the gate (no write).
    _check_org_limit(org, "points")

    # Call the shared demo seeder (extracted from /internal/demo)
    created = _seed_demo_graph(org["org_id"])

    # #1922: meter the seed that actually ran — one write op billing 12
    # seeded points + the _demo_sentinel Point (net-new non-episodic nodes,
    # the value-first commit cost driver epic #909 §4.4). A concurrent
    # request may have completed the seed first (sentinel now present) —
    # then the seeder returns already_seeded without a points count and
    # the OTHER request already recorded the op (guard on status so the
    # idempotent re-call never 500s on the missing key).
    if created.get("status") == "demo_created":
        _record_write_op(org, nodes_written=created.get("points", 0) + 1)

    _update_onboarding_state(org["org_id"], demo_created=True)
    return {"status": "seeded", "org_id": org["org_id"],
            "points_created": created}


# ── Analytics instrumentation (#501) ────────────────────────────

# Allowed property keys for analytics events — PII-free guarantee (#501).
# Server-side validation: unknown keys are stripped, never forwarded.
_ALLOWED_ANALYTICS_PROPS = {
    "method", "elapsed_from_signup_s", "harness", "section",
    "elapsed_from_copy_s", "question_id", "answer", "source", "point_count",
    "session_id", "message_count", "elapsed_time_s", "steps_completed",
    "questions", "step", "error_type",
    # #889: MCP tool-call telemetry (friction evidence for epic #888)
    "tool_name", "status", "latency_ms", "error_kind",
    # #3359: capture_cost — the per-session cost driver (calibration data
    # only; never on the billing path). All measured fields must survive
    # the PII filter or the measurement is silently lost.
    "calls", "retries", "prompt_tokens", "completion_tokens",
    "cost_usd", "calls_without_cost", "calls_without_usage",
    "deadline_aborts", "by_stage",
    # #3824: provider calls the capture made that NO roll-up accounted for.
    # Without this key in the allowlist the counter is stripped here — the
    # documented #3359 loss mode — and F2 stays invisible even though the
    # row was written.
    "unattributed",
    # #3821: billing attribution. The Stripe webhook emits `plan` and `tier`
    # (the notify_kind row at the billing emit), but they were never
    # registered — so billing analytics rows have been written STRIPPED since
    # c928b0316 (2026-08-09), despite
    # docs/plans/2026-08-08-310-stripe-billing.md mandating those fields.
    # Registering them here repairs that shipped, silent loss; the structural
    # registration test is what keeps the two sets from drifting again.
    "plan", "tier",
    # #3834: the transport-level wait bound's breach event. `method` and
    # `latency_ms` are already registered above; `path` is the one new key.
    # Without it the refusal would be counted but the ROUTE would be stripped
    # here — the documented #3359/#3824 silent-loss mode, which would make the
    # "which routes actually breach 10 s" question unanswerable in production.
    "path",
}

# ── #3821: the unregistered-key choke point ─────────────────────────────
# Every allowlist filter in this module has the same shape: a membership
# test with no `else`. Before this, a key that failed the test was simply
# gone — no error, no counter, no log — so a dropped signal was
# indistinguishable from an event that never fired, and the debugging
# direction was inverted (you hunt a product bug while the product is fine
# and the INSTRUMENT ate the event).
#
# The adopted standard is the OpenTelemetry attribute-limit rule: an
# attribute that cannot be carried MUST NOT be discarded silently, and the
# message MUST be printed at most once per record. The rule has four parts:
#   1. never forward the key  (the PII guarantee is unchanged),
#   2. always count it        (the drop is distinguishable from never-fired),
#   3. report it once         (bounded — a hot emit site cannot flood),
#   4. raise only in strict mode (an explicit dev/test opt-in, read at call
#      time so a test can flip it and prod cannot accidentally be strict).
_TELEMETRY_STRICT_ENV = "TORTOISE_TELEMETRY_STRICT"

# (where, subject, bounded sorted unknown keys) -> drop count. Monotonic —
# reads never reset it. The key is BOUNDED (see `_telemetry_drop_fingerprint`)
# and the dict is capped, because one call site (the PATCH front door) derives
# its keys from a request body: without a bound, an authenticated caller could
# grow both structures without limit and emit an unbounded warning line.
_TELEMETRY_DROP_COUNTS: Counter[tuple[str, str, tuple[str, ...]]] = Counter()

# (where, subject, bounded key fingerprint) already warned — the OTel
# "at most once per record" dedup, kept PER SITE. A single global set let the
# client-controlled PATCH front door consume the whole warning budget and
# silence EVERY other site's first warning — a per-site budget keeps one
# noisy surface from blinding the others.
_TELEMETRY_DROP_REPORTED: dict[tuple[str, str], set[tuple[str, ...]]] = {}

# Guards the count and the warn-dedup so "always counted" and "reported at
# most once" hold under the threaded emit sites (`asyncio.to_thread`, the
# MCP executor). Contended only on a drop — rare by construction — never on
# the happy path.
_TELEMETRY_DROP_LOCK = threading.Lock()

# Cardinality bounds. The counter retains at most `_TELEMETRY_DROP_MAX_MARKERS`
# distinct key-sets PLUS one shared overflow entry; the per-site dedup dict
# retains at most `_TELEMETRY_DROP_MAX_SITES` sites PLUS one shared overflow
# site, each with at most `_TELEMETRY_DROP_MAX_PER_SITE` fingerprints; and at
# most `_TELEMETRY_DROP_MAX_KEYS` keys are named in one counter key / log line,
# each truncated to `_TELEMETRY_DROP_MAX_KEY_LEN` characters.
# Together these mean a CALLER-SUPPLIED key name (or site label) can never make
# the reporter retain or log without bound.
_TELEMETRY_DROP_MAX_MARKERS = 512
_TELEMETRY_DROP_MAX_SITES = 64
_TELEMETRY_DROP_MAX_PER_SITE = 64
_TELEMETRY_DROP_MAX_KEYS = 20
_TELEMETRY_DROP_MAX_KEY_LEN = 128

# The sentinels a capped structure folds into — SHARED, so each structure is
# bounded overall rather than bounded-per-key.
_TELEMETRY_DROP_OVERFLOW: tuple[str, str, tuple[str, ...]] = (
    "<overflow>", "<overflow>", ())
_TELEMETRY_DROP_SITE_OVERFLOW: tuple[str, str] = (
    "<site-overflow>", "<site-overflow>")


def _truncate_label(text: str) -> str:
    """Truncate an over-long label, keeping a length suffix in the rendering."""
    if len(text) <= _TELEMETRY_DROP_MAX_KEY_LEN:
        return text
    return (text[:_TELEMETRY_DROP_MAX_KEY_LEN]
            + f"...(+{len(text) - _TELEMETRY_DROP_MAX_KEY_LEN} more)")


def _cap_dropped_key(key: object) -> object:
    """Truncate ONE over-long dropped key name so a fingerprint stays bounded.

    A key at or under ``_TELEMETRY_DROP_MAX_KEY_LEN`` is returned UNCHANGED, so
    a normal short key's fingerprint — and every assertion on it — is
    byte-identical to before; only an over-long rendering is truncated, with a
    length suffix so the log line still says how much was elided."""
    rendered = key if isinstance(key, str) else str(key)
    if len(rendered) <= _TELEMETRY_DROP_MAX_KEY_LEN:
        return key
    return _truncate_label(rendered)


def _telemetry_drop_fingerprint(keys: frozenset[str] | set[str]) -> tuple[str, ...]:
    """A BOUNDED, comparable rendering of a dropped key set.

    ``key=str`` keeps the sort total for a non-string key (a caller-supplied
    props dict is only membership-checked, so a mixed-type key set must not
    make the reporter itself raise). TWO caps are needed because the PATCH
    front door feeds this from a request body: ``_TELEMETRY_DROP_MAX_KEYS``
    bounds the COUNT of keys named, and ``_TELEMETRY_DROP_MAX_KEY_LEN`` bounds
    each name's LENGTH — without the second, one 1 MiB field name would become
    one 1 MiB retained fingerprint entry and log line.
    """
    ordered = sorted(keys, key=str)
    marker = None
    if len(ordered) > _TELEMETRY_DROP_MAX_KEYS:
        extra = len(ordered) - _TELEMETRY_DROP_MAX_KEYS
        ordered = ordered[:_TELEMETRY_DROP_MAX_KEYS]
        marker = f"...(+{extra} more)"
    rendered = tuple(_cap_dropped_key(k) for k in ordered)
    return (*rendered, marker) if marker is not None else rendered


class UnregisteredTelemetryKey(ValueError):
    """Raised by ``_report_unregistered`` ONLY in strict mode.

    Subclasses ``ValueError`` so a raise inside
    ``OnboardingStatePatchRequest``'s pydantic before-validator surfaces as a
    validation error rather than an opaque 500; every other raise site
    propagates it as-is."""

    def __init__(self, where: str, subject: str, unknown: set[str]) -> None:
        self.where = where
        self.subject = subject
        self.unknown = frozenset(unknown)
        super().__init__(
            f"unregistered telemetry key(s) at {where} (subject={subject}): "
            f"{sorted(map(str, unknown))}")


def _telemetry_strict() -> bool:
    """Strictness is read AT CALL TIME.

    Reading it at import time would both (a) make the flag untestable and
    (b) let a dev flag set before boot survive into production."""
    return is_truthy(os.environ.get(_TELEMETRY_STRICT_ENV))


def _report_unregistered(where: str, subject: str,
                         unknown: set[str] | frozenset[str] | None) -> None:
    """Account for allowlist-dropped telemetry keys — and never forward them.

    Contract (issue #3821), in order:

    1. ALWAYS counts — the bounded key fingerprint is incremented before any
       escalation, so the drop is visible even when strict mode raises.
    2. Reports AT MOST ONCE per ``(where, subject, key-fingerprint)`` per
       process — the OTel bound, so an emit site in a hot loop cannot flood
       the log.
    3. Raises ``UnregisteredTelemetryKey`` ONLY when strict mode is on at call
       time; otherwise returns.
    4. NEVER forwards the key: the caller's filtered props are byte-identical
       to before, preserving the PII guarantee.

    Every retained structure is bounded: ``_TELEMETRY_DROP_COUNTS`` by
    ``_TELEMETRY_DROP_MAX_MARKERS`` plus one shared overflow entry,
    ``_TELEMETRY_DROP_REPORTED`` by ``_TELEMETRY_DROP_MAX_SITES`` sites (plus a
    shared overflow site) each capped at ``_TELEMETRY_DROP_MAX_PER_SITE``
    fingerprints, and the fingerprint's key names by ``_TELEMETRY_DROP_MAX_KEYS``
    names (plus one ``...(+N more)`` marker), each capped at
    ``_TELEMETRY_DROP_MAX_KEY_LEN`` characters.
    The PATCH front door feeds this from a request body, so an authenticated
    caller must not be able to grow process-global state or a log line without
    bound by sending unique unknown field names.

    An empty/``None`` ``unknown`` is a no-op — a fully-registered event must
    leave the counter at zero, or the counter itself is unreadable.
    """
    if not unknown:
        return
    # A site label is a code literal at every CURRENT call site, but the
    # boundedness contract must not depend on that — cap it exactly as a key
    # name is capped, so a future request-derived label cannot grow the
    # counter, the per-site dict, or the log line without bound.
    where = _truncate_label(where)
    subject = _truncate_label(subject)
    fingerprint = _telemetry_drop_fingerprint(frozenset(unknown))
    with _TELEMETRY_DROP_LOCK:
        counter_key = (where, subject, fingerprint)
        if (counter_key not in _TELEMETRY_DROP_COUNTS
                and len(_TELEMETRY_DROP_COUNTS) >= _TELEMETRY_DROP_MAX_MARKERS):
            counter_key = _TELEMETRY_DROP_OVERFLOW
        _TELEMETRY_DROP_COUNTS[counter_key] += 1
        site = (where, subject)
        if (site not in _TELEMETRY_DROP_REPORTED
                and len(_TELEMETRY_DROP_REPORTED) >= _TELEMETRY_DROP_MAX_SITES):
            site = _TELEMETRY_DROP_SITE_OVERFLOW
        reported = _TELEMETRY_DROP_REPORTED.setdefault(site, set())
        report = (fingerprint not in reported
                  and len(reported) < _TELEMETRY_DROP_MAX_PER_SITE)
        if report:
            reported.add(fingerprint)
    if report:
        _logger.warning(
            "unregistered telemetry key(s) dropped at %s (subject=%s): %s — "
            "NOT forwarded; if the loss is unintended, register them in "
            "_ALLOWED_ANALYTICS_PROPS (props) or _ALLOWED_STATE_KEYS (state)",
            where, subject, list(fingerprint))
    if _telemetry_strict():
        raise UnregisteredTelemetryKey(where, subject, set(unknown))


_ANALYTICS_FALLBACK_PATH = None

# #3820: the CLOSED outcome vocabulary of an analytics write. Every exit of
# `_track_analytics_event` returns exactly one member, so its caller — and the
# outcome counter — can tell "delivered" from "degraded" from "no sink
# configured by design" from "lost entirely". Before this, every one of the
# four exits returned bare `None`: a Supabase outage, a revoked key and an
# unwritable JSONL were indistinguishable from success, which is why #3677 was
# discoverable only by a human reading a filesystem on the production machine
# (2,464 events / 568,889 bytes on an ephemeral Fly rootfs).
_ANALYTICS_OUTCOMES = ("supabase", "fallback", "unconfigured", "dropped")

# #3820: the incident kind for a degraded sink. Subject-less, platform-level —
# like DRIVER_DOWN / R2_DOWN — because the analytics sink is shared by every
# org: a per-org subject would fan one degradation out into one issue per
# tenant.
_ANALYTICS_INCIDENT_KIND = "ANALYTICS_SINK_DEGRADED"

# #3820 (D2/P2-1): a single 5s POST timeout must not open a GitHub issue,
# but a persistent outage must be visible within seconds. The trigger is a
# STREAK, not a transition: `_ANALYTICS_DEGRADED_STREAK` counts consecutive
# degraded writes since the last delivered one, and `fallback` alerts when the
# streak reaches `_ANALYTICS_FALLBACK_ALERT_AFTER`. The review's P2-1 finding
# was that the earlier "first fallback after a success" arm opened an incident
# on ONE event, contradicting this decision's own rationale; a saturated
# stream still reaches the threshold within ~15s. `dropped` — the event is
# unrecoverable — alerts at once. The in-process gate that keeps it to ONE
# incident per episode is the `_ANALYTICS_RESOLVE_NOT_BEFORE` arm (see the
# state table below); the AlertStore's own dedup cannot substitute, because a
# per-event call costs an R2 conditional PUT + a GitHub search + Telegram on
# EVERY event of an outage (seconds each, once per event).
#
# #3820 (D5b — the ABSENCE half is DEFERRED, and recorded here rather than
# dropped): D5b also asks for a sink that silently STOPS emitting to be caught
# by a last-success timestamp against a wide cadence-derived threshold. That is
# not implementable at this seam: analytics writes are user-driven with no
# fixed cadence, so "no writes for N minutes" is indistinguishable from a
# healthy idle process, and a real absence check needs a heartbeat the sink
# does not emit — a new signal plus a timer, i.e. a separate change. The
# transition INTO degradation (the next write) is covered by the streak below.
# TRACKED: #3944 — the deferral must not evaporate with the #3820 branch.
_ANALYTICS_FALLBACK_ALERT_AFTER = 3
# The alert-trigger streak — NOT part of the resolve state below: it counts
# consecutive degraded writes and is reset by a delivered one.
_ANALYTICS_DEGRADED_STREAK = 0
# #3820 (cycle-7): the resolve state machine is TWO globals, not five. The
# previous shape carried `_ANALYTICS_INCIDENT_OPEN` + `_ANALYTICS_RESOLVE_
# PROBED` + `_ANALYTICS_RESOLVE_ATTEMPTS` + `_ANALYTICS_RESOLVE_RETRY_AT` +
# `_ANALYTICS_FIRST_DELIVERED_AT` — five coupled flags encoding ONE intention,
# "an incident may be open and there may have to be a resolve". No test could
# pin their cross-product, and each fix to one path broke the invariant the
# others assumed: the same P1 class (an episode silently absorbed) reappeared
# inside the fix for the previous one, four cycles running (latch → probe →
# release → skip). The cross-product is gone; the whole state is these two:
#
#   PENDING     NOT_BEFORE    meaning
#   ───────────────────────────────────────────────────────────────────────
#   False       None          CLEAN. Nothing known open; an alert may file.
#   True        None          UNKNOWN. A pre-restart incident MAY exist and no
#                             resolve has run yet. The next delivered write
#                             probes; an alert may file (the store dedups).
#   True        t             OPEN. An incident is (or may be) open in the
#                             store. Alerts are suppressed for this episode;
#                             a resolve is eligible once `monotonic() >= t`.
#
# The invariant that replaces the cross-product: **`NOT_BEFORE is not None` ⇒
# this process has RECORDED an incident open**. One direction only, deliberately:
# the UNKNOWN row above and a pre-restart CLEAN state both carry `NOT_BEFORE is
# None` while an incident MAY still exist in the store — a stored fact this
# process has not read. What the gate can trust is what this process has SEEN:
# arming it (at a completed alert dispatch, with `t = now` so the resolve stays
# immediately eligible) is what keeps a degradation episode to ONE dispatch —
# the in-process gate the per-event R2 PUT + GitHub search + Telegram cost
# requires — and it doubles as the read bound. NOTHING is ever retired: a
# delayed resolve is never a lost one.
#
# `PENDING` (bool) is the only "is there something to resolve" flag — set at
# process start (a restart must probe the DURABLE incident the dead process
# left open) and whenever `_analytics_open_incident` completes. It is cleared
# ONLY by the store's own report that nothing is open (`RESOLVED` / `ABSENT`),
# never by a guess — driving it from a guess is what re-absorbed the episode.
_ANALYTICS_RESOLVE_PENDING = True
# `NOT_BEFORE` (monotonic deadline | None) is the only bound: the earliest a
# resolve may be attempted. `None` additionally means "nothing on record".
_ANALYTICS_RESOLVE_NOT_BEFORE = None
# The ONE window, and the pre-fix burst is gone. With an incident on record,
# an inconclusive attempt re-arms ``NOT_BEFORE`` this far ahead, so the RESOLVE
# reads the store at most once per window — where the old code allowed
# `_ANALYTICS_RESOLVE_MAX_ATTEMPTS` reads per window while the comment above it
# claimed one. #3820 (cycle-11 P2): a delivered write on the MOVED-window path
# (the stale-fact guard) adds ONE more read-only presence check
# (``AlertStore.incident_open``), so the honest bound is "the resolve reads at
# most once per window" — NOT "at most once per delivered write", which holds
# only when the window did not move under the resolve. The single exception is
# the process-start UNKNOWN state, where a failed read arms nothing (the window
# doubles as the alert gate): there a delivered write retries until the store
# answers, and each retry rebuilds the alert channel and pays one read —
# `_analytics_alert_store()` rebuilds the channel per attempt, while the
# object store and its boto3 client are process-wide (keyed on the resolved
# R2 config, #3968) — not the R2 PUT + GitHub search + Telegram a dispatch
# costs. An honest bound, chosen over a window that would silence a real
# episode.
_ANALYTICS_RESOLVE_BACKOFF_S = 300
# #3820 (cycle-8 P1): the resolve is serialized by its OWN lock — separate from
# `_ANALYTICS_ALERT_LOCK` so the claim cannot be blocked by the counters or the
# degradation gate. The claim is taken under this lock and the store call runs
# without it, so a second concurrent delivered write sees `INFLIGHT` and skips
# rather than acting on a decision taken before the first writer's arm. Lock
# order is resolve -> alert everywhere; never the reverse.
_ANALYTICS_RESOLVE_LOCK = threading.Lock()
# #3820 (cycle-9 P2-2): the resolve MUST NOT hold `_ANALYTICS_RESOLVE_LOCK`
# across its store call. That call is an R2 read whose boto3 client sets no
# explicit timeout (`hosted_backup.py` `R2Storage._s3()` — botocore defaults
# 60 s connect / 60 s read), so holding the lock across it serialized EVERY
# concurrent delivered write — the OAuth-callback path — behind one hang.
# `INFLIGHT` carries the serialization instead: set under the lock, checked
# under the lock, cleared in a `finally` so a raise cannot wedge the resolve.
# The lock is then held for microseconds, never across I/O.
_ANALYTICS_RESOLVE_INFLIGHT = False
# #3820 (cycle-4 P2-2): DERIVED from the declared vocabulary — never re-typed.
# A hand-written dict here (or a hand-written key list in
# `_analytics_incident_detail`) means adding a fifth outcome raises `KeyError`
# on the increment, outside every guard, straight into the GitHub OAuth
# callback the never-raise contract exists to protect.
_ANALYTICS_COUNTS = {o: 0 for o in _ANALYTICS_OUTCOMES}
_ANALYTICS_ALERT_LOCK = threading.Lock()

# #3677: bounded POST timeout. It is asserted (not merely tuned): a timeout
# short enough to expire in production makes EVERY write fall through to the
# ephemeral JSONL — #3677's symptom reached by a different route.
_ANALYTICS_POST_TIMEOUT_S = 5


def _track_analytics_event(org_id: str, event_name: str,
                           properties: dict | None = None) -> str:
    """Record a funnel event. PII-free; graceful when Supabase is unconfigured.

    Writes to Supabase analytics_events when SUPABASE_URL + a service key are
    set (either name in ``supabase_control._SERVICE_KEY_ENV``); otherwise
    appends to a local JSONL fallback. Never raises **except**
    ``UnregisteredTelemetryKey`` under ``TORTOISE_TELEMETRY_STRICT=1`` — the
    registration guard (``_report_unregistered``) raises before any row is
    written, so it is the one documented non-return exit and it is off by
    default in production (see its own docstring).

    #3677: this site read ONLY the legacy ``SUPABASE_SERVICE_KEY`` while the
    hosted deployment sets ``SUPABASE_SERVICE_ROLE_KEY`` — so in production
    the key was never found, every event fell through to the JSONL fallback on
    an ephemeral VM, and the whole analytics stream was silently discarded
    (2,464 events were found in that file on the production machine, and none
    of them in ``analytics_events``).

    #3820: RETURN CONTRACT — the terminal outcome, exactly one member of
    ``_ANALYTICS_OUTCOMES`` (the vocabulary is closed; callers may branch on
    it, and no branch invents a value):

    * ``"supabase"``     — delivered to the real store (2xx).
    * ``"fallback"``     — Supabase was configured but the write degraded
                           (transport error, or a non-2xx that ``post`` does
                           not raise on); the event is on local disk instead.
                           A HALF-configured env — ``SUPABASE_URL`` without a
                           service key, or a key without a URL — is this arm
                           too, with reason ``supabase_env_incomplete``. That
                           is #3677's own failure shape (the URL was set and
                           the key resolved to ``""``), and classifying it as
                           ``unconfigured`` would make this signal BLIND to
                           the very incident that created it.
    * ``"unconfigured"`` — no URL/key at all (selfhost/dev). NOT a
                           degradation: the JSONL is the intended sink, so no
                           incident is ever filed for it (an alert here would
                           fire on every such process and drown the real one).
    * ``"dropped"``      — the event reached NO sink (no writable fallback
                           directory, or the JSONL append itself failed). This
                           is #3677's loss class, and it is unrecoverable.

    ``fallback``/``dropped`` additionally increment
    ``monitoring.ANALYTICS_OUTCOME_COUNT`` and, at most once per degradation
    episode, file ``ANALYTICS_SINK_DEGRADED``. That alert leg is best-effort —
    it adds no non-return exit of its own (the contract above has exactly ONE:
    strict mode's registration guard) and it is NOT conditioned on the alert
    channel existing: counting happens either way.

    #3820 (D5a): the alert leg is also NOT conditioned on the backup sweep
    being enabled. ``_backup_config_safe()`` returns ``None`` whenever
    ``BACKUP_SWEEP_ENABLED`` is false (the default), and a channel built on it
    would therefore never file on such a deployment — re-creating #3677's loss
    class through the alert channel, which is exactly what D5a forbade. The
    channel's own credentials are read ungated (``backup_config.load_alert_
    config``); the residual is its CONSTRUCTION — no ``DR_ISSUES_PAT`` (no
    filer) or an unusable object store (``R2_*`` missing/typoed; the
    ``AlertStore``'s dedup needs ``_backup_storage()``, and ``R2Storage``
    raises without all four) — leaving the counter + WARNING.
    """
    if not isinstance(properties, dict):
        # The contract is never-raise; a non-dict would raise AttributeError
        # from `.items()` straight out of it. Every in-repo caller passes a
        # dict — this pins the contract for callers added later.
        properties = None
    # #3821: observe the drop BEFORE the filter below removes it. The filter
    # itself is unchanged — an unknown key is still never forwarded, so the
    # PII guarantee is byte-identical. Reporting first also means strict mode
    # raises before any row is written.
    _report_unregistered(
        "analytics_props", event_name,
        set(properties or {}) - _ALLOWED_ANALYTICS_PROPS)
    props = {k: v for k, v in (properties or {}).items()
             if k in _ALLOWED_ANALYTICS_PROPS}
    event = {
        "org_id": org_id,
        "event_name": event_name,
        "properties": props,
        "created_at": datetime.now(UTC).isoformat(),
    }
    url = os.environ.get("SUPABASE_URL")
    # The service-key names and their precedence come from one seam
    # (`supabase_control._service_key()`): #3677 was exactly this site reading a
    # name the hosted deployment never sets. Older sibling sites still
    # hand-roll the same pair — see #3677's sibling audit.
    key = _service_key()
    # #3820 (D1): remember whether a sink was ATTEMPTED at all. This one
    # boolean is what separates `fallback` (configured, but degraded — alert)
    # from `unconfigured` (no sink by design — never alert).
    configured = bool(url and key)
    # #3820 (P1-2): a HALF-configured env is the FIFTH silent path. The
    # docstring of `unconfigured` is "no URL/key AT ALL", but `configured`
    # implements "both present" — so `SUPABASE_URL` set with the key missing
    # (or renamed/#3677's `""`) fell through to `unconfigured`, `should_alert
    # = False`, and the stream silently diverted to the ephemeral JSONL with no
    # incident. That is #3677 itself, and it made this signal blind to the very
    # failure that created the issue: with exactly one of the pair set, a sink
    # was clearly INTENDED, so the write is a degradation.
    misconfigured = bool(url) != bool(key)
    if configured:
        # #3820 (cycle-4 P2-1): the guard covers the NETWORK CALL only. The
        # delivered branch used to sit inside it, so a raise in the success leg
        # (`return _analytics_note_success()` — the counter, the lock, the store
        # build, the resolve) was swallowed and fell through to the JSONL: a
        # DELIVERED event was duplicated to disk and misreported as `fallback`,
        # which can file an incident for a healthy sink.
        delivered = False
        try:
            import httpx
            # #4015: the client is built PER EVENT, deliberately. For the
            # funnel sites it goes through ``_emit_analytics_off_loop`` → the
            # telemetry pool, so a fresh TCP+TLS handshake costs a telemetry
            # WORKER SLOT, never an event-loop stall — it is not the defect this
            # issue names. (The capture-cost lane reaches this helper on the
            # loop's shared default executor instead; either way, off-loop.)
            # Reusing a pooled client is a throughput optimisation for those
            # pools and needs its own measurement plus a lifecycle it does not
            # have today (lazy construction gated on ``configured``, because
            # this sink must keep serving a HALF-CONFIGURED env and degrade to
            # the JSONL — the #3677/#3820 contract); tracked as #4462.
            with httpx.Client(timeout=_ANALYTICS_POST_TIMEOUT_S) as client:
                resp = client.post(
                    f"{url}/rest/v1/analytics_events",
                    json=event,
                    headers={"apikey": key, "Authorization": f"Bearer {key}",
                             "Content-Type": "application/json",
                             "Prefer": "return=minimal"},
                )
            # #3677: a REJECTED write is still a lost event. `post` does not
            # raise on a 4xx/5xx, so without this check the event was silently
            # discarded — the #3677 loss class, reachable whenever the key is
            # revoked or INSERT-denied (a 401 returns no exception). Fall
            # through to the local JSONL instead of dropping it.
            delivered = 200 <= resp.status_code < 300
        except Exception:
            delivered = False  # fall through to JSONL
        if delivered:
            # A raise here must NOT re-route a delivered event to the JSONL.
            # The event reached the sink, so the outcome is known regardless;
            # the never-raise contract still covers this leg.
            try:
                return _analytics_note_success()
            except Exception as e:  # bookkeeping is best-effort
                _logger.warning("analytics success bookkeeping failed: %s", e)
                return "supabase"
    # JSONL fallback (~/.tortoise/analytics_fallback.jsonl)
    global _ANALYTICS_FALLBACK_PATH
    if _ANALYTICS_FALLBACK_PATH is None:
        # Directory creation belongs INSIDE the best-effort guard: it used to
        # sit outside it, so a read-only HOME raised straight out of a function
        # documented never to raise (and into the GitHub OAuth callback).
        try:
            fallback_dir = os.path.join(os.path.expanduser("~"), ".tortoise")
            os.makedirs(fallback_dir, exist_ok=True)
            _ANALYTICS_FALLBACK_PATH = os.path.join(
                fallback_dir, "analytics_fallback.jsonl")
        except Exception:
            # #3820: the FOURTH silent path — the issue's table names three.
            # Pre-#3820 this was a bare `return`: the event was dropped with no
            # fallback line, no counter and no log — the same loss class as the
            # append failure below, and the reason this exit now routes through
            # the shared `_analytics_sink_dropped` helper.
            return _analytics_sink_dropped("fallback_dir_unavailable")
    try:
        import json as _json
        with open(_ANALYTICS_FALLBACK_PATH, "a") as f:
            f.write(_json.dumps(event) + "\n")
    except Exception:
        # #3677 swallowed this; #3820 swallows it AND counts it — the event
        # reached no sink at all.
        return _analytics_sink_dropped("fallback_append_failed")
    if misconfigured:
        # #3820 (P1-2): a sink was clearly INTENDED, so this is a degradation
        # with its own reason code — never `unconfigured`.
        return _analytics_note_degradation("fallback", "supabase_env_incomplete")
    return _analytics_note_degradation(
        "fallback" if configured else "unconfigured")


def _analytics_note_success() -> str:
    """Record a delivered write; resolve an open sink incident. Never raises.

    #3820 (D4): the resolve is what makes the NEXT loss a NEW incident. The
    AlertStore resolves by delete, so leaving an incident open means every
    later degradation is absorbed into a stale issue — the silent-loss class,
    reintroduced through the alert channel. ``resolve_incident`` begins with an
    R2 download, so this is NOT called per event: it runs while
    ``_ANALYTICS_RESOLVE_PENDING`` says there is (or may be) something to
    resolve, bounded by the single ``_ANALYTICS_RESOLVE_NOT_BEFORE`` window so
    a delivered write inside a just-spent window costs nothing.

    #3820 (cycle-8 P1): the resolve is SERIALIZED by an in-flight claim taken
    under ``_ANALYTICS_RESOLVE_LOCK`` — the decision and the claim are one
    atomic step, so two concurrent delivered writes cannot both read the store.
    The lock is NOT held across the store call (cycle-9 P2-2): that call is an
    R2 read botocore bounds only at its 60 s defaults, and holding the lock
    across it serialized every delivered write behind one hang. The claim is
    cleared in a ``finally``. Without any serialization, a reader that saw
    ``ABSENT`` before a fresh incident was filed could land after the
    ``SKIPPED_FRESH`` completion armed the window and clear it: an incident
    open in the store with ``PENDING=False``, and the next episode deduped into
    it (the D4/#3677 absorbed-episode class).

    #3820 (cycle-9 P1): the ``armed_at_decision`` guard is not taken on faith.
    When the window moved during the store call, the CLEAR is withheld only if
    an incident is still ON RECORD — a concurrent degradation may have DEDUPED
    onto the very incident this resolve then deleted, so the moved arm would
    otherwise hold the alert gate shut with nothing behind it and a still-
    degraded sink would file nothing, indefinitely (D4 again). The withheld
    clear therefore asks the store, read-only, whether the incident still
    exists (``AlertStore.incident_open``) and clears when it does not. A
    residual same-process ordering — a degradation that arms AFTER this clear,
    having deduped an object the resolve then deleted — is NOT closed by it;
    it is pre-existing (same rate in the cycle-8 shape) and tracked as #3969.

    #3820 (cycle-7): the outcome of the store's resolve DRIVES the state — it
    is never inferred. ``resolve_incident_state`` reports WHICH fact holds:

    * ``RESOLVED`` / ``ABSENT`` — nothing is open any more → CLEAN
      (``PENDING=False``, ``NOT_BEFORE=None``).
    * ``SKIPPED_FRESH`` — an incident IS open; it was filed at/after this
      attempt's bound, so it was deliberately left alone. The state STAYS
      pending and the next attempt is a window away. The pre-collapse code
      cleared the episode latch here, so the fresh incident was never resolved
      by this process and the following episode was absorbed into it (cycle-7
      P1).
    * a raise, or no usable store — the truth is unknown → also stay pending.
      When an incident is already on record the attempt re-arms the window
      (bounded reads); from the process-start UNKNOWN state nothing is armed,
      so the next delivered write retries. That asymmetric arm is deliberate:
      the window is ALSO the alert gate, and an uncertainty must never close
      it — see ``_analytics_note_degradation``. Nothing is ever retired on a
      failure: a delayed resolve is not a lost one.

    The ``before`` bound is the instant this attempt DECIDED to resolve (not a
    once-per-process stamp): an incident that predates the decision is the one
    this attempt may close, and anything filed after it is a fresh episode the
    Store reports back as ``SKIPPED_FRESH``. That keeps the cross-restart
    resolve (cycle-4 P1-1) and the fresh-incident guard (cycle-5 P1-2) in ONE
    rule instead of a latch/probe split.
    """
    global _ANALYTICS_DEGRADED_STREAK, _ANALYTICS_RESOLVE_PENDING
    global _ANALYTICS_RESOLVE_NOT_BEFORE, _ANALYTICS_RESOLVE_INFLIGHT
    with _ANALYTICS_ALERT_LOCK:
        _ANALYTICS_COUNTS["supabase"] += 1
        _ANALYTICS_DEGRADED_STREAK = 0
    _analytics_count_outcome("supabase")
    # #3820 (cycle-8 P1 / cycle-9 P2-2): the resolve is SERIALIZED by an
    # IN-FLIGHT claim taken under `_ANALYTICS_RESOLVE_LOCK` — never by holding
    # that lock across the store call. Without serialization, N concurrent
    # delivered writes all evaluate the decision against an UNSPENT window and
    # all read the store, so a reader that saw `ABSENT` before a fresh incident
    # was filed could land AFTER the `SKIPPED_FRESH` completion armed the window
    # and clear it — an incident open with `PENDING=False` and the alert gate
    # open, so the next episode is deduped into the stale incident (the
    # D4/#3677 absorbed-episode class). Taking the claim under the lock makes
    # the second writer see it and SKIP.
    #
    # The lock is held for the CLAIM ONLY (microseconds), not across the store
    # call: that call is an R2 read whose boto3 client sets no explicit timeout
    # (botocore defaults 60 s connect / 60 s read), so holding the lock across
    # it serialized every delivered write — the OAuth-callback path — behind
    # one hang (cycle-9 P2-2). The flag carries the serialization instead and
    # is cleared in a `finally`, so a raise cannot wedge the resolve forever.
    # Lock order is always resolve → alert (never the reverse), and the only
    # nested acquisition is the claim below, so the pair cannot deadlock.
    with _ANALYTICS_RESOLVE_LOCK, _ANALYTICS_ALERT_LOCK:
        # ONE decision, from the single pending flag and the single bound.
        # ``time.monotonic`` is read once, under the claim lock.
        resolve = _ANALYTICS_RESOLVE_PENDING and (
            _ANALYTICS_RESOLVE_NOT_BEFORE is None
            or time.monotonic() >= _ANALYTICS_RESOLVE_NOT_BEFORE)
        # A second concurrent delivered write must re-read the state under
        # the lock and SKIP — but it must not BLOCK: the claim, not the
        # lock, is what serializes the store call.
        claimed = resolve and not _ANALYTICS_RESOLVE_INFLIGHT
        if claimed:
            _ANALYTICS_RESOLVE_INFLIGHT = True
            before = datetime.now(UTC)
            # The state this decision was taken against. The CLEAR below is
            # applied only if nothing moved the window while the store call
            # was in flight: a DEGRADATION can file an incident and arm the
            # window during that call, and `_analytics_open_incident` is not
            # — and must not be — serialized on the resolve lock, because it
            # does network I/O and holding the lock across it would block
            # the analytics write path.
            armed_at_decision = _ANALYTICS_RESOLVE_NOT_BEFORE
        else:
            before = None
            armed_at_decision = None
    if not claimed:
        # Either nothing is eligible, or another delivered write holds the
        # in-flight claim and is performing exactly this resolve — so skip.
        return "supabase"
    try:
        outcome = None
        store = None
        try:
            store = _analytics_alert_store()
            if store is not None:
                outcome = store.resolve_incident_state(
                    _ANALYTICS_INCIDENT_KIND, "", before=before)
                if outcome is ResolveOutcome.RESOLVED:
                    _logger.info("analytics sink recovered — %s resolved",
                                 _ANALYTICS_INCIDENT_KIND)
                elif outcome is ResolveOutcome.SKIPPED_FRESH:
                    _logger.info(
                        "analytics sink resolve skipped a FRESH %s — it "
                        "stays open, keeping the resolve pending",
                        _ANALYTICS_INCIDENT_KIND)
        except Exception as e:  # best-effort, never raises
            _logger.warning("analytics sink resolve failed: %s", e)
        # The CLEAR is applied only if the fact is not STALE. `armed_at_decision`
        # is the window the decision was taken against; a DEGRADATION can arm
        # the window (and file or dedup an incident) while the store call is in
        # flight. An unconditional clear there leaves an incident OPEN in the
        # store with `PENDING=False`, which no delivered write would ever
        # resolve (cycle-8 criterion 2, pinned by T34).
        clear = False
        check_presence = False
        # #3820 (cycle-11 P1): the window value the CLEAR below is validated
        # against. `time.monotonic()` never repeats, so a late arm always
        # changes it — which is what makes the clear ATOMIC with the arm
        # instead of merely concurrent with it.
        moved_to = None
        with _ANALYTICS_ALERT_LOCK:
            if (outcome is ResolveOutcome.RESOLVED
                    or outcome is ResolveOutcome.ABSENT):
                if armed_at_decision == _ANALYTICS_RESOLVE_NOT_BEFORE:
                    # The store's OWN report: nothing is open. This is the only
                    # way the pending flag is cleared — never a guess. The
                    # value is re-checked against `moved_to` under the lock
                    # before the write, because the two lock acquisitions are
                    # not one atomic step: a degradation can arm in between.
                    clear = True
                    moved_to = _ANALYTICS_RESOLVE_NOT_BEFORE
                else:
                    # The window moved while this attempt was in flight, so the
                    # fact it established is STALE. The arm belongs to a
                    # concurrent degradation — but that degradation may have
                    # DEDUPED onto the very incident this resolve just deleted,
                    # so confirm an incident is still on record before keeping
                    # the arm. Keeping it on faith would leave the alert gate
                    # shut with NOTHING on record, and a still-degraded sink
                    # would file nothing, indefinitely (cycle-9 P1; D4/#3677
                    # absorbed-episode class). The presence read is read-only
                    # and is taken OFF the alert lock, below.
                    #
                    # #3820 (cycle-11 P1): this is the value the presence
                    # check is a fact ABOUT. The read below runs off-lock, so
                    # a late arm can move the window again before the CLEAR
                    # writes; snapshotting the mover's value lets the write
                    # detect exactly that.
                    check_presence = True
                    moved_to = _ANALYTICS_RESOLVE_NOT_BEFORE
            else:
                # SKIPPED_FRESH means an incident IS open; a raise or a
                # missing store leaves the truth UNKNOWN. Either way the
                # resolve stays PENDING. Arm the ONE window only when an
                # incident is on record — SKIPPED_FRESH just established
                # one, or NOT_BEFORE was already armed by a dispatch. From
                # the process-start UNKNOWN state nothing is armed, because
                # `NOT_BEFORE is not None` is ALSO the alert gate
                # (`_analytics_note_degradation`): an uncertainty must not
                # silence a real episode, so that state retries on the next
                # delivered write instead.
                if (outcome is ResolveOutcome.SKIPPED_FRESH
                        or _ANALYTICS_RESOLVE_NOT_BEFORE is not None):
                    _ANALYTICS_RESOLVE_NOT_BEFORE = (
                        time.monotonic() + _ANALYTICS_RESOLVE_BACKOFF_S)
        if check_presence:
            # Read-only presence check, OFF every lock: the alert lock must not
            # be held across a store read (the same I/O rule as the resolve
            # lock above). The value CAN move while this read is in flight —
            # the arm site takes its `known_open` DECISION under the alert
            # lock, but its WRITE lands only after `_analytics_open_incident`
            # returns (a GitHub search, a file, a Telegram push), so the two
            # are not atomic with this read. The CLEAR below is therefore
            # re-validated against `moved_to` under the lock (cycle-11 P1);
            # #3969 tracks the durable epoch/generation fix for the whole
            # class. A raise or a store without the probe keeps the arm: an
            # unknown is never treated as CLEAN.
            probe = getattr(store, "incident_open", None) if store else None
            if probe is None:
                clear = False
            else:
                try:
                    clear = not probe(_ANALYTICS_INCIDENT_KIND, "")
                except Exception as e:  # unknown → keep the arm
                    clear = False
                    _logger.warning(
                        "analytics sink resolve presence check failed: %s", e)
        if clear:
            with _ANALYTICS_ALERT_LOCK:
                # #3820 (cycle-11 P1): the clear is applied ONLY if the value it
                # was established against still holds. The presence probe above
                # runs OFF every lock, and the arm site does NOT re-check
                # `NOT_BEFORE is None`, so a degradation whose `should_alert`
                # decision was taken while the window was UNSET (`NOT_BEFORE is
                # None`) can file and arm after the probe's read and before
                # this write — a scheduler preemption across an I/O-free gap is
                # enough. Clearing then leaves an incident open in the store
                # with `PENDING=False`, which no delivered write ever resolves
                # and the next episode dedups into (cycle-8 criterion 2,
                # pinned by T34/T37). `moved_to` re-validation keeps BOTH the
                # arm and the object behind it.
                if moved_to == _ANALYTICS_RESOLVE_NOT_BEFORE:
                    _ANALYTICS_RESOLVE_PENDING = False
                    _ANALYTICS_RESOLVE_NOT_BEFORE = None
    finally:
        # The claim is released on EVERY exit — a raise in the store call or in
        # the presence probe must not leave the resolve wedge-closed.
        with _ANALYTICS_RESOLVE_LOCK:
            _ANALYTICS_RESOLVE_INFLIGHT = False
    return "supabase"


def _analytics_sink_dropped(reason: str) -> str:
    """Count + alert a write that reached NO sink; returns ``"dropped"``.

    #3820: used by both unrecoverable exits (no fallback directory, failed
    JSONL append) so the reason code, the count and the alert live in one
    place — the two sites cannot drift apart.
    """
    return _analytics_note_degradation("dropped", reason)


def _analytics_count_outcome(outcome: str) -> None:
    """Increment the outcome counter; never raises (#3820 P2-3).

    The counter leg used to sit OUTSIDE every guard in the two note helpers,
    so a raise from the metrics library would have escaped a function whose
    stated contract — the reason it exists — is never to raise into the GitHub
    OAuth callback.
    """
    try:
        record_analytics_outcome(outcome)
    except Exception as e:
        _logger.warning("analytics outcome counter failed (%s): %s", outcome, e)


def _analytics_note_degradation(outcome: str, reason: str = "") -> str:
    """Count a degraded analytics write and alert if warranted.

    Returns ``outcome`` unchanged so the write path can
    ``return _analytics_note_degradation(...)``. Never raises.

    #3820 (D2/P2-1): ``fallback`` needs a STREAK of
    ``_ANALYTICS_FALLBACK_ALERT_AFTER`` consecutive degraded writes; ``dropped``
    is unrecoverable and alerts on the first one. ``unconfigured`` never alerts.
    #3820 (P2-2): the episode gate is armed only when the dispatch actually
    SUCCEEDED — it used to be armed before the dispatch, so a raising
    ``open_incident`` (or an unavailable channel) silenced the whole episode and
    the store's own retry never got a second call.
    #3820 (cycle-7): the gate is the ONE state global — ``NOT_BEFORE is not
    None`` means this process has RECORDED an incident open (see the state
    table at the globals; the UNKNOWN row and a pre-restart CLEAN state carry
    ``NOT_BEFORE is None`` with an incident possibly still in the store).
    Arming it with ``t = now`` keeps the resolve immediately eligible
    while closing the alert gate, so one episode pays for exactly one dispatch
    (R2 PUT + GitHub search + Telegram) and the resolve still fires on the
    recovered write. There is no separate latch to go stale: a resolve that
    ends CLEAN disarms it, which is exactly when a new episode must file.
    #3820 (cycle-8 P2-1): the arm happens only when the store reports an
    incident IS on record. A paused kind creates NOTHING, so arming on that
    path left the gate closed with no incident behind it — and if the pause
    were lifted while the sink was still degraded, nothing could ever reopen
    it (only a delivered write disarms the gate, and a writing sink is the
    one thing the outage forbids).
    """
    global _ANALYTICS_DEGRADED_STREAK, _ANALYTICS_RESOLVE_PENDING
    global _ANALYTICS_RESOLVE_NOT_BEFORE
    with _ANALYTICS_ALERT_LOCK:
        _ANALYTICS_COUNTS[outcome] += 1
        if outcome == "unconfigured":
            # The local JSONL IS the intended sink — never an alert.
            should_alert = False
        else:
            _ANALYTICS_DEGRADED_STREAK += 1
            # An incident is on record open ⇒ this episode has been filed and
            # must not re-pay the alert cost per event.
            known_open = _ANALYTICS_RESOLVE_NOT_BEFORE is not None
            if outcome == "dropped":
                # Unrecoverable: the event is gone. Alert at once, but still
                # only once per episode.
                should_alert = not known_open
            else:  # "fallback" — the event is safe on disk; wait for a streak
                should_alert = (
                    not known_open
                    and _ANALYTICS_DEGRADED_STREAK
                    >= _ANALYTICS_FALLBACK_ALERT_AFTER)
    _analytics_count_outcome(outcome)
    if should_alert and _analytics_open_incident(outcome, reason):
        with _ANALYTICS_ALERT_LOCK:
            _ANALYTICS_RESOLVE_PENDING = True
            # Eligible to resolve NOW (t = now), but the alert gate above is
            # closed until a resolve reports the incident CLEAN.
            _ANALYTICS_RESOLVE_NOT_BEFORE = time.monotonic()
    return outcome


def _analytics_open_incident(outcome: str, reason: str) -> bool:
    """Best-effort ``ANALYTICS_SINK_DEGRADED`` incident. Never raises (#3820).

    Returns ``True`` only when an incident is ON RECORD — the dispatch
    completed without raising AND the store did not decline because the kind
    is paused. The caller uses that to arm the episode gate (P2-2), so a
    failure, or a suppressed kind, leaves the next event free to retry rather
    than closing the gate on nothing (cycle-8 P2-1).

    The alert does NOT ride the failing sink (an analytics event filed through
    ``_track_analytics_event`` would land in the same ephemeral file #3677's
    2,464 events were found in) — it goes to the AlertStore, which has the
    properties the signal needs: create-if-not-exists dedup per (kind,
    subject), ``ops/suppression.json`` to pause a kind, delete-to-resolve, a
    pending-push retry when Telegram fails, and a GitHub issue the fleet's
    triage agents can read.
    """
    try:
        # P2-3: inside the guard — building the detail takes the alert lock and
        # used to run BEFORE the try, outside every guard.
        detail = _analytics_incident_detail(outcome, reason)
        store = _analytics_alert_store()
        if store is None:
            _logger.warning(
                "analytics sink degraded (%s%s) — no alert store available "
                "(no alert credentials, or the object store is unusable); the "
                "counter tortoise_analytics_events_total is the only signal: "
                "%s",
                outcome, f"/{reason}" if reason else "", detail)
            return False
        # #3820 (cycle-5 P1-3): `open_incident` returns False on a DEDUP hit
        # (the dedup object already exists). Ignoring that boolean made the
        # audit trail claim `filed` on EVERY dedup path, not only the restart
        # one — it must distinguish a new issue from an already-open one.
        # #3820 (cycle-6 P2-1): False is AMBIGUOUS — a SUPPRESSED kind (a
        # pause in `ops/suppression.json`) also returns it, with NO issue and
        # NO dedup object. Reporting that as `already open (dedup)` sent an
        # operator who set a pause hunting for an issue that does not exist.
        # #3820 (cycle-8 P2-2): ask the store for the FACT, in one call.
        # Re-asking `suppression_active` at a LATER instant can disagree with
        # the decision `open_incident` already made (a pause withdrawn in
        # between), which reports a dedup hit for an incident that was never
        # created; `open_incident_state` reads the predicate once, at the
        # instant that matters. The `getattr` fallback keeps a store without
        # the probe (test doubles) working; the calls sit inside the
        # never-raise try.
        opener = getattr(store, "open_incident_state", None)
        if opener is not None:
            fact = opener(_ANALYTICS_INCIDENT_KIND, "", detail)
        else:
            probe = getattr(store, "suppression_active", None)
            if store.open_incident(_ANALYTICS_INCIDENT_KIND, "", detail):
                fact = OpenOutcome.FILED
            elif probe is not None and probe(_ANALYTICS_INCIDENT_KIND):
                fact = OpenOutcome.SUPPRESSED
            else:
                fact = OpenOutcome.DEDUP
        if fact is OpenOutcome.FILED:
            disposition = "filed"
        elif fact is OpenOutcome.SUPPRESSED:
            disposition = "suppressed (kind paused)"
        else:
            disposition = "already open (dedup)"
        _logger.warning(
            "analytics sink degraded (%s%s) — %s %s: %s",
            outcome, f"/{reason}" if reason else "",
            disposition,
            _ANALYTICS_INCIDENT_KIND, detail)
        # #3820 (cycle-8 P2-1): the gate may be armed ONLY when an incident is
        # on record. The store's own fact says which: SUPPRESSED created no
        # object, so the caller must not set `NOT_BEFORE` (the alert gate) on
        # that path — a paused kind would otherwise hold the gate shut with
        # nothing behind it, and a pause lifted mid-outage could never be
        # reopened (only a delivered write disarms the gate, which is exactly
        # what a degraded sink cannot produce). FILED and DEDUP both mean an
        # incident IS on record, so both arm it.
        return fact is not OpenOutcome.SUPPRESSED
    except Exception as e:  # the write path must never raise
        _logger.warning("analytics sink alert failed (%s): %s", outcome, e)
        return False


def _analytics_incident_detail(outcome: str, reason: str) -> dict:
    """Counts and reason codes ONLY — never event content (#3820 D5).

    The incident body is ``json.dumps(detail)`` rendered into a GitHub issue
    that fleet agents read (``alert_store._body``). ``_ALLOWED_ANALYTICS_PROPS``
    contains user-derived keys (``answer``, ``questions``, ``error_type``), so
    passing the event's properties through would publish user content into an
    issue and open a prompt-injection channel into the triage agent. Never the
    URL, the key, the event name, or the properties.
    """
    with _ANALYTICS_ALERT_LOCK:
        # #3820 (cycle-4 P2-2): derived from the declared vocabulary, so the
        # detail can never drift from `_ANALYTICS_OUTCOMES` (a hand-written key
        # list raised `KeyError` when the vocabulary grew).
        return {
            "outcome": outcome,
            "reason": reason,
            **{o: _ANALYTICS_COUNTS[o] for o in _ANALYTICS_OUTCOMES},
        }


def _incident_alert_store(writer: str | None = None):
    """THE alert-channel builder for operator incidents — ALERT creds only.

    Deliberately NOT gated on ``BACKUP_SWEEP_ENABLED`` (#3820 D5a): the sweep
    switch decides whether backups RUN, never whether an incident is VISIBLE.
    When the sweep is enabled its config is used as-is; otherwise
    ``load_alert_config`` reads the alert credentials ungated. Returns ``None``
    when there is no issue filer (``DR_ISSUES_PAT`` unset) or the object store
    cannot be built; the caller then keeps its log line. Env-only: no network
    at construction.

    ``writer`` is threaded through to ``_alert_store_from`` so a caller that
    must act as a specific identity (the watcher, ``WRITER_WATCHER``) keeps
    main's #3127/#2844 authority check — the store's resolves are checked
    against ``KIND_OWNERS``. Default ``None`` → the app's own identity.

    The rule executed here (and the constructor it calls) live in
    ``tortoise/alert_channel.py``, because ``operator_alert.alert_store()`` —
    the lane that fires from a dropped increment — must reach the identical
    channel without importing this module: importing it builds the whole
    FastAPI app (~1.7 s, see ``tortoise/mcp_server.py:31-35``) and that cost
    would ride the MCP stdio path for a bookkeeping alert. This function
    injects THIS module's factories, which is the only difference between the
    two legs.

    D6 residual, narrowed: the channel can fail to exist for TWO physical
    reasons — no ``DR_ISSUES_PAT`` means no filer, and an unusable object store
    (missing or typoed ``R2_*`` — the store constructor raises unless all four
    are set) means no dedup seam. It is therefore "no PAT **or** no usable
    object store", not "no PAT" alone. Counting must never be conditioned on
    this returning a store.

    SEAM MAP (one policy, several names — for a reader, not for a caller):
      * ``alert_channel.incident_alert_store`` — the chokepoint holding the
        ALERT-only policy; ``hosted_api._incident_alert_store`` injects the
        hosted factories into it. ``operator_alert.alert_store`` PREFERS this
        function whenever ``tortoise.hosted_api`` is already imported, and
        only falls back to the light leg when it is not — so in the hosted
        process there is ONE builder and one cached store.
      * ``_analytics_alert_store`` — a retained TEST PATCH POINT; it delegates
        here and adds no policy of its own. Patching it does NOT redirect
        ``operator_alert``/``cohort_cost``, which resolve through this function
        (or ``operator_alert.alert_store``); patch the plane you mean.
      * ``cohort_cost._alert_store`` — retained as a stable internal API for its
        module; it delegates through ``operator_alert.alert_store``.
      * ``_alert_store_from(cfg, writer=None)`` — the pure constructor from an
        already-loaded config; it dereferences ``cfg`` and must never be handed
        ``None``.
    """
    from tortoise import alert_channel

    return alert_channel.incident_alert_store(
        config_safe=_backup_config_safe, storage_factory=_backup_storage,
        writer=writer)


def _analytics_alert_store():
    """The AlertStore for sink incidents, or ``None`` when unavailable.

    #3820: the indirection seam — tests monkeypatch THIS, never
    ``_alert_store_from``.

    #3820 (D5a)/#3981: delegates to ``_incident_alert_store`` so the analytics
    sink and the operator-alert kinds share ONE channel policy and cannot
    drift apart — see that function for the ALERT-only gate and the D6
    residual. Counting must never be conditioned on this returning a store.
    """
    return _incident_alert_store()


def _as_call_count(value) -> int:
    """Coerce a #3824 call-evidence value to a non-negative int (0 on junk).

    A producer is free to hand over ``None``/missing/negative/a
    fraction/a non-finite or absurd-magnitude value; none of those may become
    a phantom nonzero disclosure, and none may raise inside the capture
    handler's best-effort emit. A call count is a WHOLE number, so a
    fractional one is malformed and is treated as absent rather than
    truncated into a phantom count. The magnitude bound matches the reader's
    own ``_as_int`` (``tools/longmem_eval/costing.py``), so a magnitude the
    emitter accepts is one the report cannot later read as junk.
    """
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return 0
    if isinstance(value, float) and not value.is_integer():
        return 0
    try:
        if abs(value) > 1e300:
            return 0
        n = int(value)
    except (TypeError, ValueError, OverflowError):
        return 0
    return n if n > 0 else 0


def _capture_cost_props(session_id: str, meta: dict) -> dict | None:
    """#3359: the per-session cost driver as an analytics ``properties`` dict.

    Reads the extractor telemetry (``meta["stats"]["llm"]``) that
    ``_rollup_llm`` now accumulates: provider calls, prompt/completion
    tokens, the provider's own reported USD charge, the
    ``calls_without_cost`` disclosure counter, and the per-stage/
    per-route ``by_stage`` envelope (repricable at report time).

    #3824 — TWO FACTS, NEVER ONE. A ``stats`` with no ``llm`` used to
    collapse two distinct captures into the same ``None``:

    * **F1 — zero provider calls.** The empty-transcript gate: nothing
      was sent, so no row is written and the window stays clean.
      ``return None`` is correct here.
    * **F2 — calls were made and the roll-up did not survive.** The M2
      session lane (#3747) issues real provider calls and discards their
      usage; any future lane that builds its own ``meta`` does the same.
      Absence made F2 indistinguishable from F1 *and* from "$0.00 spent",
      so an all-M2 deployment read as "NO capture_cost ROWS IN THIS
      WINDOW" — a missing measurement wearing the shape of a cheap one,
      and #3780's cohort-cap denominator was set from that undercount.

    The discriminator is the call evidence the producer keeps OUTSIDE the
    roll-up (``meta["stats"]["unattributed"]``, written by
    ``sdk._extract_session_llm``) — it survives exactly the case the
    roll-up does not, because it is recorded at the CALL site rather than
    reconstructed from the response. When it is present with no roll-up the
    row is written anyway, every measured field zeroed and ``unattributed``
    carrying the call count, so the spend is DISCLOSED rather than erased.
    When a roll-up does survive, ``unattributed`` rides alongside it (0 on a
    fully-metered capture) — the sibling-counter precedent
    (``calls_without_cost`` / ``calls_without_usage`` /
    ``deadline_aborts``) rather than a second, drifting total.

    A capture whose extraction ERRORED does carry a roll-up (and therefore
    a row): the provider calls were made and their spend is real.
    """
    stats = meta.get("stats") or {}
    llm = stats.get("llm") or {}
    # #3824: calls made that no roll-up accounted for. Must live OUTSIDE
    # ``llm`` — nested there it could not exist in the very case it
    # describes (an empty roll-up).
    unattributed = _as_call_count(stats.get("unattributed"))
    if not llm and not unattributed:
        # F1: zero provider calls. No measurement exists, so no row — a
        # fabricated $0 row here is the phantom the reader must never see.
        return None
    return {
        "session_id": session_id,
        "calls": int(llm.get("calls", 0) or 0),
        "retries": int(llm.get("retries", 0) or 0),
        "prompt_tokens": int(llm.get("prompt_tokens", 0) or 0),
        "completion_tokens": int(llm.get("completion_tokens", 0) or 0),
        "cost_usd": round(float(llm.get("cost_usd", 0.0) or 0.0), 6),
        "calls_without_cost": int(llm.get("calls_without_cost", 0) or 0),
        # #3359: a call that returned NO usage block at all (no tokens, no
        # charge) is a distinct disclosure from one that returned tokens but
        # no charge — both ride the row, so neither is silently a clean $0.
        "calls_without_usage": int(llm.get("calls_without_usage", 0) or 0),
        # #3359: deadline-killed generations are BILLED upstream but produce
        # no tokens, so they are spend this measurement cannot price. Carried
        # on the row so the report can disclose it instead of reading the
        # session as a clean $0 (#1787 P2-L is the counter's origin).
        "deadline_aborts": int(llm.get("deadline_aborts", 0) or 0),
        "by_stage": llm.get("by_stage") or {},
        # #3824: provider calls with no surviving roll-up. Rides the row so
        # the reader can count them into the denominator and refuse to read
        # the capture as a measured $0.
        "unattributed": unattributed,
    }


async def _emit_analytics_off_loop(org_id: str, event_name: str,
                                   properties: dict | None = None) -> None:
    """#4015: the shared off-loop entry point for a hosted funnel-event emit.

    It is the one entry point for the sites that #4352 routed through
    ``_cp_offload``; the capture-cost lane (``_emit_capture_ledger``) keeps its
    own ``asyncio.to_thread`` path — still off-loop, but on the loop's SHARED
    default executor, which the abuse hooks and the selfhost readiness probe
    also use, so it is not isolated the way this pool is — and ``mcp_server``
    its own retained emitter. Moving the capture lane onto this pool is #4468.

    ``_track_analytics_event`` is a synchronous ``httpx.Client`` POST and
    ``hosted_api`` runs a SINGLE uvicorn worker, so calling it inline from an
    ``async def`` handler stalls EVERY concurrent request for the duration of a
    Supabase round-trip (the #2988 / #3498 class). This routes it through the
    #3498 offload seam (``run_control_plane_call``, via ``_cp_offload``) on the
    dedicated ``telemetry`` pool: the auth-critical ``auth`` pool can never be
    parked by an analytics burst, and the event loop is never occupied.

    ``best_effort=True`` bounds FAILURE, not LATENCY — this emit is AWAITED,
    so a saturated telemetry pool can add up to the seam's
    ``CONTROL_PLANE_OFFLOAD_TIMEOUT_S`` (10 s) to ONE request before it returns
    (the bound is per call; a request that emits at several sites pays it per
    site). The emit is not fire-and-forget because the #3821 strict-mode
    escape below must be able to propagate, and a detached dispatch cannot
    carry it. The wait bound swallows an OFFLOAD failure — a missed bound or a
    saturated telemetry backlog — because telemetry must never gate the request
    path with an ERROR.

    The bound is deliberately BELOW the wrapped call's own worst case, which
    inverts the seam's usual "outer bound above inner bound" rule and is an
    accepted exception here: ``_ANALYTICS_POST_TIMEOUT_S`` is an httpx
    PER-PHASE timeout, so one POST can hold its worker for ~3x that. A
    `wait_for` expiry abandons the await, never the daemon thread (CPython
    #87185), so under sustained slow emits a worker keeps running for the
    remainder while the caller has already moved on. The trade is explicit:
    bounding the WORKER instead would make a slow-but-healthy telemetry sink
    gate a user request for longer than the seam's own budget allows.

    The ONE exception that still escapes is the #3821 strict-mode
    ``UnregisteredTelemetryKey``: that guard exists precisely so a misregistered
    prop cannot be silently swallowed, and the onboarding wrapper
    (``_track_onboarding_event``) depends on the escape.

    A caller whose failure path is UNRECOVERABLE guards the call itself: the
    Stripe webhook fires the billing notification FIRST and wraps this emit,
    because a raise there would land in its ``except Exception`` → a 500 AFTER
    the event was claimed, and the retry sees ``is_first=False`` — see
    ``webhooks_stripe``.
    """
    await _cp_offload(
        lambda: _track_analytics_event(org_id, event_name, properties),
        op="analytics_event", best_effort=True)


async def _track_onboarding_event(org: dict, event_name: str, **props) -> None:
    """Convenience: track with the current org, swallowing errors.

    #3821: the ONE exception that must escape this swallow is
    ``UnregisteredTelemetryKey`` — strict mode exists precisely so a
    misregistered prop cannot be silently swallowed by this wrapper.
    Everything else is still swallowed (analytics must never break the
    onboarding flow).

    #3498/#4015: async because the write it wraps is a blocking PostgREST call
    — ``_track_analytics_event`` builds a fresh ``httpx.Client(timeout=5)`` per
    event, which used to run ON the event loop from every async caller. The
    emit goes through the shared off-loop entry point; the strict-mode
    ``UnregisteredTelemetryKey`` still escapes (it is raised in the worker
    thread and re-raised through ``await``)."""
    try:
        await _emit_analytics_off_loop(org["org_id"], event_name, props or None)
    except UnregisteredTelemetryKey:
        raise
    except Exception:
        pass


# ── GitHub OAuth onboarding (#499) ──────────────────────────────

_GITHUB_AUTHORIZE_URL = "https://github.com/login/oauth/authorize"
_GITHUB_TOKEN_URL = "https://github.com/login/oauth/access_token"
_GITHUB_API = "https://api.github.com"
_GITHUB_STATE_TTL_S = 600  # 10 min
_GITHUB_STATES = {}  # state -> {org_id, org, created_at}
# NOTE (P1): in-memory — single-worker only (hosted_api runs 1 uvicorn worker
# on Fly, consistent with the auth cache, rate limiter, and _INDEX_JOBS).
# Multi-worker would need a shared store (Redis/FalkorDB) for CSRF state.


class GitHubConnectRequest(BaseModel):
    org: str | None = None


def _github_credentials(org_id: str) -> tuple[str | None, str | None]:
    """(github_token_enc, github_org) for an org — the single read path.

    Supabase mode (plan Task 6): reads ``teams.github_token_enc/github_org``
    via the service-role seam — the column is column-REVOKEd from
    anon/authenticated in migration 0006, so this seam is the ONLY reader in
    Supabase mode (never the registry). Registry mode: the Org node, for
    selfhost.
    """
    from tortoise.supabase_control import (
        get_control_plane,
        is_supabase_enabled,
    )
    from tortoise.supabase_control import (
        github_credentials as _sb_creds,
    )
    if is_supabase_enabled():
        row = _sb_creds(get_control_plane(), org_id)
        return row.get("github_token_enc"), row.get("github_org")
    sdk = _make_sdk(namespace="registry")
    rows = sdk._get_registry().query(
        "MATCH (t:Team {id: $id}) RETURN t.github_token_enc, t.github_org",
        params={"id": org_id},
    ).result_set
    if not rows:
        return None, None
    return rows[0][0], rows[0][1]


def _github_token_enc(org_id: str) -> str | None:
    """Encrypted GitHub token for an org (seam-aware — see _github_credentials)."""
    return _github_credentials(org_id)[0]


def _org_email(org_id: str) -> str | None:
    """Org email from the control plane — E2E-5 (plan Task 6).

    Supabase mode: ``teams.email`` via the service-role seam. Registry mode:
    the Org node (selfhost). None when unset/missing.
    """
    from tortoise.supabase_control import (
        get_control_plane,
        is_supabase_enabled,
    )
    from tortoise.supabase_control import (
        org_email as _sb_email,
    )
    if is_supabase_enabled():
        return _sb_email(get_control_plane(), org_id)
    sdk = _make_sdk(namespace="registry")
    rows = sdk._get_registry().query(
        "MATCH (t:Team {id: $id}) RETURN t.email",
        params={"id": org_id},
    ).result_set
    return rows[0][0] if rows else None


def _write_org_email(org_id: str, email: str) -> None:
    """Persist the org email on the control plane — E2E-5 (plan Task 6).

    Supabase mode: PATCH ``teams.email`` via the service-role seam. Registry
    mode: SET on the Org node. Raises on failure (fail-closed — a dropped
    email write must surface, not silently lose the value)."""
    from tortoise.supabase_control import (
        get_control_plane,
        is_supabase_enabled,
    )
    from tortoise.supabase_control import (
        update_org_email as _sb_email,
    )
    if is_supabase_enabled():
        _sb_email(get_control_plane(), org_id, email)
        return
    sdk = _make_sdk(namespace="registry")
    sdk._get_registry().query(
        "MATCH (t:Team {id: $id}) SET t.email = $email",
        params={"id": org_id, "email": email},
    )


async def _exchange_github_token(code: str) -> str:
    """Exchange an OAuth code for an access token (extracted for tests).

    Raises HTTPException(502) on transport/HTTP failure or a missing token.
    """
    client_id = os.environ.get("GITHUB_CLIENT_ID")
    client_secret = os.environ.get("GITHUB_CLIENT_SECRET")
    try:
        import httpx
        async with httpx.AsyncClient(timeout=15) as client:
            r = await client.post(_GITHUB_TOKEN_URL, data={
                "client_id": client_id, "client_secret": client_secret,
                "code": code,
            }, headers={"Accept": "application/json"})
            tok = r.json()
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"GitHub token exchange failed: {e}")  # noqa: B904
    access_token = tok.get("access_token")
    if not access_token:
        raise HTTPException(status_code=502, detail="GitHub token exchange failed")
    return access_token


def _github_repos_count(token: str) -> int | None:
    """Best-effort repo count for a connected token (None on any failure).

    Extracted for tests — the github_status endpoint keeps its behavior.
    (Blocking call inside the async endpoint — pre-existing behavior.)
    """
    repos_count = None
    try:
        import httpx
        with httpx.Client(timeout=10) as client:
            r = client.get(f"{_GITHUB_API}/user/repos?per_page=1",
                           headers={"Authorization": f"Bearer {token}",
                                    "Accept": "application/vnd.github+json"})
            if r.status_code == 200:
                import re
                link = r.headers.get("Link", "")
                m = re.search(r'page=(\d+)>; rel="last"', link)
                repos_count = int(m.group(1)) if m else len(r.json())
    except Exception:
        repos_count = None
    return repos_count


@app.post("/v1/onboarding/github/connect")
async def github_connect(body: GitHubConnectRequest | None = None,
                         org: dict = Depends(get_current_org_session_ungated)):  # noqa: B008
    """Initiate GitHub OAuth. Returns the authorize URL + CSRF state.

    #1828 review P3: same non-gated dual-auth as the other onboarding
    endpoints — the dashboard calls this with useSession: true."""
    # #2300: org-level control-plane surface (starts a ORG-wide OAuth +
    # registers org CSRF state) — graph-bound keys rejected (parity with
    # the github index/reindex endpoints; MCP twin tortoise_onboarding_
    # github_connect rejects graph-bound keys). A per-graph key must never
    # initiate the org's GitHub connection.
    _reject_graph_bound_org_surface(org, "github connect")
    import secrets
    from urllib.parse import urlencode
    client_id = os.environ.get("GITHUB_CLIENT_ID")
    if not client_id:
        raise HTTPException(status_code=503, detail="GitHub OAuth not configured")
    # #1845: NEVER default org to the internal org_id. The GitHub org/login
    # is derived from the token at callback time (GET /user → login); the
    # client cannot know it (the token is server-side encrypted). The old
    # ``or org["org_id"]`` fallback stored a hex UUID as github_org, which
    # made every org-scoped repo lookup 404 (empty selector). body.org (an
    # explicit client org) is still honored when provided.
    # NOTE (rename #3543): this local was `org` in the pre-rename codebase where
    # the auth dependency was named `team`. Renaming the dependency to `org`
    # collided with it — the local is now `gh_org` and `org` stays the dict.
    gh_org = (body.org if body else None)
    state = secrets.token_urlsafe(24)
    _GITHUB_STATES[state] = {
        "org_id": org["org_id"],
        "org": gh_org,
        "created_at": time.time(),
    }
    callback = os.environ.get("GITHUB_CALLBACK_URL",
                              "https://api.premiselabs.co/v1/onboarding/github/callback")
    params = {
        "client_id": client_id,
        "redirect_uri": callback,
        "scope": "repo",
        "state": state,
    }
    auth_url = f"{_GITHUB_AUTHORIZE_URL}?{urlencode(params)}"
    return {"auth_url": auth_url, "state": state}


@app.get("/v1/onboarding/github/callback")
async def github_callback(code: str | None = None, state: str | None = None,
                          error: str | None = None):
    """GitHub OAuth callback — exchange code, store encrypted token, redirect.

    `error` is the standard OAuth denial query param. (Note: tests must use
    follow_redirects=False — the 302 target is the external welcome page.)
    """
    # #1135: welcome page lives on the static-Pages host — derive from the
    # same env-driven base as the email links (EMAIL_LINK_BASE_URL), never a
    # second hardcoded host literal.
    from tortoise.email_notify import email_link_base
    welcome_url = f"{email_link_base()}/welcome.html"

    if error:
        await _emit_analytics_off_loop(
            "", "onboarding_error",
            {"step": "github_connect", "error_type": "oauth_denied"})
        return RedirectResponse(f"{welcome_url}?github=denied", status_code=302)

    # Validate state — 404 on missing/invalid (don't leak existence)
    st = _GITHUB_STATES.pop(state, None) if state else None
    if not st:
        raise HTTPException(status_code=404, detail="Not found")
    if time.time() - st["created_at"] > _GITHUB_STATE_TTL_S:
        raise HTTPException(status_code=404, detail="Not found")
    if not code:
        raise HTTPException(status_code=404, detail="Not found")

    client_id = os.environ.get("GITHUB_CLIENT_ID")
    client_secret = os.environ.get("GITHUB_CLIENT_SECRET")
    if not client_id or not client_secret:
        raise HTTPException(status_code=503, detail="GitHub OAuth not configured")

    # Exchange code for token
    access_token = await _exchange_github_token(code)

    # #1845: derive the real GitHub login from the token (GET /user). The
    # dashboard never sends body.org, so the old flow stored the internal
    # org_id UUID as github_org — every org-scoped lookup 404'd (empty
    # selector). The login IS the org for the org-wide scope (the token's
    # repos / orgs are resolved under it). Falls back to an explicit
    # body.org from the connect state when the /user call fails.
    from tortoise.indexer.github_indexer import GitHubIndexer
    org = st["org"]
    try:
        login_indexer = GitHubIndexer(access_token)
        try:
            login = await login_indexer.current_login()
        finally:
            await login_indexer._close()
        if login:
            org = login
    except Exception:
        pass  # best-effort — an explicit body.org (or None) survives

    # Encrypt + store on the Org record (never log the raw token).
    # Supabase mode (plan Task 6): PATCH orgs via the service-role seam —
    # github_token_enc is column-REVOKEd from anon/authenticated (migration
    # 0006); the seam is the only write path. Rotation: every reconnect
    # overwrites the previous encrypted token in place (see
    # store_github_credentials docstring).
    from tortoise.crypto import encrypt_token
    encrypted = encrypt_token(access_token)
    org_id = st["org_id"]
    from tortoise.supabase_control import (
        get_control_plane,
        is_supabase_enabled,
    )
    from tortoise.supabase_control import (
        store_github_credentials as _sb_store,
    )
    if is_supabase_enabled():
        _sb_store(get_control_plane(), org_id, token_enc=encrypted, org=org)
    else:
        sdk = _make_sdk(namespace="registry")
        sdk._get_registry().query(
            "MATCH (t:Team {id: $id}) SET t.github_token_enc = $tok, t.github_org = $org",
            params={"id": org_id, "tok": encrypted, "org": org},
        )
    _update_onboarding_state(org_id, github_connected=True)
    # Auto-index after connect (Task 5, amend 11): background first-run
    # (ONE repo — bounded, P2-4). The job is created under the org's
    # single-flight guard; an indexing failure surfaces honestly via the
    # job poll, never the redirect (the user lands on welcome.html either
    # way). P1-1 (PR #1792): spawn the run ONLY when the job was
    # freshly minted — a reused in-flight job is already being walked.
    job_id, is_new = _start_index_job(org_id)
    if is_new:
        import asyncio as _asyncio
        _asyncio.get_event_loop().create_task(
            _run_indexing(job_id, org_id, org, None))
    await _emit_analytics_off_loop(
        org_id, "question_answered",
        {"question_id": "github_connect", "answer": "yes"})
    return RedirectResponse(f"{welcome_url}?github=connected", status_code=302)


async def _heal_github_org(org_id: str, encrypted: str,
                          org: str | None) -> str | None:
    """#1845 self-heal: return the REAL org/login for a connected token.

    The pre-#1845 connect flow stored the internal org_id UUID as
    github_org (the dashboard never sent body.org, and the server defaulted
    to ``org["org_id"]``). That made every org-scoped lookup 404 (the
    empty source-scope selector). When the stored org is missing or is the
    org_id, derive the token's login via ``GET /user`` and PATCH it back so
    the fix is permanent (a reconnect is NOT required). Best-effort: any
    failure returns the stored org unchanged (the resolver's /user/repos
    fallback still lists the token's repos).
    """
    if org and org != org_id:
        return org
    from tortoise.crypto import decrypt_token
    try:
        token = decrypt_token(encrypted)
    except ValueError:
        return org
    from tortoise.indexer.github_indexer import GitHubIndexer
    login = None
    indexer = GitHubIndexer(token)
    try:
        login = await indexer.current_login()
    except Exception:
        login = None
    finally:
        await indexer._close()
    if not login or login == org:
        return login or org
    from contextlib import suppress
    with suppress(Exception):
        # Review: the heal write must NEVER 500 the read endpoints it feeds
        # (github_status/repos/branches promise "never a 500"). A control-
        # plane blip during the one-time patch falls back to the resolver's
        # /user/repos fallback on the next call — the login is returned
        # either way.
        _store_github_org(org_id, encrypted, login)
    return login


def _store_github_org(org_id: str, encrypted: str, org: str) -> None:
    """PATCH the stored github_org (seam-aware — mirrors the callback's
    store path, preserving the existing encrypted token)."""
    from tortoise.supabase_control import (
        get_control_plane,
        is_supabase_enabled,
    )
    from tortoise.supabase_control import (
        store_github_credentials as _sb_store,
    )
    if is_supabase_enabled():
        _sb_store(get_control_plane(), org_id, token_enc=encrypted, org=org)
    else:
        sdk = _make_sdk(namespace="registry")
        sdk._get_registry().query(
            "MATCH (t:Team {id: $id}) SET t.github_org = $org",
            params={"id": org_id, "org": org},
        )


def _cleanup_legacy_docs_corpus(org_id: str,
                                walk_items: list[tuple[str, str | None]]) -> None:
    """Review (deep bug scan): remove a pre-#1845 UNQUALIFIED docs corpus.

    The old docs layout staged at {base}/{org}/{owner}/{repo}/docs/... with
    a .manifest/{owner}/{name}.json; the #1845 branch-qualified layout
    stages under {owner}/{repo}/{branch}/docs/... and would INGEST the
    legacy corpus too (same content, two doc ids — duplicates that the new
    per-branch manifest can never reconcile away). Best-effort: removes the
    legacy unqualified docs/ dir + legacy manifest for each scoped repo when
    they exist. Never removes branch-qualified dirs (those live one level
    deeper). No prod org ever had a legacy corpus (github_docs_indexed was
    false for every connected org — the old connect bug 404'd every
    org-scoped walk), so this is a defensive guard for API clients that
    used the old open endpoint.
    """
    from tortoise.indexer.github_docs import GitHubDocsIndexer
    org_root = GitHubDocsIndexer.org_root(org_id)
    for repo_name, _branch in walk_items:
        parts = repo_name.split("/", 1)
        if len(parts) != 2:
            continue
        owner, name = parts
        legacy_dir = org_root / owner / name / "docs"
        legacy_manifest = org_root / ".manifest" / owner / f"{name}.json"
        try:
            if legacy_dir.is_dir():
                import shutil
                shutil.rmtree(legacy_dir, ignore_errors=True)
        except OSError:
            pass  # best-effort
        try:
            if legacy_manifest.is_file():
                legacy_manifest.unlink(missing_ok=True)
        except OSError:
            pass  # best-effort


@app.get("/v1/onboarding/github/status")
async def github_status(org: dict = Depends(get_current_org_session_ungated)):  # noqa: B008
    """Return GitHub connection status + repo count.

    #1828 review P3: same non-gated dual-auth as the other onboarding
    endpoints — the dashboard calls this with useSession: true. #1845:
    self-heals a legacy org_id-as-org (see _heal_github_org) so the
    selector's org is real.
    """
    # #2300: reads org-level GitHub credential state (control-plane) —
    # graph-bound keys rejected (MCP twin tortoise_onboarding_github_status
    # parity). A per-graph key must never observe the org's GitHub org.
    _reject_graph_bound_org_surface(org, "github status")
    _org_id = org["org_id"]
    encrypted, gh_org = _github_credentials(_org_id)
    if not encrypted:
        return {"connected": False, "org": None, "repos_count": None}
    from tortoise.crypto import decrypt_token
    try:
        token = decrypt_token(encrypted)
    except ValueError:
        return {"connected": False, "org": None, "repos_count": None}
    gh_org = await _heal_github_org(_org_id, encrypted, gh_org)
    # #3498 (the audit's §A1 item 9): _github_repos_count is a BLOCKING
    # httpx.Client call to api.github.com — off the loop.
    repos_count = await _cp_offload(
        lambda: _github_repos_count(token), op="github_repos_count",
        best_effort=True)
    return {"connected": True, "org": gh_org, "repos_count": repos_count}


@app.get("/v1/onboarding/github/repos")
async def github_repos(org: dict = Depends(get_current_org_session_ungated)):  # noqa: B008
    """List the connected org's repo names for the source-scope selector (#1845).

    The GitHub token is server-side encrypted (never on the client), so the
    dashboard CANNOT enumerate repos via the GitHub API directly — this is the
    single read path. Mirrors github_status: same non-gated dual-auth, same
    decrypt-then-best-effort shape. A resolve failure returns an EMPTY list
    (the selector still renders its "All repos" default), never a 500 — the
    selector must render even when GitHub is unreachable.

    Returns SHORT repo names (owner prefix stripped) — the /v1/index/*
    endpoints already construct ``f"{org}/{repo}"`` from the short name, so
    sending a full_name would double-prefix the org.

    #1893 (code-review P1): any response whose repos are EMPTY because of a
    FAILURE (resolve exception, decrypt failure) carries ``resolve_error:
    true`` so the dashboard never treats a failed fetch as a genuinely-empty
    org (pruning the persisted scope on it would clobber the selection).
    ``connected: false`` + ``resolve_error`` is the "stored-but-now-failing"
    shape; a clean disconnect returns connected:false WITHOUT the flag.
    """
    # #2300: lists the ORG's connected org repos (control-plane credential
    # state) — graph-bound keys rejected (MCP/onboarding-github parity). A
    # per-graph key must never enumerate the org's GitHub org repos.
    _reject_graph_bound_org_surface(org, "github repos")
    _org_id = org["org_id"]
    encrypted, gh_org = _github_credentials(_org_id)
    if not encrypted:
        return {"connected": False, "org": None, "repos": []}
    from tortoise.crypto import decrypt_token
    try:
        token = decrypt_token(encrypted)
    except ValueError:
        # decrypt failure = the stored token is unusable — a resolve-class
        # failure, not evidence of an empty org (the dashboard gates
        # hydration on this flag exactly like a resolve exception).
        return {"connected": False, "org": None, "repos": [], "resolve_error": True}
    gh_org = await _heal_github_org(_org_id, encrypted, gh_org)
    from tortoise.indexer.github_indexer import GitHubIndexer
    indexer = GitHubIndexer(token)
    resolve_error = False
    try:
        resolved = await indexer.resolve_repos(gh_org)
    except Exception:
        # resolve failure → empty list (selector still renders "All repos"),
        # but FLAG it: the dashboard must not treat a failed resolve as a
        # genuinely-empty org — pruning the persisted scope on it would
        # clobber the stored selection (#1893, code-review P1).
        resolved = []
        resolve_error = True
    finally:
        await indexer._close()
    # short names (owner prefix stripped) — see the endpoint docstring.
    repos = [r.split("/", 1)[1] if "/" in r else r for r in resolved]
    payload = {"connected": True, "org": gh_org, "repos": repos}
    if resolve_error:
        payload["resolve_error"] = True
    return payload


@app.get("/v1/onboarding/github/branches")
async def github_branches(repo: str,
                          org: dict = Depends(get_current_org_session_ungated)):  # noqa: B008
    """List a repo's branch names for the source-scope selector (#1845).

    Mirrors /v1/onboarding/github/repos: same non-gated dual-auth, same
    decrypt-then-best-effort shape, server-side token (the client never
    calls GitHub directly). ``repo`` is a SHORT name (the stored org is
    prepended server-side — sending a full_name would double-prefix). A
    resolve failure returns an EMPTY branch list (the selector still
    renders its default branch), never a 500. Review P2-4: also returns
    the repo's API-reported ``default_branch`` (GET /repos/{repo}) so the
    picker can label/seed its default option truthfully for repos whose
    default is neither main nor master.
    """
    # #2300: lists the ORG's connected repo branches (control-plane
    # credential state) — graph-bound keys rejected (onboarding-github
    # family parity — a per-graph key must never enumerate the org's
    # GitHub branches).
    _reject_graph_bound_org_surface(org, "github branches")
    _org_id = org["org_id"]
    encrypted, gh_org = _github_credentials(_org_id)
    if not encrypted:
        return {"connected": False, "org": None, "repo": repo,
                "branches": [], "default_branch": None}
    from tortoise.crypto import decrypt_token
    try:
        token = decrypt_token(encrypted)
    except ValueError:
        return {"connected": False, "org": None, "repo": repo,
                "branches": [], "default_branch": None}
    gh_org = await _heal_github_org(_org_id, encrypted, gh_org)
    if not gh_org:
        return {"connected": True, "org": None, "repo": repo,
                "branches": [], "default_branch": None}
    # #1845 (review P1 parity): repo is a client-supplied value that reaches
    # the GitHub URL path — allowlist SHORT names (same conservative token
    # as github_reindex / github_docs._safe_segment).
    repo = (repo or "").strip()
    if not re.match(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$", repo):
        raise HTTPException(status_code=400, detail="Invalid repo name")
    from tortoise.indexer.github_indexer import GitHubIndexer
    indexer = GitHubIndexer(token)
    branches = []
    default_branch = None
    try:
        branches = await indexer.list_branches(f"{gh_org}/{repo}")
    except Exception:
        branches = []  # review P2-4: list failure degrades to empty
    try:
        default_branch = await indexer.default_branch(f"{gh_org}/{repo}")
    except Exception:
        default_branch = None  # review P2-4: default unknown is non-fatal
    finally:
        await indexer._close()
    return {"connected": True, "org": gh_org, "repo": repo,
            "branches": branches, "default_branch": default_branch}



# ── GitHub indexing endpoints (#499 Task 5) ─────────────────────

_INDEX_JOBS: dict[str, dict] = {}  # job_id -> {status, progress, points_created, error, created_at, started_at, org_id}
# Owner/generation token per job (P2, PR #1792): a TTL-evicted entry
# (presumed-dead, replaced by a newer run) must not let the stale run keep
# writing status / resurrect a live walk. Kept OUT of the job dict so the
# poll response can never leak it.
_INDEX_JOB_OWNERS: dict[str, str] = {}

# Per-org single-flight TTL (T2-P2 + cycle-3 P1-3): a `started` entry
# older than this is presumed dead (Fly restart / hung run) — evicted so a
# hung run never bricks the org; the just-reused in-flight entry is never
# evicted. Single-process assumption recorded: per-event-loop atomic; a
# DB-backed job lock is the documented path only if Fly scales horizontally.
_INDEX_JOB_TTL_S = 30 * 60
# Post-terminal eviction (T1-P14): the job stays pollable for an hour, then
# vanishes — the UI renders an eviction-expired poll as "status expired".
_INDEX_JOB_EVICT_S = 3600


def _start_index_job(org_id: str, *, kind: str = "github") -> tuple[str, bool]:
    """Per-org single-flight job creation (T2-P2, ordered algorithm).

    Returns ``(job_id, is_new)``: ``is_new=False`` means an in-flight
    `started` job for the org was REUSED — the caller MUST NOT spawn a
    second ``_run_indexing`` task (P1-1, PR #1792: single-flight dedupes
    the RUN, not just the entry; spawning on every POST ran two concurrent
    walks → duplicate statement ids + version inflation + job-status
    races).

    ``kind`` scopes the guard ("github" | "docs", #1726): the docs job
    shares the org-scoped ``_INDEX_JOBS`` store but its single-flight is
    kind-scoped — an in-flight github walk never blocks/blends a docs job
    and vice versa.

    1. Guard-check FIRST: a `started` entry for the org AND kind is
       REUSED (return its job_id with is_new=False) — kills the TOCTOU
       probe→create duplicate.
    2. Only then evict terminal entries or `started` older than the 30-min
       TTL (presumed-dead); the just-reused in-flight entry is never
       evicted.
    3. Otherwise mint a fresh job entry (is_new=True) stamped with a
       generation/owner token.
    """
    import secrets
    now = time.time()
    for jid, job in list(_INDEX_JOBS.items()):
        if job.get("org_id") != org_id:
            continue
        if job.get("kind", "github") != kind:
            continue
        if job.get("status") == "started":
            started = job.get("started_at") or job.get("created_at") or now
            if now - started < _INDEX_JOB_TTL_S:
                return jid, False  # guard-check FIRST — reuse the in-flight job
            # presumed-dead (TTL exceeded) — evict, then fall through
            _INDEX_JOBS.pop(jid, None)
            _INDEX_JOB_OWNERS.pop(jid, None)
            continue
        # terminal → evict (T1-P14: clear stale entries on enqueue)
        _INDEX_JOBS.pop(jid, None)
        _INDEX_JOB_OWNERS.pop(jid, None)
    job_id = secrets.token_hex(8)
    _INDEX_JOBS[job_id] = {"status": "started", "progress": 0,
                           "points_created": 0, "error": None,
                           "org_id": org_id, "kind": kind,
                           "created_at": now,
                           "started_at": now}
    _INDEX_JOB_OWNERS[job_id] = secrets.token_hex(8)
    return job_id, True


class GitHubIndexRequest(BaseModel):
    org: str
    repo: str | None = None


class GitHubRepollRequest(BaseModel):
    """#1845: optional repo scope for the issues re-poll (diff).

    ``org`` is deliberately ABSENT — the re-poll reads org from the stored
    credentials (never trusted from the client); only the repo scope is
    client-supplied. ``repos`` is a list of SHORT names (the indexer
    prepends org/); empty/absent = ALL repos (org-wide diff). ``repo`` is
    the legacy single-repo field (kept for backward compat — a value here
    is equivalent to ``repos=[repo]``).
    """
    repos: list[str] | None = None
    repo: str | None = None


# #1893: the SHORT-repo-name charset is shared between the persisted-scope
# validator and _validate_repo_scope — legacy inline copies also exist at
# other index-surface call sites; new validators MUST use this constant
# (keep-in-sync — a charset change lands in ALL copies).
_SHORT_REPO_NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$")


def _validate_scope_payload(updates: dict) -> dict:
    """#1893: PATCH-boundary validation for the persisted source-scope keys
    (github_issues_scope / github_docs_scope). Same conservative surface as
    the index endpoints — _validate_repo_scope for issues (short names,
    deduped), _is_safe_branch for docs branches. [] is a VALID value
    (explicit clear = all repos) and is stored as-is — the persist path
    NEVER omits empty (unlike the job builders, where absent = all)."""
    if "github_issues_scope" in updates and updates["github_issues_scope"] is not None:
        repos = _validate_repo_scope(updates["github_issues_scope"])
        updates["github_issues_scope"] = repos if repos is not None else []
    if "github_docs_scope" in updates and updates["github_docs_scope"] is not None:
        scopes: list[dict] = []
        seen_repos: set[str] = set()  # FIRST-WINS dedupe (API boundary — see note)
        # ⚠️ dedupe asymmetry (intentional): the server dedupes FIRST-WINS
        # (raw API boundary — the client already serializes unique repos),
        # while the dashboard's reconcileDocsScope dedupes LAST-WINS
        # (defensive corrupt-data path). Do NOT "align" one to the other —
        # tests pin each contract (test_scope_keys_normalized_at_patch /
        # sourceScope.test.js dedup-last-wins).
        for s in updates["github_docs_scope"]:
            if not isinstance(s, dict) or not isinstance(s.get("repo"), str):
                raise HTTPException(status_code=400, detail="Invalid repo scope")
            repo = s["repo"].strip()
            if not _SHORT_REPO_NAME_RE.match(repo):
                raise HTTPException(status_code=400, detail="Invalid repo name")
            branch = s.get("branch")
            if branch == "" or branch is None:
                branch = None
            else:
                if not isinstance(branch, str):  # non-str branch → 400, never 500
                    raise HTTPException(status_code=400, detail="Invalid branch")
                branch = branch.strip()  # normalize like repo (padded branches never persist)
                if not _is_safe_branch(branch):
                    raise HTTPException(status_code=400, detail="Invalid branch")
            if repo not in seen_repos:
                seen_repos.add(repo)
                scopes.append({"repo": repo, "branch": branch})
        updates["github_docs_scope"] = scopes
    return updates


def _validate_repo_scope(repos: list[str] | None) -> list[str] | None:
    """#1845 (review P1): allowlist SHORT repo names (the ONE
    client-supplied value that reaches the GitHub URL path). Rejects (400)
    rather than walk a repo the user never picked. Empty/None stays None
    (full-org scope). Review P3-1: a blank entry INSIDE a non-empty list is
    rejected (400) — silently dropping it would turn a client bug into an
    unintended org-wide diff."""
    if not repos:
        return None
    out: list[str] = []
    for r in repos:
        if not isinstance(r, str):
            raise HTTPException(status_code=400, detail="Invalid repo name")
        r = r.strip()
        if not r:
            raise HTTPException(status_code=400, detail="Invalid repo name")
        if not _SHORT_REPO_NAME_RE.match(r):
            raise HTTPException(status_code=400, detail="Invalid repo name")
        if r not in out:
            out.append(r)
    return out or None


# Git-ref-safe branch token (review P1-1): git refs can NEVER contain "..",
# "@{}", spaces, control chars, or "~^:?*[\\" — but MAY contain "/"
# (feature/x). This is the same conservative surface the fetcher walks.
# ⚠️ keep-in-sync with github_docs._safe_branch — both guard the same
# client branch before URL interpolation (API layer + fetcher defense-in-
# depth); a charset change must land in BOTH.
_SAFE_BRANCH_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._/\-]{0,127}$")


def _is_safe_branch(branch: object) -> bool:
    """#1845 (review P1-1): reject a client branch before it reaches the
    GitHub URL path. Dot-segment traversal ("../../victimorg/x") and other
    git-ref-unsafe tokens must never be interpolated into the tree URL.
    "all" (the multi-branch marker) is allowed; ".." is not a valid git
    ref segment and is rejected. An empty string ("" = the DEFAULT branch
    contract) and None are treated as SAFE by the caller — the scope
    builder normalizes them to None before this check."""
    if not isinstance(branch, str):
        return False
    branch = branch.strip()
    if not branch:
        return False
    if branch == "all":
        return True
    if ".." in branch or "//" in branch:
        return False
    return bool(_SAFE_BRANCH_RE.match(branch))


async def _run_indexing(job_id: str, org_id: str, org: str,
                        repos: list[str] | None) -> None:
    """Background indexing job: GitHub issues/PRs → entities/events.

    #1725 Slice 0 rework: cursor-correct (composite (updated_at, number)
    per-repo cursors persisted to onboarding jsonb), ONE-repo bounded first
    run, one-time legacy `-closed` backfill (marker-gated), honest status
    ("N issues beyond window", quota_hit, errors, partial completion).
    #1844: OBJECT-ONLY — zero non-episodic :Point writes, so no points-quota
    gate (see the pre-walk comment; the #1843 statement-write resurrection
    #1845: ``repos`` is a list of SHORT repo names (None/empty = ALL repos,
    org-wide diff). The first-run ONE-repo bound applies to the org-wide
    path only — an explicit repos list walks exactly those repos even on
    the first run (the user scoped them deliberately).
    would re-add it).

    P1-1 / P2 (PR #1792): every caller spawns this task ONLY when
    `_start_index_job` reports is_new; as a belt-and-suspenders guard this
    function ALSO aborts when it no longer owns the job entry (TTL-evicted
    / replaced by a newer run) — a stale run must never keep writing
    status or resurrect a live walk.
    """
    from tortoise.indexer.github_indexer import GitHubFetchError, GitHubIndexer
    # P2: generation/owner token stamped at mint. A TTL-evicted entry
    # (presumed-dead, replaced by a newer run) must not let THIS run keep
    # writing status — it aborts silently at the next status-write or
    # repo boundary.
    owner = _INDEX_JOB_OWNERS.get(job_id)

    def _job(**fields) -> None:
        """Update the job entry ONLY while this run still owns it."""
        if _INDEX_JOB_OWNERS.get(job_id) != owner:
            return  # entry evicted/replaced — abort silently
        job = _INDEX_JOBS.get(job_id)
        if job is not None:
            job.update(fields)

    try:
        encrypted = _github_token_enc(org_id)
    except Exception:
        # Fail-closed: a control-plane outage must not leave the job stuck at
        # "started" — mark it failed so the poller reports a real error.
        _job(status="failed", error="Control plane unavailable")
        return
    if not encrypted:
        _job(status="failed", error="GitHub not connected")
        return
    from tortoise.crypto import decrypt_token
    try:
        token = decrypt_token(encrypted)
    except ValueError:
        _job(status="failed", error="Token undecryptable")
        return
    # State + cursors loaded BEFORE the walk try: the finally persists them
    # back, so a pre-walk failure (resolve_repos 404, pre-walk raise) must
    # never WIPE previously-persisted cursors (P2, PR #1792).
    state = _get_onboarding_state(org_id)
    cursors: dict[str, dict] = state.get("github_index_cursor") or {}
    totals = {"points_created": 0, "statements_superseded": 0,
              "events_minted": 0, "issues_beyond_window": 0,
              "repos_processed": 0, "errors": [], "quota_hit": False,
              "backfill_minted": 0, "cleared_truncated": False}
    try:
        org_sdk = _make_sdk(namespace=org_id)

        # #1844: the index job is OBJECT-ONLY — it writes zero non-episodic
        # :Point nodes (the "points" quota resource counts ONLY
        # `MATCH (n:Point) WHERE n.is_episodic IS NULL OR false`), so no
        # points-quota preflight or per-batch re-check is needed. A org at
        # its points cap must still be able to index issues. The #1843
        # statement-write resurrection (point/statement mints) would re-add
        # the points gate.
        indexer = GitHubIndexer(token)

        # ── One-time legacy `-closed` backfill (T1-P1 + T2-P3). Gated on the
        # persisted marker; scans PRE-EXISTING events ONLY (before the walk
        # mints fresh ones) so fresh first-runs never double-mint; normal diff
        # never mints `-closed` for closed-without-`-closed` on re-runs. The
        # marker is set ONLY on success — a transient failure must not skip
        # the one-time migration forever (P2, PR #1792). ──
        if not state.get("github_legacy_backfill_done"):
            try:
                totals["backfill_minted"] = indexer.backfill_legacy_closed(
                    org_sdk._get_proj())
            except Exception as e:
                _logger.warning(
                    "legacy -closed backfill failed (team=%s): %s", org_id, e)
            else:
                _update_onboarding_state(
                    org_id, github_legacy_backfill_done=True)

        # ── Cursor + repo scope (Tasks 2/4). First-run scope = ONE repo
        # regardless of org size (P2-4 pre-decided fallback) with the honest
        # "index more" affordance (re-poll re-runs with the cursor).
        # #1845: an explicit ``repos`` list (SHORT names) scopes the walk to
        # exactly those repos; None/empty = org-wide (resolve, then bound
        # the first run to ONE repo). ──
        first_run = not bool(state.get("github_indexed"))
        if repos:
            walk_repos = [f"{org}/{r}" for r in repos]
        else:
            # Review (deep bug scan): the org-wide WALK path must fail
            # honestly on a 404 org, never silently walk the token user's
            # personal namespace — only the selector keeps the /user/repos
            # fallback (allow_user_fallback=False).
            walk_repos = await indexer.resolve_repos(
                org, allow_user_fallback=False)
            if first_run:
                walk_repos = walk_repos[:1]

        for repo_name in walk_repos:
            if _INDEX_JOB_OWNERS.get(job_id) != owner:
                break  # lost ownership (entry evicted/replaced) — abort
            result = await indexer.index_repo(
                org_sdk, repo_name, cursor=cursors.get(repo_name) or None)
            totals["points_created"] += result["points_created"]
            totals["statements_superseded"] += result["statements_superseded"]
            totals["events_minted"] += result["events_minted"]
            totals["issues_beyond_window"] += result["issues_beyond_window"]
            totals["errors"].extend(result["errors"])
            if result.get("cursor"):
                cursors[repo_name] = result["cursor"]
            if result.get("quota_hit"):
                totals["quota_hit"] = True
                break
            totals["repos_processed"] += 1
            # #1989 review round 2: surface the DRAIN→DIFF heal so an
            # operator can distinguish a fully-drained backlog from a stuck
            # one (the job body would otherwise only show an inflated
            # issues_beyond_window estimate with no per-repo signal).
            if result.get("cleared_truncated"):
                totals["cleared_truncated"] = True
            # #1894: live per-repo progress — the poll surfaces honest
            # mid-walk state (progress/repos/points) so the dashboard can
            # render an ETA from REAL signal (never fabricated). Written
            # AFTER the increment so the quota-hit repo (which breaks BEFORE
            # it) is never counted as processed.
            _job(progress=round(totals["repos_processed"] * 100
                                / max(len(walk_repos), 1)),
                 points_created=totals["points_created"],
                 repos_processed=totals["repos_processed"],
                 repos_total=len(walk_repos))

        _job(status="completed", progress=100,
             points_created=totals["points_created"],
             statements_superseded=totals["statements_superseded"],
             events_minted=totals["events_minted"],
             repos_processed=totals["repos_processed"],
             repos_total=len(walk_repos),
             issues_beyond_window=totals["issues_beyond_window"],
             backfill_minted=totals["backfill_minted"],
             quota_hit=totals["quota_hit"],
             cleared_truncated=totals["cleared_truncated"],
             errors=totals["errors"],
             error=None)
        # #1727 Slice 2 (Task 12, T1-P15): re-run the entity-linking pass
        # on index COMPLETION — sessions captured before their entities
        # materialized now resolve (the capture-time links were honest
        # no-matches then). Owned by the completion hook, never a separate
        # endpoint.
        _relink_sessions_after_index(org_id)
    except GitHubFetchError as e:
        # Mid-walk 401/429 / unresolved org (T1-P13 + P2): honest "failed"
        # status with a readable error; the cursor was NOT advanced past
        # unprocessed items (the indexer only returns it for processed
        # items) — a re-run resumes without gaps/dupes (idempotent writes
        # make overlap harmless).
        _job(status="failed", error=str(e))
    except Exception as e:
        _job(status="failed", error=str(e))
    finally:
        # P2: persist per-repo cursors + github_indexed in a finally so
        # PARTIAL runs (mid-walk raise) leave a resumable state —
        # previously the accumulated cursors were lost on
        # a mid-walk raise and the next run re-walked from the old cursor.
        # github_indexed flips True ONLY on real progress (>=1 repo
        # processed): a 0-repo failure (resolve_repos 404, pre-walk raise)
        # leaves it untouched so the next run keeps the ONE-repo
        # bounded first-run pacing (P2, PR #1792).
        updates: dict = {"github_index_cursor": cursors}
        if totals["repos_processed"] > 0:
            updates["github_indexed"] = True
            # #1894: stamp the last-indexed timestamp in the SAME branch that
            # flips the bool (parity semantics — "last time indexing ran and
            # made progress", incl. quota-partial/mid-walk-error runs with >=1
            # repo processed, mirroring github_indexed's resumable-cursor
            # behavior).
            updates["github_indexed_at"] = datetime.now(UTC).isoformat()
        _update_onboarding_state(org_id, **updates)
        # Evict after an hour (T1-P14: eviction-expired polls render
        # honestly).
        import asyncio as _asyncio
        _asyncio.get_running_loop().call_later(
            _INDEX_JOB_EVICT_S,
            lambda: (_INDEX_JOBS.pop(job_id, None),
                     _INDEX_JOB_OWNERS.pop(job_id, None)))


def _relink_sessions_after_index(org_id: str) -> None:
    """#1727 Slice 2 (Task 12, T1-P15): re-run the entity-linking pass for
    the org's captured sessions after an index completes.

    Sessions captured BEFORE their entities materialized carried honest
    no-match links; once the index lands (entities minted), the pass resolves
    them. Best-effort: a failure is logged, never fatal to the job status.
    """
    try:
        from .session_link import link_session_entities
        # #3664: pass the SDK so the re-linked edges CAN be journaled — but on
        # this lane _make_sdk/_data_sdk set no `event_log_path` and
        # `EntityLinked` is JSONL-only (absent from _GRAPH_EVENT_TYPES), so
        # `sdk._emit_event` is a no-op here (the same lane limit the turn
        # record's note in _capture_session_impl documents). The re-linked
        # edges are therefore live-only on the hosted lane; the JSONL-journal
        # gap is filed as #4240. Do NOT read the `sdk=` argument as journaling.
        _link_sdk = _make_sdk(namespace=org_id)
        proj = _link_sdk._get_proj()
        rows = proj.g.query(
            "MATCH (s:Session)-[:CONTAINS]->(t:Point) "
            "WHERE t.pointKind='event' "
            "RETURN s.id, t.id, t.content").result_set
        by_session: dict[str, tuple[list[str], list[str]]] = {}
        for sid, tid, content in rows:
            by_session.setdefault(sid, ([], []))
            by_session[sid][0].append(str(content or ""))
            by_session[sid][1].append(tid)
        for sid, (texts, tids) in by_session.items():
            result = link_session_entities(proj, sid, texts, turn_ids=tids,
                                           sdk=_link_sdk)
            if result["attempted"]:
                proj.g.query(
                    "MATCH (s:Session {id:$sid}) SET "
                    "s.entity_links_attempted=$a, s.entity_links_created=$c",
                    params={"sid": sid, "a": result["attempted"],
                            "c": result["created"]})
    except Exception:
        _logger.exception(
            "session re-linking after index failed (team=%s)", org_id)


@app.post("/v1/index/github")
async def index_github(body: GitHubIndexRequest, org: dict = Depends(get_current_org_session_ungated)):  # noqa: B008
    """Start a background GitHub indexing job (Q2). Returns job_id for polling.

    Per-org single-flight (T2-P2 + P1-1): an in-flight `started` job for
    the org is REUSED (its job_id returned) and the run is spawned ONLY
    for a freshly-minted job — concurrent POSTs can never run two walks
    (duplicate statement ids, version inflation, job-status races).
    """
    # C5 #2114 (re-review P1): indexing WRITES entities/events/sources into
    # the org's DEFAULT graph via a background job (invisible to the
    # endpoint-body _make_sdk inventory). Write scope required + graph-bound
    # keys rejected (cross-graph write prevention).
    _require_scope(org, "graphs:write", "github index")
    _reject_graph_bound_org_surface(org, "github index")
    gh_org = (body.org or "").strip()
    if not gh_org:
        raise HTTPException(status_code=400, detail="org is required")
    # Verify GitHub connected first (seam-aware read — Supabase orgs in
    # Supabase mode, registry for selfhost)
    encrypted = _github_token_enc(org["org_id"])
    if not encrypted:
        raise HTTPException(status_code=400, detail="GitHub not connected. Run connect first.")
    job_id, is_new = _start_index_job(org["org_id"])
    if is_new:
        import asyncio as _asyncio
        _asyncio.get_event_loop().create_task(
            _run_indexing(job_id, org["org_id"], gh_org,
                          _validate_repo_scope([body.repo] if body.repo else None)))
    return {"job_id": job_id, "status": "started"}


@app.post("/v1/index/github/re-poll")
async def github_reindex(body: GitHubRepollRequest | None = None,
                         org: dict = Depends(get_current_org_session_ungated)):  # noqa: B008
    """Re-run the GitHub diff (diff-on-poll, amend 6) for the connected org.

    C5 #2114 (re-review P1): reindex WRITES into the DEFAULT graph.
    _require_scope + graph-bound rejection (see index_github).
    The ONLY route shape (T1-P2) — no query-param alternative. Reuses the
    persisted per-repo composite cursors, so a re-poll is an incremental
    diff, not a re-ingest. Declared BEFORE /v1/index/github/{job_id} so the
    literal path wins over the job_id path param.

    #1845: accepts an OPTIONAL ``repos`` scope (list of SHORT names). When
    set, the diff walks ONLY those repos (each reusing its persisted
    cursor); when unset/empty, the full-org diff (existing behavior). ``repo``
    is the legacy single-repo field (equivalent to ``repos=[repo]``). org is
    still read from the stored credentials, never the client.
    """
    # C5 #2114 (re-review P1): reindex WRITES into the DEFAULT graph — write
    # scope + graph-bound rejection (see index_github).
    _require_scope(org, "graphs:write", "github reindex")
    _reject_graph_bound_org_surface(org, "github reindex")
    _org_id = org["org_id"]
    encrypted, gh_org = _github_credentials(_org_id)
    if not encrypted:
        raise HTTPException(status_code=400, detail="GitHub not connected. Run connect first.")
    gh_org = await _heal_github_org(_org_id, encrypted, gh_org)
    if not gh_org:
        raise HTTPException(status_code=400, detail="GitHub org unknown. Re-connect.")
    # #1845 (review P1): repo(s) are the ONE client-supplied value that
    # reaches the GitHub URL path. org is read server-side from the stored
    # credentials, but a malicious repo (e.g. "../victimorg/x" or "a/b?q=")
    # would be interpolated into f"{org}/{repo}" and could traverse the org
    # boundary via dot-segment normalization at the GitHub edge. Allowlist
    # SHORT repo names (see _validate_repo_scope — the LIST form is strict,
    # a blank entry inside a non-empty list 400s per review P3-1). The
    # legacy single ``repo`` field keeps its documented whitespace-collapse
    # to None (full-org) for backward compat.
    if body and body.repos:
        repos = _validate_repo_scope(body.repos)
    elif body and body.repo is not None:
        legacy = body.repo.strip() or None
        repos = _validate_repo_scope([legacy]) if legacy else None
    else:
        repos = None
    job_id, is_new = _start_index_job(_org_id)
    if is_new:
        import asyncio as _asyncio
        _asyncio.get_event_loop().create_task(
            _run_indexing(job_id, _org_id, gh_org, repos))
    return {"job_id": job_id, "status": "started"}


@app.get("/v1/index/github/{job_id}")
async def index_job_status(job_id: str, org: dict = Depends(get_current_org_session_ungated)):  # noqa: B008
    """Poll an indexing job's progress."""
    job = _INDEX_JOBS.get(job_id)
    if not job:
        raise HTTPException(status_code=404, detail="Job not found")
    # Cross-tenant isolation (P2 review fix): only the owning org can poll
    if job.get("org_id") != org["org_id"]:
        raise HTTPException(status_code=404, detail="Job not found")
    return {"job_id": job_id, **job}


# ── GitHub docs indexing endpoints (#1726 Slice 1) ───────────────
# POST /v1/index/docs mirrors /v1/index/github: org-scoped _INDEX_JOBS
# single-flight (kind-scoped — an in-flight github walk never blends a docs
# job), honest job poll, and the DOCUMENTS gate (the points gate is vacuous
# for Documents — ingest_corpus/index_directory creates Document/Source
# nodes, not Points). Fail-closed when TORTOISE_INGEST_BASE_DIR is unset
# (the endpoint is tenant-reachable; the ingest_dir_is_safe
# "any absolute path when unset" leniency is for the operator stdio path
# only — the tenant path demands the server-owned sandbox).


class DocsIndexRequest(BaseModel):
    # Review (deep bug scan): org is ACCEPTED for backward compat but is
    # never used — index_docs resolves org server-side from the stored
    # credentials (never client-trusted). Optional so a client following
    # the new contract ({repos: [...]} without org) does not 422.
    org: str | None = None
    # #1845: multi-repo scope — list of {"repo": short, "branch": str|None}.
    # branch None/"" = default (main, master fallback); "all" = every branch;
    # a name = that branch. Empty/absent = ALL repos (org-wide).
    repos: list[dict] | None = None
    repo: str | None = None
    branch: str | None = None  # default "main" (fetcher falls back to master)


async def _run_docs_indexing(job_id: str, org_id: str, org: str,
                             scopes: list[dict] | None) -> None:
    """Background docs-indexing job: GitHub docs/ → staged corpus →
    deterministic ingest (Sources only — NO claim extraction, deferred
    #1724).

    Mirrors ``_run_indexing``: quota-preflighted (DOCUMENTS gate), per-repo
    re-check, owner-token-gated status writes, ``github_docs_indexed`` state
    key on progress, one-hour eviction. The sandbox check is FIRST — no
    writes (no staging, no graph writes) when TORTOISE_INGEST_BASE_DIR is
    unset.

    #1845: ``scopes`` is a list of ``{"repo": short, "branch": str|None}``
    dicts. ``branch`` None/"" = the default walk (main, master fallback,
    legacy corpus layout); "all" = walk EVERY branch of the repo
    (branch-qualified corpus — branch-unique doc ids); any other name = that
    specific branch (branch-qualified). None/empty scopes = ALL repos with
    the default branch (the pre-#1845 org-wide behavior).
    """
    from tortoise.indexer.github_docs import GitHubDocsIndexer
    from tortoise.indexer.github_indexer import GitHubFetchError
    # P2: generation/owner token stamped at mint (see _run_indexing).
    owner = _INDEX_JOB_OWNERS.get(job_id)

    def _job(**fields) -> None:
        """Update the job entry ONLY while this run still owns it."""
        if _INDEX_JOB_OWNERS.get(job_id) != owner:
            return  # entry evicted/replaced — abort silently
        job = _INDEX_JOBS.get(job_id)
        if job is not None:
            job.update(fields)

    # Stamp the docs stats on the entry up front — a job that fails early
    # (unset base, quota preflight, unconnected) still reports honest
    # zeroed counts (mirrors the github entry's points_created=0).
    _job(documents_indexed=0, documents_updated=0, documents_skipped=0,
         documents_failed=0, blobs_fetched=0, blobs_skipped_binary=0,
         blobs_skipped_oversized=0, repos_processed=0, repos_total=0)

    try:
        encrypted = _github_token_enc(org_id)
    except Exception:
        _job(status="failed", error="Control plane unavailable")
        return
    if not encrypted:
        _job(status="failed", error="GitHub not connected")
        return
    from tortoise.crypto import decrypt_token
    try:
        token = decrypt_token(encrypted)
    except ValueError:
        _job(status="failed", error="Token undecryptable")
        return

    # ── Fail-closed sandbox check FIRST — no writes when unset (the tenant
    # path never falls through to the ingest_dir_is_safe unset-leniency). ──
    if not os.environ.get("TORTOISE_INGEST_BASE_DIR", "").strip():
        _job(status="failed", error=(
            "TORTOISE_INGEST_BASE_DIR is not set — docs indexing requires "
            "a server-owned ingest sandbox; no writes performed"))
        return

    totals = {"documents_indexed": 0, "documents_updated": 0,
              "documents_skipped": 0, "documents_failed": 0,
              "blobs_fetched": 0, "blobs_skipped_binary": 0,
              "blobs_skipped_oversized": 0, "repos_processed": 0,
              "repos_total": 0, "errors": [], "quota_hit": False}
    try:
        org_sdk = _make_sdk(namespace=org_id)

        # ── Documents gate (Task 9): the docs job gates on the DOCUMENTS
        # resource — the points gate is vacuous for docs (index_directory
        # creates Document/Source nodes, never Points). Resolved BEFORE any
        # fetch/staging; an at-cap org fails honestly (402-equivalent
        # "failed" status), never silently overshooting max_documents. ──
        from tortoise.quota import (  # noqa: I001
            QuotaCheckError, QuotaExceededError, enforce_org_limit,
            resolve_org_limits,
        )
        limits = resolve_org_limits(org_id)
        try:
            enforce_org_limit(limits, "documents", sdk=org_sdk)
        except QuotaExceededError as e:
            _job(status="failed", error=str(e))
            return
        except QuotaCheckError as e:
            _job(status="failed", error=f"Quota check failed: {e}")
            return

        indexer = GitHubDocsIndexer(token)
        # #1845: resolve the walk list from the scopes. None/empty = ALL
        # repos, default branch (org-wide). Explicit scopes = exactly those
        # repos; each carries its own branch (None/"" = default walk;
        # "all" = every branch; a name = that branch).
        if scopes:
            walk_items: list[tuple[str, str | None]] = [
                (f"{org}/{s.get('repo')}", s.get("branch")) for s in scopes]
        else:
            # Review (deep bug scan): same as _run_indexing — the docs
            # org-wide walk must fail honestly on a 404 org, never silently
            # walk the token user's personal repos.
            resolved = await indexer.resolve_repos(
                org, allow_user_fallback=False)
            walk_items = [(r, None) for r in resolved]
        totals["repos_total"] = len(walk_items)

        # org_root = the ingest corpus root — rel-paths embed
        # {owner}/{repo}/docs/... so doc ids stay REPO-UNIQUE (two repos with
        # identical docs paths never share a Document node — the
        # derive_document_id path-collision edge). #1845: branch-qualified
        # walks add {owner}/{repo}/{branch}/docs/... — BRANCH-unique too.
        org_root = GitHubDocsIndexer.org_root(org_id)

        # Review (deep bug scan): one-time legacy cleanup. Pre-#1845 walks
        # staged an UNQUALIFIED corpus at {org}/{owner}/{repo}/docs/...
        # with a .manifest/{owner}/{name}.json — the new branch-qualified
        # layout would ingest that legacy corpus UNDER the new tree, giving
        # the same content TWO doc ids (doc_{owner}/{repo}/docs/x.md vs
        # doc_{owner}/{repo}/{branch}/docs/x.md) and the legacy manifest
        # would never reconcile it away. Remove the legacy unqualified docs
        # dir + legacy manifest once (best-effort — the layout never
        # existed for any prod org, verified github_docs_indexed=false for
        # every connected org; this is a defensive guard for API clients
        # that used the old open endpoint).
        _cleanup_legacy_docs_corpus(org_id, walk_items)

        def _docs_quota_check() -> None:
            enforce_org_limit(limits, "documents", sdk=org_sdk)

        for repo_name, scope_branch in walk_items:
            if _INDEX_JOB_OWNERS.get(job_id) != owner:
                break  # lost ownership (entry evicted/replaced) — abort
            try:
                # #1845: "all" → walk every branch, each into its own
                # branch-qualified corpus (branch-unique doc ids); a named
                # branch → that branch; None/"" → the default walk (main,
                # master fallback). walk_repo branch-qualifies by the
                # RESOLVED branch internally (review P2-2 — always
                # qualified, no legacy layout, so re-indexes never
                # duplicate).
                if scope_branch == "all":
                    branches = await indexer.list_branches(repo_name)
                    if not branches:
                        totals["errors"].append(
                            f"{repo_name}: no branches to index")
                        continue
                    for b in branches:
                        walk = await indexer.walk_repo(
                            org_id, repo_name, branch=b)
                        totals["blobs_fetched"] += walk["blobs_fetched"]
                        totals["blobs_skipped_binary"] += walk["skipped_binary"]
                        totals["blobs_skipped_oversized"] += walk["skipped_oversized"]
                    totals["repos_processed"] += 1
                    # #1894: live per-repo progress ("indexed so far" — the
                    # document count trails by one repo because the current
                    # repo's ingest runs after this write).
                    _job(progress=round(totals["repos_processed"] * 100
                                        / max(totals["repos_total"], 1)),
                         documents_indexed=totals["documents_indexed"],
                         repos_processed=totals["repos_processed"],
                         repos_total=totals["repos_total"])
                else:
                    walk = await indexer.walk_repo(
                        org_id, repo_name, branch=scope_branch or "main")
                    totals["blobs_fetched"] += walk["blobs_fetched"]
                    totals["blobs_skipped_binary"] += walk["skipped_binary"]
                    totals["blobs_skipped_oversized"] += walk["skipped_oversized"]
                    totals["repos_processed"] += 1
                    # #1894: live per-repo progress (see above).
                    _job(progress=round(totals["repos_processed"] * 100
                                        / max(totals["repos_total"], 1)),
                         documents_indexed=totals["documents_indexed"],
                         repos_processed=totals["repos_processed"],
                         repos_total=totals["repos_total"])
            except GitHubFetchError as e:
                # Fix 4: a bad repo must not starve the others — record and
                # continue; already-staged repos are ingested below.
                totals["errors"].append(f"{repo_name}: {e}")
                continue

            # Fix 3: re-check the DOCUMENTS gate immediately BEFORE each ingest
            # (sees the running count after prior repos' ingests — bounds the
            # overshoot to ONE repo's docs, not the whole org).
            try:
                _docs_quota_check()
            except QuotaExceededError as e:
                totals["quota_hit"] = True
                totals["errors"].append(str(e))
                break
            try:
                ingest = org_sdk.index_directory(
                    str(org_root), file_type="doc", extract_metadata=False,
                    corpus_name=f"{org}-docs")
            except Exception as e:
                totals["errors"].append(f"corpus ingest: {e}")
            else:
                totals["documents_indexed"] += ingest.get("indexed", 0)
                totals["documents_updated"] += ingest.get("updated", 0)
                totals["documents_skipped"] += ingest.get("skipped", 0)
                totals["documents_failed"] += ingest.get("failed", 0)

        _job(status="completed", progress=100,
             documents_indexed=totals["documents_indexed"],
             documents_updated=totals["documents_updated"],
             documents_skipped=totals["documents_skipped"],
             documents_failed=totals["documents_failed"],
             blobs_fetched=totals["blobs_fetched"],
             blobs_skipped_binary=totals["blobs_skipped_binary"],
             blobs_skipped_oversized=totals["blobs_skipped_oversized"],
             repos_processed=totals["repos_processed"],
             repos_total=totals["repos_total"],
             quota_hit=totals["quota_hit"],
             errors=totals["errors"],
             error=None)
    except GitHubFetchError as e:
        # Mid-walk 401/429 / unresolved org / unset base: honest "failed"
        # status with a readable error; the manifest was NOT advanced past
        # the failed run — a re-run resumes without gaps (idempotent
        # staging + file-hash dedup make overlap harmless).
        _job(status="failed", error=str(e))
    except Exception as e:
        _job(status="failed", error=str(e))
    finally:
        # github_docs_indexed flips True ONLY on real progress (>=1 repo
        # processed): a 0-repo failure (quota preflight, unset base) leaves
        # it untouched.
        updates: dict = {}
        if totals["repos_processed"] > 0:
            updates["github_docs_indexed"] = True
            # #1894: stamp the last-indexed timestamp in the SAME branch that
            # flips the bool (parity semantics — see _run_indexing; a
            # quota-partial docs run with >=1 repo processed counts as "made
            # progress").
            updates["github_docs_indexed_at"] = datetime.now(UTC).isoformat()
        _update_onboarding_state(org_id, **updates)
        # Evict after an hour (T1-P14: eviction-expired polls render
        # honestly).
        import asyncio as _asyncio
        _asyncio.get_running_loop().call_later(
            _INDEX_JOB_EVICT_S,
            lambda: (_INDEX_JOBS.pop(job_id, None),
                     _INDEX_JOB_OWNERS.pop(job_id, None)))


@app.post("/v1/index/docs")
async def index_docs(body: DocsIndexRequest | None = None,
                     org: dict = Depends(get_current_org_session_ungated)):  # noqa: B008
    """Start a background GitHub-docs indexing job (#1726 Slice 1).

    Mirrors /v1/index/github: per-org single-flight (kind-scoped), returns
    job_id for polling via GET /v1/index/docs/{job_id}. The job is
    documents-gated (derived-constant cap) and fail-closed when the ingest
    sandbox is unset.

    C5 #2114 (re-review P1): the docs job WRITES into the DEFAULT graph —
    write scope + graph-bound rejection (see index_github).
    #1845: ``repos`` is the multi-repo scope (list of {repo, branch}); the
    legacy single ``repo``/``branch`` fields are equivalent to a one-item
    scope. Empty/absent = ALL repos (org-wide, default branch). Review
    P2-3: ``org`` is read SERVER-SIDE from the stored credentials (healed
    via _heal_github_org) — never trusted from the client, mirroring
    github_reindex. The dashboard's body.org is accepted but ignored for
    scope resolution (it is the dashboard's read-back of the same stored
    org, so this is non-breaking); a mismatched/absent body.org falls back
    to the stored org.
    """
    # C5 #2114 (re-review P1): the docs job WRITES into the DEFAULT graph —
    # write scope + graph-bound rejection.
    _require_scope(org, "graphs:write", "docs index")
    _reject_graph_bound_org_surface(org, "docs index")
    # Verify GitHub connected first (seam-aware read) + resolve the REAL
    # org server-side (review P2-3: the client must not pick the org — a
    # malicious org would index any accessible repo into this org's
    # quota/corpus).
    encrypted, stored_org = _github_credentials(org["org_id"])
    if not encrypted:
        raise HTTPException(status_code=400, detail="GitHub not connected. Run connect first.")
    _org_id = org["org_id"]
    gh_org = await _heal_github_org(_org_id, encrypted, stored_org)
    if not gh_org:
        raise HTTPException(status_code=400, detail="GitHub org unknown. Re-connect.")
    # #1845 (review P1 parity): every repo short name is the ONE
    # client-supplied value that reaches the GitHub URL path — allowlist
    # SHORT names (same conservative token as github_reindex). branch
    # values are validated against git-ref safety (P1-1: an unvalidated
    # branch like "../../victimorg/git/trees/main" would traverse the org
    # boundary via httpx dot-segment normalization; git refs can never
    # contain "..", so the rejection is lossless).
    scopes: list[dict] | None = None
    if body and body.repos:
        scopes = []
        for s in body.repos:
            if not isinstance(s, dict) or not s.get("repo"):
                raise HTTPException(status_code=400, detail="Invalid repo scope")
            if not isinstance(s["repo"], str):
                raise HTTPException(status_code=400, detail="Invalid repo name")
            repo = s["repo"].strip()
            if not re.match(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$", repo):
                raise HTTPException(status_code=400, detail="Invalid repo name")
            branch = s.get("branch")
            # '' (the client's default contract) and None mean the default
            # walk; anything else must be a git-ref-safe branch name.
            if branch == "" or branch is None:
                branch = None
            elif not _is_safe_branch(branch):
                raise HTTPException(status_code=400, detail="Invalid branch")
            scopes.append({"repo": repo, "branch": branch})
    elif body and body.repo:
        repo = body.repo.strip()
        if not re.match(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$", repo):
            raise HTTPException(status_code=400, detail="Invalid repo name")
        branch = body.branch
        if branch == "" or branch is None:
            branch = None
        elif not _is_safe_branch(branch):
            raise HTTPException(status_code=400, detail="Invalid branch")
        scopes = [{"repo": repo, "branch": branch}]
    job_id, is_new = _start_index_job(_org_id, kind="docs")
    if is_new:
        import asyncio as _asyncio
        _asyncio.get_event_loop().create_task(
            _run_docs_indexing(job_id, _org_id, gh_org, scopes))
    return {"job_id": job_id, "status": "started"}


@app.get("/v1/index/docs/{job_id}")
async def docs_job_status(job_id: str,
                          org: dict = Depends(get_current_org_session_ungated)):  # noqa: B008
    """Poll a docs-indexing job's progress (org-scoped isolation)."""
    job = _INDEX_JOBS.get(job_id)
    if not job:
        raise HTTPException(status_code=404, detail="Job not found")
    # Cross-tenant isolation: only the owning org can poll
    if job.get("org_id") != org["org_id"]:
        raise HTTPException(status_code=404, detail="Job not found")
    return {"job_id": job_id, **job}


# ── Backups: endpoints (#305) ────────────────────────────────────


# Test seam (#303 E2E): TORTOISE_BACKUP_STORAGE=memory swaps the R2 object
# store for an in-process MemoryStorage so the backup→restore journey can run
# hermetic (no R2 creds). Precedent: RATE_LIMIT_DISABLED. Any other value
# fails closed (loud) so a typo can never silently downgrade durability.
# Durability guard (#101 incident class): on Fly (FLY_APP_NAME set) the seam
# REFUSES — memory backups vanish on restart, the exact silent-data-loss mode
# the #101 postmortem documents (mirrors the sdk.py embedded-on-Fly guard).
if os.environ.get("TORTOISE_BACKUP_STORAGE", "").strip().lower() == "memory":
    if os.environ.get("FLY_APP_NAME"):
        raise RuntimeError(
            "TORTOISE_BACKUP_STORAGE=memory is a test seam and refuses to run "
            "on Fly (FLY_APP_NAME set) — memory backups are lost on restart"
        )
    _logger.warning(
        "TORTOISE_BACKUP_STORAGE=memory active at startup — backups live in "
        "process memory only and are LOST on restart (test seam, #303)"
    )
_MEMORY_BACKUP_STORE: MemoryStorage | None = None
# #3968: the DEFAULT (R2) path needs the same process-wide reuse the memory seam
# already has. Without it every `_backup_storage()` call built a fresh
# `R2Storage`, and `R2Storage._s3()` builds a fresh boto3 client per instance —
# so the #3820 process-start-UNKNOWN resolve (which retries one read per
# delivered write until the store answers) paid a client construction per
# write. Keyed on the RESOLVED R2 config (`_r2_config_from_env`), never a bare
# "have we built one yet" flag: a changed `R2_*` env (a credential rotation, or
# a test's monkeypatch) rebuilds the store instead of pinning a stale
# credential into a long-lived client. No health/refresh path is needed because
# the env IS the credential source in this process model — the key covers it.
_R2_BACKUP_STORE: R2Storage | None = None
_R2_BACKUP_STORE_CONFIG: tuple[str, str, str, str] | None = None


def _backup_storage() -> R2Storage | MemoryStorage:
    """Backup object store. R2 from env (R2_ACCOUNT_ID / ...) by default.

    TORTOISE_BACKUP_STORAGE=memory → process-wide MemoryStorage singleton
    (E2E seam, #303). Unknown value → RuntimeError (fail-closed).

    The R2 path is ALSO process-wide, keyed on the resolved R2 config (#3968):
    N calls build one ``R2Storage`` (and therefore one lazily-built boto3
    client), not N. An incomplete config still raises here, fail-closed — the
    key is compared BEFORE any return, so a removed ``R2_*`` cannot be served
    out of a previously-populated cache."""
    global _MEMORY_BACKUP_STORE, _R2_BACKUP_STORE, _R2_BACKUP_STORE_CONFIG
    mode = os.environ.get("TORTOISE_BACKUP_STORAGE", "").strip().lower()
    if mode == "memory":
        if _MEMORY_BACKUP_STORE is None:
            _logger.warning(
                "TORTOISE_BACKUP_STORAGE=memory — backups live in process "
                "memory only and are LOST on restart (test seam, #303)"
            )
            _MEMORY_BACKUP_STORE = MemoryStorage()
        return _MEMORY_BACKUP_STORE
    if mode:
        raise RuntimeError(
            f"TORTOISE_BACKUP_STORAGE={mode!r} unknown — use 'memory' or unset for R2"
        )
    config = _r2_config_from_env()
    if _R2_BACKUP_STORE is None or config != _R2_BACKUP_STORE_CONFIG:
        # `R2Storage()` re-resolves the SAME env into the SAME tuple, so the
        # cached store always describes `config`. Assign only AFTER a
        # successful construction: a raise (missing R2_*) leaves the cache
        # untouched rather than half-updated.
        _R2_BACKUP_STORE = R2Storage()
        _R2_BACKUP_STORE_CONFIG = config
    return _R2_BACKUP_STORE


def _backup_mirror_storage(cfg) -> R2Storage | None:
    """#2319 geo-mirror store from config (BACKUP_MIRROR_ENABLED +
    R2_MIRROR_*). None when mirroring is disabled — the sweep then runs
    byte-for-byte mirror-free. Construction cannot fail here when the config
    is valid: backup_config validates the four R2_MIRROR_* creds
    required-when-enabled (and derives the endpoint from the account id)."""
    if cfg is None or not cfg.mirror_enabled:
        return None
    return R2Storage(
        endpoint_url=cfg.mirror_endpoint,
        access_key_id=cfg.mirror_access_key_id,
        secret_access_key=cfg.mirror_secret_access_key,
        bucket=cfg.mirror_bucket,
    )


def _lock_status_block(cfg) -> dict | None:
    """#2319 live bucket-lock drift block for /status. None when lock is not
    enabled (no /status surface change until an operator flips the lock on).
    On-demand single GET with a short timeout; failures report unverifiable
    (never block /status, never block the pipeline — the runbook is the
    fallback verification path)."""
    if cfg is None or not cfg.lock_enabled:
        return None
    from tortoise.hosted_backup import (
        LockVerificationError,
        fetch_r2_bucket_lock_rules,
        verify_bucket_lock,
    )

    out: dict = {
        "enabled": True,
        "prefix": "backups/",
        "expected_days": cfg.lock_days,
    }
    if not cfg.cf_api_token:
        out.update({
            "status": "unverifiable",
            "detail": "CF_API_TOKEN not set — verify via the ops runbook "
                       "(docs/ops/registry-backup-dr.md §#2319, console/wrangler)",
        })
        return out
    try:
        rules = fetch_r2_bucket_lock_rules(
            cfg.r2_account_id, cfg.cf_api_token, cfg.r2_bucket)
        out.update(verify_bucket_lock(rules, expected_days=cfg.lock_days))
    except LockVerificationError as e:
        out.update({"status": "unverifiable", "detail": str(e)})
    return out


def _require_backup_tier(org: dict) -> None:
    """Backups gated on pricing.json hourly_backups feature flag (#656).

    #2317: named for the ACTUAL delivered cadence — the sweep driver runs
    hourly (RPO ≤1h typical / ≤2h worst), not daily. The allowlist is derived
    from product/pricing.json (NOT hardcoded) so the gate can never drift
    from the canonical pricing source.
    """
    from tortoise.pricing import hourly_backups_enabled

    tier = org.get("tier")
    if not hourly_backups_enabled(tier):
        raise HTTPException(
            status_code=402,
            detail="Backups are a Builder feature — upgrade to enable hourly backups",
        )


def _legacy_overrides_from_index(listed: list[dict],
                                 index: dict) -> dict[str, str]:
    """#2370: pure Q6-override derivation from the sweep-written legacy-flat
    classification index (backup_id → {graph_name, graph_id}). Legacy flat
    manifests whose index entry resolves to a CUSTOM graph (graph_id set and
    ≠ default) list under that graph; everything else keeps the default
    bucket. Returns {backup_id: graph_id}."""
    if not index:
        return {}
    out: dict[str, str] = {}
    for m in listed:
        if m.get("graph_id") is not None:
            continue
        bid = str(m.get("backup_id") or "")
        if len(bid.split("/")) != 2:
            continue
        meta = index.get(bid)
        gid = str((meta or {}).get("graph_id") or "")
        if gid and gid != "default":
            out[bid] = gid
    return out


def _manifest_graph(manifest: dict, override_gid: str | None = None) -> dict:
    """#2313: derive the graph identity of a backup manifest for listing.

    Per-graph manifests carry ``graph_id``; legacy flat manifests (pre-#2313
    org-level artifacts) bucket to the DEFAULT graph by key shape (Q6 owner
    decision) unless an override resolves them — see ``backups_list``'s
    reverse lookup (a legacy flat manifest whose ``graph_name`` names a
    custom namespace is a pre-#2313 C5-era on-demand custom dump and lists
    under that custom graph). Additive enrichment only — consumers ignore
    unknown fields.
    """
    graph = override_gid or manifest.get("graph_id")
    if graph is None:
        parts = str(manifest.get("backup_id", "")).split("/")
        graph = parts[1] if len(parts) == 3 else "default"
    out = dict(manifest)
    out["graph_id"] = graph
    out["kind"] = "default" if graph == "default" else "custom"
    return out


def _legacy_graph_overrides(cp_source, org_id: str,
                            manifests: list[dict]) -> dict[str, str]:
    """Q6 reverse lookup: legacy FLAT manifests (2-segment backup_id) carry
    the graph they dumped in ``graph_name`` — resolve that to an ACTIVE graph
    id via the graphs seam so pre-#2313 C5-era on-demand dumps of CUSTOM
    graphs list under their graph instead of mislabeling as the default.
    Returns {backup_id: graph_id}. Fail-soft: any seam error → empty map
    (the default bucket in ``_manifest_graph`` is the fallback).
    """
    legacy = [m for m in manifests
              if m.get("graph_id") is None
              and len(str(m.get("backup_id", "")).split("/")) == 2]
    if not legacy:
        return {}
    try:
        from tortoise.backup_sweep import _sweep_graph_list
        rows = _sweep_graph_list(cp_source, org_id)
    except Exception as e:
        _logger.warning("legacy graph reverse lookup failed for %s: %s",
                        org_id, e)
        return {}
    return _legacy_bucket_map(rows, legacy)


def _legacy_bucket_map(rows: list[dict], legacy: list[dict]) -> dict[str, str]:
    """Pure Q6 mapping: active-graph rows (namespace → graph_id) → legacy flat
    manifests whose ``graph_name`` names one of them. Pure for unit testing."""
    ns_to_gid = {str(r.get("namespace") or ""): r["graph_id"]
                 for r in rows if not r.get("_invalid")}
    return {m["backup_id"]: ns_to_gid[str(m.get("graph_name") or "")]
            for m in legacy
            if str(m.get("graph_name") or "") in ns_to_gid}


# #3030: the sweep-emitted guard kinds a conclusive clear run resolves, and the
# subject rule that keys them, are both owned by ``tortoise.backup_sweep``
# (``sweep_resolutions`` / ``graph_subject`` / ``incident_subject``) — nothing
# sweep-domain is duplicated here.


def _incident_subject(inc: dict) -> str:
    """#2313: alert-store subject for a sweep incident — thin alias for
    ``backup_sweep.incident_subject``."""
    from tortoise.backup_sweep import incident_subject

    return incident_subject(inc)


# #4144: the public backups family is ALSO served under `/v1/`. The dashboard
# reaches the API only through the same-origin BFF proxy
# (`website/apps/dashboard/functions/api/v1/[[path]].ts`), which rebuilds the
# upstream URL as `${API_ORIGIN}/v1/${rest}` — it cannot produce a bare path.
# Served only at `/backups`, the dashboard's `loadBackups` got a 404 from Pages
# (no `api/backups.ts` exists either) and the Backups card silently read as
# empty. The alias is the SAME function object, so it cannot drift into a
# second implementation.
@app.get("/backups")
@app.get("/v1/backups")
async def backups_list(org: dict = Depends(get_current_org_session_ungated)):  # noqa: B008
    """List this org's backups (newest first) with timestamps + node counts.

    #1831 P2-4: rides the session dual-auth (#1828) — the dashboard's
    loadBackups call carries NO key when a recoverable mint failure left
    apiKey empty (the overview reads ride the session JWT), so a bare
    get_current_org dependency 401'd and the Backups card silently
    disappeared for Builder-plan (`pro`) users. Ungated dual-auth accepts session JWT OR
    tt_ key; only org["org_id"] is read below, so a session-resolved
    dict behaves identically."""
    org_id = org.get("org_id")
    if not org_id:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    try:
        listed = await asyncio.to_thread(
            list_backups, _backup_storage(), org_id)
        # #2313: additive per-graph identity on every entry. Legacy flat
        # artifacts read-bucket to the default graph by key shape, with a
        # Q6 reverse lookup first: a flat manifest whose graph_name names a
        # custom namespace (pre-#2313 C5-era on-demand custom dumps) lists
        # under that custom graph. Fail-soft — the default bucket stands on
        # any control-plane error.
        # #2370: the reverse lookup now reads the sweep-written legacy-flat
        # classification index (one R2 object) instead of running a
        # control-plane query per request. The CP path remains only as the
        # pre-first-sweep / index-miss fallback.
        overrides: dict[str, str] = {}
        if any(m.get("graph_id") is None for m in listed):
            storage_obj = _backup_storage()
            from tortoise.backup_sweep import read_legacy_flat_index
            idx = await asyncio.to_thread(
                read_legacy_flat_index, storage_obj, org_id)
            if idx:
                overrides = _legacy_overrides_from_index(listed, idx)
            # legacy flats the index could not classify (or no index yet) →
            # pre-#2313 CP reverse lookup (fail-soft on any error).
            unresolved = [m for m in listed
                          if m.get("graph_id") is None
                          and len(str(m.get("backup_id", "")).split("/")) == 2
                          and m.get("backup_id") not in (idx or {})]
            if unresolved:
                try:
                    # #2823: one shared dialect-aware seam — never a hand-rolled
                    # `is_supabase_enabled()` branch (that per-caller drift is
                    # what left the sweep enumerating the empty registry).
                    cp = _control_plane_source()
                except Exception as e:
                    _logger.warning("backups list cp unavailable: %s", e)
                    cp = None
                if cp is not None:
                    overrides.update(await asyncio.to_thread(
                        _legacy_graph_overrides, cp, org_id, listed))
        return {"backups": [
            _manifest_graph(m, override_gid=overrides.get(m.get("backup_id")))
            for m in listed
        ]}
    except ValueError as e:
        raise HTTPException(status_code=400, detail=f"List rejected: {e}")  # noqa: B904
    except RuntimeError as e:
        raise HTTPException(status_code=503, detail=f"Backup storage unavailable: {e}")  # noqa: B904


def _registry_sdk() -> TortoiseSDK:
    """Registry-namespaced SDK — Org/Membership nodes live in the canonical
    registry_control_plane graph, reached only via namespace='registry' (the
    same resolution every other registry op in this file uses).

    #1579: the embedded-store CONNECT (FalkorProjection construction inside
    the first ``_get_proj()``) can transiently fail under parallel-suite
    temp-DB contention (redis ConnectionError / OSError-family — the same
    class the #1565 probe_db retry clears). Eager-connect here with ONE
    retry so drill/sweep/restore handlers never 500 on a momentary connect
    blip; a persistent failure still raises (a genuinely broken DB must keep
    failing). Reuses monitoring._is_transient_connect_error — a builtin or
    redis TimeoutError is NEVER retried (a hung DB stays hung).
    """
    from tortoise.monitoring import (
        PROBE_RETRY_DELAY,
        _is_transient_connect_error,
    )

    sdk = _make_sdk(namespace="registry")
    try:
        sdk._get_proj()  # eager: surface the connect failure here, retried below
    except Exception as exc:
        if not _is_transient_connect_error(exc):
            raise
        time.sleep(PROBE_RETRY_DELAY)
        sdk._get_proj()  # ONE retry — same SDK; _proj stays None until success
    return sdk


def _control_plane_source():
    """Dialect-aware control-plane source for the backup/DR seam (#669/#2823).

    Supabase lane: the ``SupabaseControlPlane`` (PostgREST adapter). Registry
    lane (selfhost): the FalkorDB ``registry_control_plane`` graph handle.

    #2823: this is the sanctioned way for the backup/DR OPERATORS to obtain
    the control plane — every operator that hand-rolled the dialect branch
    (sweep, purge, re-baseline, drill, scheduled drill, acl-reconcile,
    `backups_list`, the watcher lifespan) now resolves it here, so the next
    operator cannot re-introduce the defect per-endpoint (#2340).

    Two older sites still resolve the same pair inline
    (``backups_create``'s stamp seam, ``backups/restore``'s target resolver):
    they HOLD the registry SDK as a request-scoped keepalive and close it in
    their ``finally`` (#1475/#1607), so folding them needs that lifetime
    preserved — tracked separately rather than risked here.

    A Supabase-mode caller also never opens the registry namespace: the
    pre-#2823 handlers passed ``_registry_sdk()._get_proj().db`` as the
    data-plane handle. That projection is the registry namespace's own shell
    (``registry_tortoise``), which it re-materializes; and ``_get_registry()``
    — the pre-#2823 org source — runs ``CREATE INDEX`` against
    ``registry_control_plane``, the graph the #669 flip DELETED. Both are
    auto-recreate artifacts (#669 post-flip verification). The data-plane
    handle (``_make_sdk(namespace=None)._get_proj().db`` — backup_sweep's
    ``db``, the GRAPH.DELETE / ``select_graph`` target) is the one #669
    mandates and the one that exists in BOTH lanes.
    """
    from tortoise.supabase_control import get_control_plane, is_supabase_enabled

    if is_supabase_enabled():
        return get_control_plane()
    return _registry_sdk()._get_registry()


# Per-org restore serialization: the swap (delete live → copy temp) must not
# interleave with a concurrent same-org restore — a second restore landing in
# the delete→copy window would recreate the live key and fail the copy, or
# defeat the empty-backup guard's TOCTOU.
_BACKUP_RESTORE_LOCKS: dict[str, asyncio.Lock] = {}
_BACKUP_LOCKS_GUARD = asyncio.Lock()


async def _org_restore_lock(org_id: str) -> asyncio.Lock:
    async with _BACKUP_LOCKS_GUARD:
        return _BACKUP_RESTORE_LOCKS.setdefault(org_id, asyncio.Lock())


@app.post("/backups", status_code=201)
@app.post("/v1/backups", status_code=201)  # #4144 BFF-reachable alias
async def backups_create(org: dict = Depends(get_current_org_gated)):  # noqa: B008
    """Trigger an on-demand backup of the org graph (Builder plan, tier `pro`)."""
    org_id = org.get("org_id")
    if not org_id:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    _require_backup_tier(org)
    # C5 #2114: a backup is a full-graph read (least-privilege parity with
    # read access — the key can already read every node) → graphs:read.
    # Accepted residual (code-review P2): a read-only key can generate
    # repeated dump artifacts (storage amplification) — data-exposure parity
    # is sound (read == full visibility); a per-key backup rate limit or
    # graphs:write requirement is a follow-up if storage cost matters.
    _require_scope(org, "graphs:read", "backups_create")
    sdk = None
    registry_sdk = None
    try:
        sdk = _make_sdk(namespace=org_id)
        # #669 post-flip: the backup stamp seam is dialect-aware — pass the
        # Supabase control plane in Supabase mode (the registry handle would
        # stamp the DELETED registry and auto-recreate the empty graph).
        from tortoise.supabase_control import (
            get_control_plane,
            is_supabase_enabled,
        )
        if is_supabase_enabled():
            registry_sdk = None
            cp_source = get_control_plane()
        else:
            registry_sdk = _registry_sdk()
            cp_source = registry_sdk._get_registry()
        # #924: graph name resolved from the control plane via the SAME seam
        # as the sweep (org_graph_name) — Supabase mode reads teams.graph_name
        # (SDK org creation names graphs org_{name}, NOT org_{id}; #768/#770),
        # registry mode is the deterministic org_{id}. Fail-closed: a
        # resolution error 503s rather than backing up a wrong/nonexistent graph.
        from tortoise.backup_sweep import org_graph_name, resolve_active_graph
        # C5 #2114: a graph-bound key backs up ITS OWN graph (graph_namespace
        # is the resolved FULL name — custom org_{tid}_{gid} or the default);
        # org-wide keys/session back up the org default (today's path).
        # FAIL-CLOSED (final-gate P1): a graph-bound key whose graph is GONE
        # resolves graph_namespace=None — the `or` fallback would widen a
        # ghost key onto the org DEFAULT graph (cross-graph read dump).
        # Mirror _data_sdk: vanish → 403, never a demotion.
        default_name = org_graph_name(cp_source, org_id)
        if org.get("graph_id"):
            graph_name = org.get("graph_namespace")
            if not graph_name:
                raise HTTPException(
                    status_code=403,
                    detail={"error_code": "GRAPH_NOT_FOUND",
                            "message": "graph not found for key"})
            # #2376: the canonical key segment is decided by graph KIND
            # through the ACTIVE-graph seam (resolve_active_graph — the same
            # tombstone guard restore/re-baseline use), NEVER by namespace
            # string-equality. A default-kind binding must key under the
            # literal "default" even if its namespace no longer equals the
            # current default name (graph_name change / stale binding); a
            # custom always keys under its control-plane id. Custom-bound
            # keys are the only mintable shape today (the default rides
            # org-wide keys, _mint_graph_key rejects default bindings), so
            # this is defense-in-depth for a future default-bound binding or
            # non-conforming row id — but the classification must not be
            # hostage to namespace spelling. Unresolved (vanished) graphs
            # fail closed 403, mirroring the ghost-key guard above.
            try:
                g_row = resolve_active_graph(cp_source, org_id,
                                             org.get("graph_id"))
            except ValueError as e:
                raise HTTPException(
                    status_code=403,
                    detail={"error_code": "GRAPH_NOT_FOUND",
                            "message": "graph not found for key"}) from e
            graph_id = ("default" if g_row["kind"] == "default"
                        else org.get("graph_id"))
        else:
            graph_name = default_name
            graph_id = "default"
        # #924 review P1: create_backup dumps proj.g — the SDK bound to
        # namespace=org_id resolves org_{org_id}, NOT the resolved graph.
        # For a org_{name} org the dump would be the EMPTY phantom graph
        # while the manifest claims org_{name}. Bind the dump projection to
        # the RESOLVED graph (the sweep's per-graph _backup_graph does db.select_graph
        # on the same name). from_uri reuses the configured connection with
        # graph_name override (#7886 multi-tenant isolation).
        import os as _os

        from tortoise.projection import FalkorProjection
        db_uri = _os.environ.get("TORTOISE_DB_URI")
        proj = sdk._get_proj()
        if db_uri:
            dump_proj = FalkorProjection.from_uri(db_uri, graph_name=graph_name)
        elif getattr(proj, "_path", None):
            # Embedded: re-open the same DB on the resolved graph name.
            dump_proj = FalkorProjection(
                path=proj._path, graph_name=graph_name,
                skip_health_check=True,
            )
        else:
            # No path (unusual) — bind the existing db handle to the graph.
            from tortoise.projection import _GuardedGraph
            dump_proj = type("_DumpProj", (), {
                "g": _GuardedGraph(proj.db.select_graph(graph_name), proj),
                "graph_name": graph_name,
            })()
        storage = _backup_storage()
        manifest = await asyncio.to_thread(
            create_backup, dump_proj, cp_source, storage,
            org_id=org_id, graph_name=graph_name, graph_id=graph_id,
        )
        # Retention: prune the graph's pool after a successful backup so
        # storage stays bounded (best-effort — a prune failure must not fail
        # the backup). Per-graph prune never touches other graphs' nested
        # keys; the legacy flat pool is drained by the sweep.
        try:
            await asyncio.to_thread(
                prune_backups, storage, org_id, graph_id=graph_id)
        except Exception as e:
            _logger.warning("prune failed for team %s: %s", org_id, e)
    except HTTPException:
        # C5 #2114 (final-gate P1): the fail-closed GRAPH_NOT_FOUND 403 for
        # a vanished graph-bound key must surface as 403, not be swallowed
        # by the generic arm into a 500 (the file's established pattern).
        raise
    except ValueError as e:
        raise HTTPException(status_code=400, detail=f"Backup rejected: {e}")  # noqa: B904
    except RuntimeError as e:
        raise HTTPException(status_code=503, detail=f"Backup failed: {e}")  # noqa: B904
    except Exception as e:
        _logger.exception("backup failed for team %s", org_id)
        raise HTTPException(status_code=500, detail=f"Backup failed: {e}")  # noqa: B904
    finally:
        if sdk is not None:
            sdk.close()
        if registry_sdk is not None:
            registry_sdk.close()
    return manifest


@app.post("/backups/restore")
@app.post("/v1/backups/restore")  # #4144 BFF-reachable alias
async def backups_restore(body: BackupRestoreRequest, request: Request, org: dict = Depends(get_current_org_session)):  # noqa: B008
    """Restore the org graph from a backup (Builder plan, tier `pro`; confirm=true required).

    Restores into a temp graph, verifies node/edge counts against the payload,
    then swaps (pre-restore safety copy → delete live → copy temp). The live
    graph is only touched after the temp graph verifies. ``confirm=true`` is
    a footgun guard, not role authorization — every org key already has full
    write access to the org graph.
    """
    org_id = org.get("org_id")
    if not org_id:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    _require_backup_tier(org)
    # C5 #2114: restore is a DESTRUCTIVE org-default-graph operation (the
    # #1148 management set) — a graph-bound key must never restore over the
    # org default (cross-graph write). Org-wide keys + session auth pass.
    _reject_graph_bound_org_surface(org, "backup restore")
    # C5 #2114 (re-review P2): restore REPLACES the live graph — a
    # deleg-NULL org-wide graphs:read-only key must never trigger it.
    _require_scope(org, "graphs:write", "backup restore")
    if not body.confirm:
        raise HTTPException(
            status_code=400, detail="confirm=true required — restore replaces the live graph"
        )
    lock = await _org_restore_lock(org_id)
    sdk = None
    registry_sdk = None
    from tortoise.supabase_control import (
        get_control_plane,
        is_supabase_enabled,
    )
    async with lock:
        try:
            sdk = _make_sdk(namespace=org_id)
            if not is_supabase_enabled():
                registry_sdk = _registry_sdk()
            cp_source = (get_control_plane() if is_supabase_enabled()
                         else registry_sdk._get_registry())
            # #924/#2313: resolve the restore target from the ACTIVE-graph
            # seam. The artifact's key shape names its graph: legacy flat and
            # the "default" segment are the org DEFAULT surface (the only
            # surface this endpoint restores — custom-graph restore is a
            # graph-bound-key operation, refused below); resolution via
            # resolve_active_graph doubles as the tombstone guard (a
            # deleted/quarantined graph is never a valid restore target,
            # #2304). Default graph name: teams.graph_name in Supabase mode
            # (the old org_{id} hardcode would reject the restore as
            # cross-graph for SDK-created orgs), org_{id} in registry mode.
            from tortoise.backup_sweep import resolve_active_graph
            from tortoise.hosted_backup import _parse_backup_key
            try:
                _parsed_org, _parsed_graph, _ = _parse_backup_key(body.backup_key)
            except ValueError as e:
                raise ValueError(f"unrecognized backup key: {e}") from None
            if _parsed_graph not in (None, "default"):
                raise ValueError(
                    "restoring a custom graph from this endpoint is not "
                    "supported — graph-bound restore required"
                )
            _graph_id = _parsed_graph or "default"
            _row = resolve_active_graph(cp_source, org_id, _graph_id)
            graph_name = _row["graph_name"]
            result = await asyncio.to_thread(
                restore_backup, sdk._get_proj().db, cp_source,
                _backup_storage(),
                body.backup_key, org_id=org_id, graph_name=graph_name,
            )
            # Rebuild indexes on the restored live graph (range/FTS/vector) —
            # the logical dump + GRAPH.COPY restores data, not schema. Off the
            # event loop: a large graph's index build must not stall all tenants.
            # #924 review P2: bind the rebuild to the RESOLVED graph (the SDK
            # projection bound to namespace=org_id would index the phantom
            # org_{id} graph for org_{name} orgs — same class of bug as the
            # dump binding P1).
            try:
                db_uri = os.environ.get("TORTOISE_DB_URI")
                if db_uri:
                    from tortoise.projection import FalkorProjection
                    dump_proj = FalkorProjection.from_uri(db_uri, graph_name=graph_name)
                else:
                    proj = sdk._get_proj()
                    if getattr(proj, "_path", None):
                        from tortoise.projection import FalkorProjection
                        dump_proj = FalkorProjection(
                            path=proj._path, graph_name=graph_name,
                            skip_health_check=True,
                        )
                    else:
                        dump_proj = proj
                await asyncio.to_thread(dump_proj._ensure_indexes)
            except Exception as e:
                _logger.warning(
                    "index rebuild after restore failed for team %s: %s", org_id, e
                )
        except RestoreVerificationError as e:
            raise HTTPException(status_code=409, detail=f"Restore rejected: {e}")  # noqa: B904
        except (ValueError, KeyError) as e:
            raise HTTPException(status_code=400, detail=f"Restore rejected: {e}")  # noqa: B904
        except RuntimeError as e:
            raise HTTPException(status_code=503, detail=f"Restore failed: {e}")  # noqa: B904
        except Exception as e:
            _logger.exception("restore failed for team %s", org_id)
            raise HTTPException(status_code=500, detail=f"Restore failed: {e}")  # noqa: B904
        finally:
            if sdk is not None:
                sdk.close()
            if registry_sdk is not None:
                registry_sdk.close()
    return result


# ── Backup sweep / DR alerting (#596) ──────────────────────────────────
# Per-org knowledge-graph protection: scheduled sweep driver, dual-watcher
# alerting (GitHub issue + Telegram), drill-only restore. Fail-closed: every
# endpoint 503s when the sweep is disabled (config missing or BACKUP_SWEEP_ENABLED
# not true).

_WATCHER: WatcherThread | None = None  # WatcherThread imported in _lifespan  # noqa: F821
# #2877: why the watcher is not running. `_WATCHER is None` ALONE cannot tell a
# dead monitor from a deliberately-disabled one — it is also the fail-closed
# default (no/invalid backup config) and the `BACKUP_WATCHER_DISABLED=1` kill
# switch. Set only from the watcher-start `except` in `_lifespan`; cleared when
# the watcher starts cleanly, so the one signal it carries is "wanted but
# failed". Read by `_backup_watcher_health()` for /health.
_WATCHER_START_ERROR: str | None = None
_DRIVER_HEARTBEAT_KEY = "ops/driver-heartbeat.json"
_LAST_DRILL_AT: float = 0.0  # in-memory drill cooldown (single-instance, resets on restart)
_DRILL_COOLDOWN_S = 3600
# #2317: committed per-org restore RTO — restore-op ≤ 15 min measured from
# drill accept to verified scratch restore (drill_ok), carried from the
# retired registry-era target (docs/ops/registry-backup-dr.md). Every drill
# records duration_s and compares to this; the SCHEDULED drill opens a
# RESTORE_DRILL_FAILED incident when the RTO is breached (restore succeeded
# but too slowly) or the drill fails outright.
_DRILL_RTO_S = 900.0
_DRILL_RECORD_KEY = "ops/drills/last.json"
_DRILL_FAILED_KIND = "RESTORE_DRILL_FAILED"
_SWEEP_ORG_LOCKS: dict[str, threading.Lock] = {}
_SWEEP_LOCKS_GUARD = threading.Lock()
_SWEEP_INFLIGHT = asyncio.Lock()
_PURGE_INFLIGHT = asyncio.Lock()  # #2304 trash-purge in-flight guard


def _backup_config_safe() -> BackupConfig | None:  # noqa: F821
    """Sweep config, or None when disabled (fail-closed).

    Thin delegate to ``alert_channel.sweep_config_safe`` — the ALERT channel's
    light leg needs the same fail-closed rule without importing this module.
    Kept as a module global because tests patch THIS name (``test_notify``,
    ``test_email_notify``).
    """
    from tortoise import alert_channel

    return alert_channel.sweep_config_safe()


def _alert_store_from(cfg, writer: str | None = None) -> AlertStore:  # noqa: F821
    """Build the store. `writer` is the identity its resolves act as.

    Defaults to the app (this factory is the app's), so the declared owner in
    KIND_OWNERS actually declares itself — otherwise the authority check is
    short-circuited for the whole app path and the map is inert. The watcher
    passes WRITER_WATCHER explicitly at its construction site.

    The body lives in ``alert_channel.alert_store_from`` so the light leg
    (``operator_alert``, which must not import this module) builds a
    byte-identical store. ``_backup_storage`` is passed as a FACTORY, resolved
    at call time, so the test patch point on this module keeps working and the
    hosted leg keeps its cache-keyed R2 singleton (#3968). ``writer`` is
    forwarded verbatim — the #3127/#2844 authority contract is main's, and this
    delegate must not narrow it.
    """
    from tortoise import alert_channel

    return alert_channel.alert_store_from(
        cfg, storage_factory=_backup_storage, writer=writer)


def _sweep_org_lock(org_id: str) -> threading.Lock:
    with _SWEEP_LOCKS_GUARD:
        return _SWEEP_ORG_LOCKS.setdefault(org_id, threading.Lock())


def _read_driver_heartbeat() -> dict:
    try:
        parsed = _json.loads(_backup_storage().download(_DRIVER_HEARTBEAT_KEY))
        return parsed if isinstance(parsed, dict) else {}
    except (KeyError, ValueError):
        return {}


def _boot_gc_drill_graphs(db, max_age_hours: float = 6.0) -> None:
    """Sweep drill/restore scratch graphs left by a mid-drill crash. A crash
    mid-drill would otherwise leave a full org snapshot on the production
    instance under a scratch name (Task 7 acceptance; boot-time GC)."""

    try:
        graphs = db.list_graphs()
    except Exception as exc:
        _logger.warning("drill-graph GC: list failed: %s", exc)
        return
    now = datetime.now(UTC)
    # Review P1-1: only the drill endpoint's OWN scratch prefix is eligible —
    # substring patterns could match a legitimately-provisioned org id (e.g.
    # "org_drill_20240101...") and the GC would delete a LIVE graph. Org
    # graphs are never eligible.
    for name in graphs:
        if not name.startswith("_drill_"):
            continue
        if name.startswith("org_"):
            continue
        try:
            g = db.select_graph(name)
            ts_part = name.rsplit("_", 1)[-1]
            created = datetime.strptime(ts_part, "%Y%m%dT%H%M%S%fZ").replace(tzinfo=UTC)
            if (now - created).total_seconds() / 3600.0 > max_age_hours:
                g.delete()
                _logger.info("drill-graph GC removed %s", name)
        except Exception:
            continue


def _reconcile_acl_users_sync() -> dict:
    """Sync body of backups_acl_reconcile — MUST run off the event loop
    (#2371): per ACTIVE graph ``create_acl_user`` issues several blocking
    redis/FalkorDB round-trips (3s/5s timeouts); inline in the async handler
    a slow-but-reachable ACL server would stall the single-worker API event
    loop for every tenant during the exact post-restore window this endpoint
    exists for. Runs in its own worker thread — no lock needed (the old
    ``threading.Lock`` guarded nothing: a single event loop has no
    concurrency)."""
    cfg = _backup_config_safe()
    if cfg is None:
        raise HTTPException(status_code=503, detail="Backup sweep disabled")
    from tortoise.backup_sweep import _sweep_graph_list, enumerate_eligible_orgs

    # #2823/#2340: dialect-aware control plane — the raw registry handle
    # enumerates an EMPTY graph post-#669, so this returned {"teams": 0} (a
    # silent no-op success) instead of rebuilding the post-restore ACLs.
    registry = _control_plane_source()
    try:
        org_ids = enumerate_eligible_orgs(registry)
    except RuntimeError as e:
        raise HTTPException(status_code=503,
                            detail=f"team enumeration failed: {e}") from e

    from typing import Any as _Any

    from tortoise.acl_graph_users import create_acl_user  # type: ignore[import-not-found]

    results: dict[str, _Any] = {}
    for org_id in sorted(org_ids):
        try:
            graphs = _sweep_graph_list(registry, org_id)
        except Exception as e:
            results[org_id] = {"status": "error", "error": str(e)}
            continue
        ok = skipped = defaults = 0
        errors: list[str] = []
        for row in graphs:
            if row.get("_invalid"):
                continue
            if row["kind"] == "default":
                # The default graph's ACL protection rides the ORG-scoped
                # tenant ACL (its namespace is the org namespace —
                # org_{name}/{graph_name}); per-graph ACL users only exist
                # for CUSTOM graphs (namespace org_{tid}_{gid}, the pattern
                # acl_graph_users._graph_namespace derives).
                defaults += 1
                continue
            try:
                r = create_acl_user(row["graph_id"], org_id)
                if r is None:
                    skipped += 1  # ACL layer absent — fail-soft, reported
                else:
                    ok += 1
            except Exception as e:
                # A RAISED failure (server-reachable AclLayerError class) is
                # surfaced in the summary — never silently swallowed.
                _logger.warning("acl reconcile failed for %s/%s: %s",
                                org_id, row.get("graph_id"), e)
                errors.append(f"{row.get('graph_id')}: {e}")
        results[org_id] = {"status": "reconciled", "custom_graphs_ok": ok,
                            "acl_absent_skipped": skipped,
                            "default_skipped": defaults,
                            "errors": errors}
    return {"status": "reconciled", "organizations": len(results), "results": results}


@app.post("/v1/internal/backups/acl-reconcile")
async def backups_acl_reconcile(request: Request):
    """Post-restore ACL rebuild/verification (#2313 folded delta): every
    ACTIVE graph of every org must have its per-graph ACL user.

    A full-platform restore (disaster recovery into a fresh FalkorDB server)
    restores graph DATA from R2 — ACL server users do NOT live in the graph
    namespace and are lost with the old server. ``create_acl_user`` is the
    idempotent rebuild primitive (full-reset upsert; registry/selfhost mode
    reuses the stored credential, hosted create-once verifies without
    password churn). This reconcile replays it per ACTIVE graph — the DR
    runbook's post-restore step. Idempotent + fail-soft: ACL-layer absence
    (no server URI / bare redis) is reported, never a 500. Runs off the
    event loop via ``asyncio.to_thread`` (#2371).
    """
    _check_internal(request)
    return await asyncio.to_thread(_reconcile_acl_users_sync)


@app.post("/v1/internal/backups/sweep")
async def backups_sweep(request: Request):
    """Run the per-org backup sweep (driver's core action). Internal-key only."""
    _check_internal(request)
    cfg = _backup_config_safe()
    if cfg is None:
        raise HTTPException(status_code=503, detail="Backup sweep disabled")
    from tortoise.backup_sweep import run_backup_sweep

    # #2823 (P0): the control plane resolves through the SHARED dialect-aware
    # seam. `_registry_sdk()._get_registry()` is the pre-#669 resolution — the
    # post-flip graph is DELETED, so the sweep enumerated 0 orgs, reported a
    # benign `no_teams`, and backed nothing up from the flip until now.
    registry = _control_plane_source()
    # #2823/#669: the DATA-plane handle (#1366) — the data-plane SDK, never
    # the registry namespace (see _control_plane_source's docstring).
    db = _make_sdk(namespace=None)._get_proj().db
    storage = _backup_storage()
    try:
        mirror = _backup_mirror_storage(cfg)
    except RuntimeError as e:
        raise HTTPException(status_code=503,
                            detail=f"Mirror storage misconfigured: {e}") from e

    # In-flight guard: a concurrent sweep returns 202 (no queueing — the next
    # hourly run retries). This is what the driver's 202 branch keys on.
    if _SWEEP_INFLIGHT.locked():
        # #2823: the dialect rides the 202 too — a lock-held run is the one
        # shape where an unresolved dialect would otherwise surface as `unknown`
        # to every consumer of the sweep result (the source is already resolved
        # above).
        from tortoise.hosted_backup import source_dialect

        return {"status": "already_running", "teams_backed_up": 0,
                "source": source_dialect(registry)}
    async with _SWEEP_INFLIGHT:
        def lock_for(org_id: str):
            return _sweep_org_lock(org_id)

        try:
            result = await asyncio.to_thread(
                run_backup_sweep, db=db, registry=registry, storage=storage,
                config=cfg, lock_for=lock_for, mirror=mirror,
            )
        except RuntimeError as e:
            raise HTTPException(status_code=503, detail=f"Sweep failed: {e}")  # noqa: B904

        alerts = _alert_store_from(cfg)
        alerts_failed = []
        for inc in result.get("incidents", []):
            try:
                # #2313: graph-scoped incidents (custom graphs) route under
                # the "{org}:{gid}" subject — coherent with the watcher and
                # re-baseline. Default/org incidents keep the bare org.
                await asyncio.to_thread(
                    alerts.open_incident, inc["kind"],
                    _incident_subject(inc), inc.get("detail")
                )
            except Exception as e:  # incident-filing must never fail the run (review P3)
                _logger.warning("incident routing failed for %s: %s", inc.get("kind"), e)
                alerts_failed.append(inc.get("kind"))
        if alerts_failed:
            result["alerts_failed"] = alerts_failed

        # ── #3030: producer-side resolution for the sweep's guard kinds. ──
        # The sweep is the authority on its own guards: a conclusive run that did
        # NOT emit a kind, with POSITIVE evidence the guard ran/looked, is the
        # "condition cleared" evidence — closed through the same delete-to-resolve
        # lifecycle the watcher uses. `sweep_resolutions` owns that decision
        # (degraded runs and un-checked graphs clear nothing).
        #
        # Review: the candidate list is intersected with what is actually OPEN —
        # one LIST per kind, never an R2 GET per graph, so an hourly sweep over a
        # few thousand graphs does not serialise thousands of reads while holding
        # the sweep lock (nor does a listing failure close anything).
        from tortoise.backup_sweep import sweep_resolutions

        candidates = sweep_resolutions(result)
        resolved: list[str] = []
        failed: list[str] = []
        open_cache: dict[str, set[str]] = {}
        for kind, subject in candidates:
            try:
                if kind not in open_cache:
                    # strict: a failed LIST must not be indistinguishable from
                    # "nothing open" (it would make an R2 outage read as a clean
                    # sweep — final-cycle review P2). The raise lands below.
                    open_cache[kind] = await asyncio.to_thread(
                        alerts.open_subjects, kind, strict=True
                    )
                # A platform subject has two spellings in the store: `_` (what
                # `_key()` writes for an empty subject) and a literal `global`
                # (the restore-drill path files that one). They are DIFFERENT
                # objects, so match whichever is open and resolve BOTH when both
                # are (resolving only the matched one left the other open forever
                # — cycle-3/4 review).
                spellings = [subject] if subject else ["", "global"]
                targets = [
                    t for t in spellings
                    if (t or "_") in open_cache[kind]
                ]
                if not targets:
                    continue
                for target in targets:
                    if await asyncio.to_thread(alerts.resolve_incident, kind, target):
                        resolved.append(f"{kind}/{target}" if target else kind)
            except Exception as e:
                # A raised close (incident still open) OR a failed listing. Do not
                # report it as resolved; surface it so the run does not read as a
                # clean sweep.
                failed.append(f"{kind}/{subject}" if subject else kind)
                _logger.warning(
                    "incident resolve failed for %s/%s: %s", kind, subject or "global", e
                )
        # `incidents_resolved` means "dedup objects CLEARED", which includes
        # placeholders and tombstones — not necessarily issues closed (cycle-3
        # review). `incidents_unresolved` is the honest counterpart.
        if resolved:
            result["incidents_resolved"] = resolved
        if failed:
            result["incidents_unresolved"] = failed
        return result


@app.post("/v1/internal/backups/purge")
async def backups_purge(request: Request):
    """#2304 — trash purge: physically erase every expired tombstone
    (custom graphs deleted > grace_days ago, plus legacy tombstones).
    Internal-key only. Optional ``{"grace_days": N}`` overrides the _TRASH_GRACE_DAYS
    default (operator drills). Ownership-guarded namespace drops, idempotent,
    per-org/`-graph isolation; purged rows are stamped (kept — audit).
    In-flight guard: a concurrent purge returns 202.

    Cadence: operator-invoked today (runbook); the driver cron wiring lands
    with #2317's registry-cron.sh changes (coordination — same file)."""
    _check_internal(request)
    body = await _read_internal_json_body(request)
    from tortoise.backup_sweep import run_graph_purge

    # #2823/#2340: dialect-aware control plane. `run_graph_purge` enumerates
    # orgs through the same seam — off the raw registry handle it purged 0
    # orgs in Supabase mode (expired trash never erased).
    registry = _control_plane_source()
    # #2823/#669: the DATA-plane handle (#1366) — the data-plane SDK, never
    # the registry namespace (see _control_plane_source's docstring).
    db = _make_sdk(namespace=None)._get_proj().db
    storage = _backup_storage()
    grace_days = int((body or {}).get("grace_days")
                     or _TRASH_GRACE_DAYS)
    if not 1 <= grace_days <= 365:
        raise HTTPException(status_code=422,
                            detail="grace_days must be 1..365")
    if grace_days < _TRASH_GRACE_DAYS and not (body or {}).get(
            "confirm_short_grace"):
        # #2566 (re-audit P3): an operator grace_days override SHORTENS the
        # user-visible recovery window the trash UI/restore API still
        # promise — a drill with a small value permanently erases rows
        # inside the promised window with no restore escape. Require an
        # explicit confirmation.
        raise HTTPException(
            status_code=422,
            detail="grace_days below the standard recovery window "
                   f"({_TRASH_GRACE_DAYS}) requires confirm_short_grace: true")
    if _PURGE_INFLIGHT.locked():
        return {"status": "already_running", "purged": []}
    async with _PURGE_INFLIGHT:
        def lock_for(org_id: str):
            return _sweep_org_lock(org_id)

        try:
            return await asyncio.to_thread(
                run_graph_purge, db=db, registry=registry, storage=storage,
                grace_days=grace_days, lock_for=lock_for,
            )
        except RuntimeError as e:
            raise HTTPException(status_code=503,
                                detail=f"Purge failed: {e}") from e


@app.post("/v1/internal/backups/verify-lock")
async def backups_verify_lock(request: Request):
    """#2319 — live R2 bucket-lock drift check. Internal-key only.

    Reads the Cloudflare REST lock-rules configuration for the primary backup
    bucket (default) or an override ``{"account_id", "bucket"}`` (e.g. the
    second-region mirror store — the same rule must protect it) and compares
    the strictest retention covering the ``backups/`` prefix against
    ``BACKUP_LOCK_DAYS``.

    Returns ``{"status": verified|drift|absent|unverifiable, ...}``. The R2
    S3 seam cannot read lock state (Object-Lock/versioning APIs are
    unimplemented), so this requires an R2-scoped ``CF_API_TOKEN`` (account
    token, set out-of-band on Fly). Without one the status is unverifiable
    and the ops runbook (docs/ops/registry-backup-dr.md §#2319) is the
    verification path. A lock-read failure never fails backups themselves.
    """
    _check_internal(request)
    body = await _read_internal_json_body(request)
    cfg = _backup_config_safe()
    if cfg is None:
        raise HTTPException(status_code=503, detail="Backup sweep disabled")
    from tortoise.hosted_backup import (
        LockVerificationError,
        fetch_r2_bucket_lock_rules,
        verify_bucket_lock,
    )

    account_id = (body or {}).get("account_id") or cfg.r2_account_id
    bucket = (body or {}).get("bucket") or cfg.r2_bucket
    out: dict = {"enabled": cfg.lock_enabled, "bucket": bucket,
                 "prefix": "backups/",
                 "expected_days": cfg.lock_days}
    if not cfg.lock_enabled:
        out.update({
            "status": "absent",
            "detail": "BACKUP_LOCK_ENABLED is not set — provision the rule "
                       "(runbook) and set it before relying on immutability",
        })
        return out
    if not cfg.cf_api_token:
        out.update({
            "status": "unverifiable",
            "detail": "CF_API_TOKEN not set — verify via the ops runbook "
                       "(console/wrangler steps)",
        })
        return out
    try:
        rules = fetch_r2_bucket_lock_rules(
            str(account_id), cfg.cf_api_token, str(bucket))
        out.update(verify_bucket_lock(rules, expected_days=cfg.lock_days))
    except LockVerificationError as e:
        out.update({"status": "unverifiable", "detail": str(e)})
    return out


@app.get("/v1/internal/backups/status")
async def backups_status(request: Request):
    """Operator/driver status — per-org tri-state, watcher + driver liveness."""
    _check_internal(request)
    from tortoise.backup_config import ConfigError, load_config
    from tortoise.backup_watcher import HEARTBEAT_KEY

    config_error = None
    try:
        cfg = load_config()
    except ConfigError as e:
        cfg = None
        config_error = str(e)
    try:
        storage = _backup_storage()
    except RuntimeError as e:
        return {"enabled": False, "app_time": datetime.now(UTC).isoformat(),
                "storage_error": str(e), "per_team": {}, "no_teams": False}
    lock_block = _lock_status_block(cfg)
    watcher = _WATCHER
    now = datetime.now(UTC)
    watcher_status = watcher._watcher._last_status if watcher else {}
    hb = {}
    storage_error = None
    try:
        parsed = _json.loads(storage.download(HEARTBEAT_KEY))
        hb = parsed if isinstance(parsed, dict) else {}
    except KeyError:
        pass  # not-yet-written heartbeat is benign, not an error
    except Exception as e:  # R2 hiccup must never 500 /status (live-E2E fix)
        storage_error = f"heartbeat read: {e}"
    # #2372: surface the SWEEP's own run roll-up (ops/state.json — written
    # every run) so an operator sees per-graph totals/failures/streaks, not
    # just the watcher's archive-age tri-state.
    sweep_state = {}
    try:
        parsed = _json.loads(storage.download("ops/state.json"))
        if isinstance(parsed, dict):
            sweep_state = parsed
    except KeyError:
        pass  # sweep never ran yet — benign
    except Exception as e:
        storage_error = f"{storage_error}; ops-state read: {e}" if storage_error else f"ops-state read: {e}"
    last_sweep = {
        key: sweep_state.get(key)
        for key in ("last_sweep_at", "last_team_count", "graph_totals",
                    "graph_failures", "graph_error_streaks", "source",
                    # #2823: the most recent run's dialect, which differs from
                    # ``source`` only on a no-op run (whose roll-up preserves
                    # the last REAL sweep's outcome fields + dialect).
                    "last_run_source")
    }
    if not last_sweep.get("last_sweep_at"):
        # #2823 (code-review cycle 4): a deployment whose ONLY runs were no-ops
        # has a dialect in ops/state.json but no `last_sweep_at` (see
        # backup_sweep._noop_ops_state). Nulling the whole block there hid the
        # lane on exactly the fresh / misconfigured deployment an operator is
        # diagnosing — `_refuse_wrong_dialect` is deliberately one-directional,
        # so a registry-dialect source on a Supabase deployment is NOT caught
        # there. Keep the block when it can still name the lane; never
        # fabricate the outcome fields (the driver reads
        # `.last_sweep.last_sweep_at // empty`, so their absence stays
        # meaningful).
        dialect_only = {
            key: last_sweep[key]
            for key in ("source", "last_run_source")
            if last_sweep.get(key)
        }
        last_sweep = dialect_only or None  # sweep never ran — omit the block
    driver_hb = {}
    try:
        parsed = _json.loads(storage.download(_DRIVER_HEARTBEAT_KEY))
        driver_hb = parsed if isinstance(parsed, dict) else {}
    except KeyError:
        pass  # not-yet-written driver heartbeat is benign
    except Exception as e:
        storage_error = f"{storage_error}; driver-heartbeat read: {e}" if storage_error else f"driver-heartbeat read: {e}"
    # #2317: surface the last drill record (ops/drills/last.json — pass/fail
    # + measured restore time vs the committed RTO) so scheduled-restore-drill
    # outcomes are REPORTED, not just logged in the workflow.
    last_drill = None
    try:
        parsed = _json.loads(storage.download(_DRILL_RECORD_KEY))
        if isinstance(parsed, dict):
            last_drill = parsed
    except KeyError:
        pass  # no drill ever ran — benign
    except Exception as e:
        storage_error = f"{storage_error}; drill-record read: {e}" if storage_error else f"drill-record read: {e}"

    watcher_age_min = None
    if hb.get("last_poll_at"):
        try:  # noqa: SIM105
            watcher_age_min = (now - datetime.fromisoformat(hb["last_poll_at"])).total_seconds() / 60.0
        except ValueError:
            pass
    driver_age_min = None
    if driver_hb.get("ran_at"):
        try:  # noqa: SIM105
            driver_age_min = (now - datetime.fromisoformat(driver_hb["ran_at"])).total_seconds() / 60.0
        except ValueError:
            pass

    return {
        "enabled": bool(cfg and cfg.enabled),
        "config_error": config_error,
        "storage_error": storage_error,
        "app_time": now.isoformat(),
        "lock": lock_block,
        "per_team": watcher_status.get("per_team", {}),
        "no_teams": watcher_status.get("no_teams", False),
        "unknown": watcher_status.get("unknown", False),
        "last_sweep": last_sweep,
        "last_drill": last_drill,
        "watcher": {
            "running": bool(watcher and watcher._thread and watcher._thread.is_alive()),
            "last_poll_at": hb.get("last_poll_at"),
            "age_minutes": watcher_age_min,
            "r2_ok": hb.get("r2_ok"),
        },
        "driver": {"last_heartbeat_at": driver_hb.get("ran_at"), "age_minutes": driver_age_min},
    }

@app.post("/v1/internal/driver/heartbeat")
async def driver_heartbeat(request: Request):
    """Driver liveness — written through the app so R2 creds stay off GH for
    this leg; a stale heartbeat is only meaningful when the app is up."""
    _check_internal(request)
    body = await _read_internal_json_body(request, required=True)
    storage = _backup_storage()
    storage.upload(
        _DRIVER_HEARTBEAT_KEY,
        _json.dumps({"ran_at": datetime.now(UTC).isoformat(), "body": body or {}}).encode(),
        content_type="application/json",
    )
    return {"ok": True}


@app.post("/v1/internal/backups/simulate-stale")
@app.post("/v1/internal/backups/simulate-recover")
async def backups_simulate(request: Request):
    """Simulated-stale hooks (env-gated, fail closed) — prove the detection →
    filing → dedup path end-to-end in staging."""
    _check_internal(request)
    cfg = _backup_config_safe()
    if cfg is None or not cfg.simulate_enabled:
        raise HTTPException(status_code=403, detail="simulate disabled (BACKUP_SIMULATE_ENABLED)")
    storage = _backup_storage()
    now = datetime.now(UTC)
    if request.url.path.endswith("simulate-stale"):
        ts = now.strftime("%Y%m%dT%H%M%S%fZ")
        storage.upload(
            f"ops/simulate/stale-{ts}.json",
            _json.dumps({
                "age_ts": (now - timedelta(hours=100)).isoformat(),
                "expires_at": (now + timedelta(hours=2)).isoformat(),
            }).encode(),
            content_type="application/json",
        )
        return {"status": "simulated_stale"}
    for k in storage.list("ops/simulate/"):
        storage.delete(k)
    return {"status": "simulated_recovered"}


@app.post("/v1/internal/backups/re-baseline")
async def backups_rebaseline(request: Request):
    """Operator re-baseline: acknowledge a fired DATA_LOSS_CANDIDATE by
    re-persisting the current counts of the target graph (default unless
    ``body.graph_id`` names a custom graph) — closes the incident.

    #2313: per-graph re-baseline. The default graph updates the per-graph
    state AND mirrors the legacy org file (the pre-#2313 surface); custom
    graphs update only their per-graph state. Incident subjects follow the
    graph: bare org for the default, "{org}:{gid}" for customs (the same
    key the sweep routes and the watcher uses).
    """
    _check_internal(request)
    body = await _read_internal_json_body(request, required=True)
    org_id = body.get("org_id", "")
    graph_id = body.get("graph_id", "default")
    if not org_id:
        raise HTTPException(status_code=400, detail="org_id required")
    from tortoise.hosted_backup import (
        _validate_graph_id,
        _validate_org_id,
        count_data_nodes,
    )
    try:
        # #2377 (defense in depth): org_id/graph_id flow into R2 state keys
        # (_graph_state_key + the legacy org-file write below) — apply the
        # same charset gate every create/prune backup write got, so a
        # future non-server-generated row id can never mint keys outside the
        # org's prefix. resolve_active_graph gates against enumerated rows;
        # this gates the shape first.
        _validate_org_id(org_id)
        _validate_graph_id(graph_id)
    except ValueError as e:
        raise HTTPException(status_code=400, detail=f"Re-baseline rejected: {e}")  # noqa: B904
    from tortoise.backup_sweep import (
        _graph_state_key,
        _write_json,
        read_org_state,
        resolve_active_graph,
    )

    # #2823/#2340: dialect-aware control plane — `resolve_active_graph`
    # enumerates the org's graphs through this source; the raw registry handle
    # 400s/409s ACTIVE Supabase-lane graphs.
    registry = _control_plane_source()
    # #2823/#669: the DATA-plane handle (#1366) — the data-plane SDK, never
    # the registry namespace (see _control_plane_source's docstring).
    db = _make_sdk(namespace=None)._get_proj().db
    storage = _backup_storage()
    try:
        row = resolve_active_graph(registry, org_id, graph_id)
    except ValueError as e:
        raise HTTPException(status_code=400, detail=f"Re-baseline rejected: {e}")  # noqa: B904
    except RuntimeError as e:
        raise HTTPException(status_code=503, detail=f"Re-baseline failed: {e}")  # noqa: B904
    try:
        # #4233: count the SAME node set every other DR surface counts —
        # dump_graph's (the sweep manifest, the empty-backup guard, drill
        # verification). A raw `MATCH (n)` included the projection's internal
        # `Meta {key:'point_fts_v2'}` marker once a projection had been opened
        # on the org graph, so a 3-point graph re-baselined to 4 and flaked the
        # required check on unrelated PRs.
        count = count_data_nodes(db, row["graph_name"])
    except Exception as e:
        raise HTTPException(status_code=503, detail=f"graph unavailable: {e}")  # noqa: B904
    state = {
        **(read_org_state(storage, org_id)
          if graph_id == "default" else {}),
        "node_count": count,
        "updated_at": datetime.now(UTC).isoformat(),
    }
    _write_json(storage, _graph_state_key(org_id, graph_id), state)
    if graph_id == "default":
        _write_json(storage, f"ops/teams/{org_id}/state.json", state)
    subject = f"{org_id}:{graph_id}" if graph_id != "default" else org_id
    alerts = _alert_store_from(_backup_config_safe())
    # The state write above already succeeded, so a resolve failure must NOT fail
    # the request (cycle-2 review P2: `resolve_incident` now RAISES on a failed
    # close instead of returning silently — an unguarded call here would 500 the
    # re-baseline AFTER the operator's verdict was persisted, and the caller would
    # reasonably retry a state write that already happened).
    #
    # But NOTHING else resolves these two kinds, so a failed close leaves the
    # incident open with no retry — the response and the log must say so rather
    # than implying a poll will retry (cycle-3 review P1). The outcome is reported
    # per kind so the operator can re-run re-baseline after GitHub recovers.
    incidents_failed: list[str] = []
    for kind in ("DATA_LOSS_CANDIDATE", "SIZE_GUARD_ABORT"):
        try:
            alerts.resolve_incident(kind, subject)
        except Exception:
            incidents_failed.append(f"{kind}/{subject}")
            _logger.warning(
                "%s resolve failed on re-baseline of %s — the incident is STILL OPEN "
                "and only another re-baseline (or a manual close) clears it; re-run "
                "once the GitHub API recovers", kind, subject, exc_info=True,
            )
    out = {"status": "rebaselined", "org_id": org_id,
           "graph_id": graph_id, "node_count": count}
    if incidents_failed:
        out["incidents_unresolved"] = incidents_failed
    return out


def _drill_record(
    *,
    run: str,
    status: str,
    org_id: str,
    graph_id: str,
    backup_key: str,
    duration_s: float | None,
    detail: dict | None = None,
) -> dict:
    """#2317 drill record — pass/fail + measured restore time vs the RTO.

    ``status`` is one of ``ok`` (restored within RTO), ``rto_breach``
    (restored but slower than the committed ≤15-min target), ``rejected``
    (ValueError — unresolvable/foreign/corrupt archive), ``failed``
    (RuntimeError — storage/DB fault) or ``no_candidates`` (scheduled drill
    found no eligible nested archive). Written to ops/drills/last.json and
    surfaced on GET /v1/internal/backups/status → last_drill.
    """
    within = None
    if duration_s is not None:
        within = bool(duration_s <= _DRILL_RTO_S)
    return {
        "run": run,
        "at": datetime.now(UTC).isoformat(),
        "status": status,  # ok | rto_breach | rejected | failed | no_candidates
        "ok": status == "ok",
        "org_id": org_id,
        "graph_id": graph_id,
        "backup_key": backup_key,
        "duration_s": round(float(duration_s), 3) if duration_s is not None else None,
        "rto_s": _DRILL_RTO_S,
        "within_rto": within,
        "detail": detail or {},
    }


def _write_drill_record(storage, record: dict) -> bool:
    """Best-effort durable drill record (ops/drills/last.json). A record-write
    failure never fails the drill itself — the /status.last_drill surface
    simply stays at its previous value until the next successful write."""
    try:
        storage.upload(
            _DRILL_RECORD_KEY,
            _json.dumps(record, indent=2).encode("utf-8"),
            content_type="application/json",
        )
        return True
    except Exception as e:
        _logger.warning("drill record write failed: %s", e)
        return False


def _drill_execute(
    *,
    cfg,
    registry,
    db,
    storage,
    org_id: str,
    backup_key: str,
    graph_name: str | None = None,
    run: str = "manual",
) -> dict:
    """One drill attempt — resolve → restore → scratch cleanup → record.

    Sync (blocking redis/R2 round-trips) — the endpoints run it in a worker
    thread. ``graph_name`` may be pre-resolved by a caller (drill-scheduled
    pre-filters candidates through the ACTIVE seam); None resolves here (the
    manual drill surface). Restores the real archive into ``_drill_*``
    scratch (zero production writes — asserted server-side; the registry
    end-stamp is skipped via drill=True).

    Raises ValueError (drill REJECTED: unresolvable/foreign/corrupt archive)
    and RuntimeError (drill FAILED: storage/DB fault) — the endpoints map to
    HTTP 409/503. Both paths record the outcome first.

    Returns the ``drill_ok`` payload: ``{status, target_graph, duration_s,
    rto_s, within_rto, record, **restore_result}``.
    """
    from tortoise.hosted_backup import _parse_backup_key, restore_backup

    ts = datetime.now(UTC).strftime("%Y%m%dT%H%M%S%fZ")
    target_graph = f"_drill_{ts}"
    graph_id = ""
    start = time.monotonic()
    try:
        if graph_name is None:
            from tortoise.backup_sweep import resolve_active_graph

            _parsed_org, _parsed_graph, _ = _parse_backup_key(backup_key)
            graph_id = _parsed_graph or "default"
            # #2313: the artifact's key shape names its graph; resolve the
            # target through the ACTIVE-graph seam (tombstone guard — a drill
            # of a deleted/quarantined graph is refused) so the drill
            # exercises the REAL graph's name, not a hardcoded org_{id}.
            graph_name = resolve_active_graph(registry, org_id, graph_id)["graph_name"]
        else:
            try:  # parse only for the record (graph_name already resolved)
                _parsed_org, _parsed_graph, _ = _parse_backup_key(backup_key)
                graph_id = _parsed_graph or "default"
            except ValueError:
                graph_id = ""
        result = restore_backup(
            db, registry, storage, backup_key,
            org_id=org_id, graph_name=graph_name,
            key=cfg.backup_key, target_graph=target_graph, drill=True,
        )
        duration_s = time.monotonic() - start
    except ValueError as e:
        _write_drill_record(
            storage,
            _drill_record(
                run=run, status="rejected", org_id=org_id, graph_id=graph_id,
                backup_key=backup_key, duration_s=time.monotonic() - start,
                detail={"error": str(e)},
            ),
        )
        raise
    except RuntimeError as e:
        _write_drill_record(
            storage,
            _drill_record(
                run=run, status="failed", org_id=org_id, graph_id=graph_id,
                backup_key=backup_key, duration_s=time.monotonic() - start,
                detail={"error": str(e)},
            ),
        )
        raise
    # Cleanup the scratch graph (best-effort; boot GC is the backstop).
    try:  # noqa: SIM105
        db.select_graph(target_graph).delete()
    except Exception:
        pass
    within_rto = duration_s <= _DRILL_RTO_S
    # #3845: surface a wedge distinctly — "fork slot wedged" must never be
    # readable as a plain "copy failed". #4233: surface a copy (either the
    # pre-restore safety copy or the swap) that outlived the restore's read
    # bound the same way, so an RTO breach caused by it is attributable from
    # the PERSISTED record/incident, not only the immediate response. Both
    # absent on the clean path, so a healthy drill record is unchanged.
    detail = {k: v for k, v in (
        ("restored", result.get("restored")),
        ("fork_slot", result.get("fork_slot")),
        ("copy_read_bound_overrun", result.get("copy_read_bound_overrun")),
    ) if v is not None}
    record = _drill_record(
        run=run, status="ok" if within_rto else "rto_breach",
        org_id=org_id, graph_id=graph_id, backup_key=backup_key,
        duration_s=duration_s, detail=detail,
    )
    _write_drill_record(storage, record)
    return {
        "status": "drill_ok",
        "target_graph": target_graph,
        "duration_s": round(duration_s, 3),
        "rto_s": _DRILL_RTO_S,
        "within_rto": within_rto,
        "record": record,
        **result,
    }


def _scheduled_drill(*, cfg, registry, db, storage) -> dict:
    """Scheduled (monthly, unattended) drill body — sync; worker-threaded.

    Picks the OLDEST eligible nested archive across orgs (see
    ``backup_sweep.list_drill_candidates``), skips candidates whose graph is
    no longer ACTIVE (quarantined/deleted — #2304 tombstone guard), drills
    the first eligible one, and records pass/fail + measured restore time.
    With no eligible archive it records ``no_candidates`` and returns that
    status (the chronic no-archive state is the existing LIVENESS_NO_WORK /
    NEVER_BACKED_UP alarm's job, not a drill failure).
    """
    from tortoise.backup_sweep import list_drill_candidates, resolve_active_graph

    candidates = list_drill_candidates(storage)  # RuntimeError on list failure
    for cand in candidates:
        try:  # skip candidates whose graph is not ACTIVE (never a drill source)
            row = resolve_active_graph(registry, cand["org_id"], cand["graph_id"])
        except ValueError:
            continue
        return _drill_execute(
            cfg=cfg, registry=registry, db=db, storage=storage,
            org_id=cand["org_id"], backup_key=cand["backup_key"],
            graph_name=row["graph_name"], run="scheduled",
        )
    record = _drill_record(
        run="scheduled", status="no_candidates", org_id="", graph_id="",
        backup_key="", duration_s=None,
        detail={
            "reason": "no eligible nested archive across teams",
            "candidates_seen": len(candidates),
        },
    )
    _write_drill_record(storage, record)
    return {"status": "no_candidates", "record": record}


@app.post("/v1/internal/backups/drill")
async def backups_drill(request: Request):
    """Drill-only restore: scratch target, internal-key auth, zero production
    writes (drill:true skips the registry end-stamp; live-phase binds the
    scratch target). Cooldown ≥1h between drill accepts (in-memory). #2317:
    every drill now records pass/fail + measured restore time to
    ops/drills/last.json (surfaced on /status → last_drill)."""
    _check_internal(request)
    global _LAST_DRILL_AT
    cfg = _backup_config_safe()
    if cfg is None:
        raise HTTPException(status_code=503, detail="Backup sweep disabled")
    body = await _read_internal_json_body(request, required=True)
    org_id = body.get("org_id", "")
    backup_key = body.get("backup_key", "")
    if not org_id or not backup_key:
        raise HTTPException(status_code=400, detail="org_id and backup_key required")
    import time as _time

    if _time.time() - _LAST_DRILL_AT < _DRILL_COOLDOWN_S:
        raise HTTPException(status_code=429, detail="drill cooldown — ≥1h between drills")
    _LAST_DRILL_AT = _time.time()

    # #2823/#2340: dialect-aware control plane (see re-baseline).
    registry = _control_plane_source()
    # #2823/#669: the DATA-plane handle (#1366) — the data-plane SDK, never
    # the registry namespace (see _control_plane_source's docstring).
    db = _make_sdk(namespace=None)._get_proj().db
    storage = _backup_storage()
    try:
        return await asyncio.to_thread(
            _drill_execute, cfg=cfg, registry=registry, db=db, storage=storage,
            org_id=org_id, backup_key=backup_key,
        )
    except ValueError as e:
        raise HTTPException(status_code=409, detail=f"Drill rejected: {e}") from e
    except RuntimeError as e:
        raise HTTPException(status_code=503, detail=f"Drill failed: {e}") from e


@app.post("/v1/internal/backups/drill-scheduled")
async def backups_drill_scheduled(request: Request):
    """#2317: SCHEDULED (monthly, unattended) verification-restore drill.

    Auto-selects the OLDEST eligible nested archive across orgs (tombstoned/
    deleted graphs' archives are skipped, never drilled — #2304), restores it
    into ``_drill_*`` scratch via the shared drill core, and records
    pass/fail + measured restore time to ops/drills/last.json (surfaced on
    /status → last_drill). A failed drill OR an RTO breach (restore slower
    than the committed ≤15 min) opens a deduplicated RESTORE_DRILL_FAILED
    incident (GitHub issue + Telegram, existing dual-channel); success and
    the no-candidates state resolve it. Same ≥1h cooldown and boot-GC
    backstop as the manual drill. Intended caller: the monthly
    registry-drill-cron workflow.
    """
    _check_internal(request)
    global _LAST_DRILL_AT
    cfg = _backup_config_safe()
    if cfg is None:
        raise HTTPException(status_code=503, detail="Backup sweep disabled")
    import time as _time

    if _time.time() - _LAST_DRILL_AT < _DRILL_COOLDOWN_S:
        raise HTTPException(status_code=429, detail="drill cooldown — ≥1h between drills")
    _LAST_DRILL_AT = _time.time()

    # #2823/#2340: dialect-aware control plane — the scheduled drill resolves
    # its candidate's active graph through this source.
    registry = _control_plane_source()
    # #2823/#669: the DATA-plane handle (#1366) — the data-plane SDK, never
    # the registry namespace (see _control_plane_source's docstring).
    db = _make_sdk(namespace=None)._get_proj().db
    storage = _backup_storage()
    alerts = _alert_store_from(cfg)
    try:
        result = await asyncio.to_thread(
            _scheduled_drill, cfg=cfg, registry=registry, db=db, storage=storage,
        )
    except ValueError as e:
        try:
            await asyncio.to_thread(
                alerts.open_incident, _DRILL_FAILED_KIND, "global",
                {"error": str(e), "source": "drill-scheduled"},
            )
        except Exception:
            _logger.warning("RESTORE_DRILL_FAILED open failed (ValueError path)", exc_info=True)
        raise HTTPException(status_code=409, detail=f"Drill rejected: {e}") from e
    except RuntimeError as e:
        try:
            await asyncio.to_thread(
                alerts.open_incident, _DRILL_FAILED_KIND, "global",
                {"error": str(e), "source": "drill-scheduled"},
            )
        except Exception:
            _logger.warning("RESTORE_DRILL_FAILED open failed (RuntimeError path)", exc_info=True)
        raise HTTPException(status_code=503, detail=f"Drill failed: {e}") from e
    if result.get("status") == "drill_ok" and not result.get("within_rto", True):
        # Restore succeeded but missed the committed RTO — incident-worthy
        # (restore speed is a target, not an accident).
        try:
            await asyncio.to_thread(
                alerts.open_incident, _DRILL_FAILED_KIND, "global",
                {
                    "error": "restore exceeded the committed RTO",
                    "duration_s": result.get("duration_s"),
                    "rto_s": result.get("rto_s"),
                    "org_id": (result.get("record") or {}).get("org_id"),
                    "backup_key": (result.get("record") or {}).get("backup_key"),
                    # #4233: if either GRAPH.COPY (pre-restore safety copy or
                    # swap) outlived the restore's read bound, name it — that
                    # is the attributable cause.
                    "copy_read_bound_overrun": result.get(
                        "copy_read_bound_overrun"),
                },
            )
        except Exception:
            _logger.warning("RESTORE_DRILL_FAILED open failed (RTO-breach path)", exc_info=True)
    else:
        # success (or no eligible archive) closes any open incident. A failed
        # close has NO retry until the next monthly drill, so report it in the
        # response (final-cycle review P2 — the runbook claimed this field).
        try:
            await asyncio.to_thread(
                alerts.resolve_incident, _DRILL_FAILED_KIND, "global"
            )
        except Exception:
            result["incidents_unresolved"] = [f"{_DRILL_FAILED_KIND}/global"]
            _logger.warning(
                "RESTORE_DRILL_FAILED resolve failed — the incident is STILL OPEN "
                "and only another drill (or a manual close) clears it",
                exc_info=True,
            )
    return result


def _dashboard_base() -> str:
    """Dashboard host — single env-driven source (#1135).

    Matches the CLI claim-flow convention (__main__.py: TORTOISE_DASHBOARD_URL,
    default https://app.premiselabs.co); billing redirect defaults derive from
    it so the dashboard host is configured once.
    """
    v = os.environ.get("TORTOISE_DASHBOARD_URL")
    return v.strip() if v and v.strip() else "https://app.premiselabs.co"


_BILLING_ACTIVE_STATUSES = ("active", "trialing", "past_due")


def _billing_default_success_url() -> str:
    return f"{_dashboard_base()}/team?session_id={{CHECKOUT_SESSION_ID}}"


def _billing_default_cancel_url() -> str:
    return f"{_dashboard_base()}/team?checkout=cancelled"


def _billing_default_portal_return() -> str:
    return f"{_dashboard_base()}/team"


def _billing_error_to_http(exc: Exception) -> HTTPException:
    """Map billing exceptions to HTTP responses — degrade, never crash.

    BillingConfigError (missing STRIPE_* env, lazy by design) → 503;
    BillingError (bad input like an unknown price id) → 400;
    StripeAPIError (upstream failure) → 502.
    """
    from tortoise.billing import BillingConfigError, BillingError, StripeAPIError
    if isinstance(exc, BillingConfigError):
        return HTTPException(status_code=503, detail=str(exc))
    if isinstance(exc, BillingError):
        return HTTPException(status_code=400, detail=str(exc))
    if isinstance(exc, StripeAPIError):
        return HTTPException(status_code=502, detail=str(exc))
    return HTTPException(status_code=502, detail=str(exc))


def _billing_email_like(value: object) -> bool:
    """True when *value* is usable as a billing/customer email.

    #4504 review: ``APIKey.created_by`` is a CREATOR ID, not always an email —
    the same codebase writes a Supabase user UUID (``_mint_key``:
    ``session_user_id or "api"``), the literal ``"api"``, and (for
    /v1/register) an email address. Handing a UUID/``"api"`` to Stripe as the
    customer email either 502s or binds a garbage address, and — with the
    session fallback placed last — it shadowed that fallback for a genuinely
    entitled session user. The gate requires a real address shape — a single
    ``@``, a non-empty local part and domain, and no interior whitespace;
    surrounding whitespace is trimmed, so a caller that returns a passing
    value must return its ``.strip()``. UUIDs and ``"api"`` fail the gate and
    fall through.
    """
    if not isinstance(value, str):
        return False
    v = value.strip()
    if not v or v.count("@") != 1 or any(c.isspace() for c in v):
        return False
    local, _, domain = v.partition("@")
    return bool(local) and bool(domain)


def _billing_customer_email(sdk: TortoiseSDK | None, org: dict) -> str:
    """Resolve the billing email via the fallback chain (review fix 1):

    1. ``Org.email`` — set at /v1/register (self-service orgs); the resolved
       org dict carries it in BOTH lanes (registry Team node / Supabase orgs
       row) and is read as the ``t.email`` twin (#4640: Supabase mode passes
       ``sdk=None`` — the registry graph is deleted post-#669).
    2. ``APIKey.created_by`` — provision-path orgs (created via
       /internal/provision) have no ``Org.email``; the Edge Function stored
       the creator on the APIKey node instead. Prefer the key used for THIS
       request, fall back to any org key. Both links are shape-gated
       (``_billing_email_like``) because ``created_by`` may be a user UUID or
       ``"api"`` rather than an address (#4504 review) — a non-email creator
       id must fall through, not be posted to Stripe as the customer email.
    3. The VERIFIED session user's email (#4504) — OAuth/session users whose
       org carries no ``Team.email`` and whose keys carry no usable
       ``created_by`` (a dashboard/provisioned org) were refused a checkout
       they are entitled to. ``org[_SESSION_USER_EMAIL_KEY]`` is attached
       ONLY on the JWT branch of ``get_current_org_session``, from the
       signature-verified Supabase JWT's ``email`` claim — never a
       client-supplied body/header. Last in the chain: the existing
       resolutions keep precedence.
    4. 400 last resort — clear message, no crash.

    ``sdk`` is None in Supabase mode (#4640): the registry reads are skipped
    entirely, and resolution runs through the resolved org dict, which the
    control-plane seam populated from the authoritative row.
    """
    org_id = org["org_id"]
    if sdk is not None:
        row = sdk._get_registry().query(
            "MATCH (t:Team {id:$id}) RETURN t.email", params={"id": org_id}
        ).result_set
        if row and row[0][0]:
            return row[0][0]
    # #4640: the resolved org row's email — the ``t.email`` twin above, and the
    # only link available in Supabase mode. Registry parity: org["email"] IS
    # the t.email that read returns, so this is a selfhost no-op.
    if _billing_email_like(org.get("email")):
        return org["email"].strip()
    if sdk is not None:
        key_id = org.get("key_id")
        if key_id:
            row = sdk._get_registry().query(
                "MATCH (k:APIKey {id:$id}) RETURN k.created_by", params={"id": key_id}
            ).result_set
            if row and _billing_email_like(row[0][0]):
                return row[0][0].strip()
        row = sdk._get_registry().query(
            "MATCH (k:APIKey {org_id:$tid}) RETURN k.created_by LIMIT 1",
            params={"tid": org_id},
        ).result_set
        if row and _billing_email_like(row[0][0]):
            return row[0][0].strip()
    # #4504: verified session email — before the 400, after the existing
    # resolutions (precedence unchanged). Reached whenever no earlier link
    # produced an address — including a non-email ``created_by``.
    session_email = org.get(_SESSION_USER_EMAIL_KEY)
    if isinstance(session_email, str) and session_email.strip():
        return session_email.strip()
    raise HTTPException(
        status_code=400,
        detail="No customer email for this team — register with an email or "
               "provision via a key carrying created_by",
    )


def _billing_checkout_sync(org: dict, price_id: str) -> dict:
    """Sync body of POST /v1/billing/checkout (runs in a thread — the Stripe
    calls + registry writes are blocking).

    Order matters (scoping P1-2, review fix 1): resolve/validate price →
    stored-mirror guard → resolve email → create-or-reuse Stripe customer →
    SYNC-PERSIST ``stripe_customer_id`` on the authoritative store (#4640: the
    orgs row in Supabase mode, the Org node in registry mode; plus
    ``customer_email`` on first bind, or as a backfill when the stored one is
    empty — a reused customer keeps its stored email, see below) →
    stale-mirror race guard (list_subscriptions) → create Checkout session. A
    missed first webhook event leaves a reconcilable mirror (Task 8).

    #4640: Supabase mode reads/writes ``organizations`` through the
    control-plane seam, exactly as the webhook's ``_set`` does (#669: the
    registry graph is deleted there). The pre-fix code read and wrote the
    registry unconditionally — the reads matched nothing and the persist was a
    silent no-op (or a registry-graph resurrection, #878), so the portal's
    read of the same store found no customer.
    """
    from tortoise.billing import StripeClient
    from tortoise.supabase_control import (
        get_control_plane,
        is_supabase_enabled,
        org_billing_state,
        update_org_billing,
    )
    org_id = org["org_id"]
    supabase_mode = is_supabase_enabled()
    # Supabase mode never constructs a registry-namespaced SDK: post-#669 the
    # registry graph is deleted, so a read finds nothing and a write would
    # resurrect it (#878).
    sdk = None if supabase_mode else _make_sdk(namespace="registry")

    # Layer 1 guard: stored mirror already active → reject before any Stripe call.
    if supabase_mode:
        stored = org_billing_state(get_control_plane(), org_id)
    else:
        row = sdk._get_registry().query(
            "MATCH (t:Team {id:$id}) "
            "RETURN t.subscription_status, t.stripe_customer_id, t.customer_email",
            params={"id": org_id},
        ).result_set
        stored = ({"subscription_status": row[0][0],
                   "stripe_customer_id": row[0][1],
                   "customer_email": row[0][2]} if row else {})
    status = stored.get("subscription_status")
    stored_customer_id = stored.get("stripe_customer_id")
    stored_customer_email = stored.get("customer_email")
    if status in _BILLING_ACTIVE_STATUSES:
        raise HTTPException(status_code=409, detail="team already has an active subscription")

    email = _billing_customer_email(sdk, org)
    try:
        client = StripeClient()
        if stored_customer_id:  # noqa: SIM108
            customer_id = stored_customer_id  # create-or-fetch: reuse the Stripe customer
        else:
            customer_id = client.create_customer(email)
    except Exception as e:
        raise _billing_error_to_http(e) from e

    # Sync-persist the customer binding BEFORE the session (survives a missed
    # first event). When the customer is REUSED, keep an already-stored
    # ``customer_email``: it belongs to that Stripe customer, while the
    # resolved email may now come from a different member's session (#4504) —
    # rewriting it would make the mirror disagree with the address invoices go
    # to. Backfill only when the stored value is empty (the checkout webhook
    # persisted the binding without a customer_email).
    binding = {"stripe_customer_id": customer_id}
    if not (stored_customer_id and stored_customer_email):
        binding["customer_email"] = email
    if supabase_mode:
        update_org_billing(get_control_plane(), org_id, binding)
    elif stored_customer_id and stored_customer_email:
        sdk._get_registry().query(
            "MATCH (t:Team {id:$id}) SET t.stripe_customer_id=$cid",
            params={"id": org_id, "cid": customer_id},
        )
    else:
        sdk._get_registry().query(
            "MATCH (t:Team {id:$id}) SET t.stripe_customer_id=$cid, t.customer_email=$email",
            params={"id": org_id, "cid": customer_id, "email": email},
        )

    # Layer 2 guard: stale-mirror race — Stripe is the authority for money.
    try:
        subs = client.list_subscriptions(customer_id)
    except Exception as e:
        raise _billing_error_to_http(e) from e
    for sub in subs:
        if sub.get("status") in _BILLING_ACTIVE_STATUSES:
            raise HTTPException(status_code=409, detail="team already has an active subscription")

    try:
        url = client.create_checkout_session(
            org_id, price_id, customer_id,
            os.environ.get("BILLING_SUCCESS_URL", _billing_default_success_url()),
            os.environ.get("BILLING_CANCEL_URL", _billing_default_cancel_url()),
        )
    except Exception as e:
        raise _billing_error_to_http(e) from e
    return {"checkout_url": url}


@app.post("/v1/billing/checkout", response_model=CheckoutResponse)
async def billing_checkout(body: CheckoutRequest, request: Request, org: dict = Depends(get_current_org_session)):  # noqa: B008
    """Start a Stripe Checkout session for a validated price (org auth)."""
    from tortoise.billing import BillingConfigError, BillingError, PriceCatalog
    try:
        # Price validation against the catalog — unknown price_id → 400.
        PriceCatalog().tier_for_price(body.price_id)
    except BillingConfigError as e:
        raise HTTPException(status_code=503, detail=str(e))  # noqa: B904
    except BillingError as e:
        raise HTTPException(status_code=400, detail=str(e))  # noqa: B904
    return await asyncio.to_thread(_billing_checkout_sync, org, body.price_id)


# ── #2789: paid NEW organization (webhook-provisioned) ──────────────────────
# The third option of the one-free-org dialog. Checkout is otherwise
# org-scoped (billing_checkout above), which a not-yet-existing org cannot
# satisfy — hence a separate SESSION-authed endpoint. Design decision
# (documented in docs/scoping/2026-09-10-2789-one-free-org.md §3 S-B): no
# pending_payment org row. NOTHING is written here; the pre-minted org id
# rides Stripe and `checkout.session.completed` provisions the org. An
# abandoned checkout therefore leaves nothing visible and does not consume
# the user's one-free-org allowance.

def _new_org_org_id() -> str:
    """#2789: pre-mint the new org's id BEFORE the Stripe session exists.

    It must be known at session-creation time (``client_reference_id`` is a
    creation param), so it cannot be derived from the session id — the session
    id is Stripe's. 26-hex, matching the ids the create-org lanes mint (teams.id
    is unconstrained text, 0006). Echoed back by the webhook, where the
    existence check + ``provision_org``'s ON CONFLICT upsert make a replay a
    no-op — idempotency by construction rather than by care."""
    import uuid as _uuid
    return _uuid.uuid4().hex[:26]


def _new_org_collision_name(org_name: str, org_id: str) -> str:
    """#2789: the disambiguating name for a collision that happened AFTER
    checkout — the pre-check cannot see the future (someone else took the name
    between payment intent and webhook).

    Must stay legal in BOTH lanes, so NO parentheses (the registry SDK's
    validator is ``^[a-zA-Z0-9][a-zA-Z0-9_ -]*$`` and it rejects them — a
    paren suffix would make the retry raise forever and strand a paying
    customer), first char still alphanumeric, and <= 64 chars. 8 id chars (32
    bits) of entropy keeps a *second* collision vanishingly unlikely; if one
    did happen the raise surfaces as a 500 + ops log rather than silently
    stranding money.
    """
    suffix = str(org_id or "")[:8]
    return f"{org_name[: 63 - len(suffix)].rstrip()} {suffix}"


def _new_org_success_url(new_org_id: str, org_name: str = "") -> str:
    """#2789: the standard success URL + ``new_org=<id>`` (+ the intended name).

    The dashboard's success-return effect polls until the org appears in
    /v1/organizations and then switches to it (the webhook lands seconds later). The
    env template (``{CHECKOUT_SESSION_ID}``) is preserved verbatim — only a
    separator is chosen.

    ``new_org_name`` is carried because the pre-minted id is NOT always the
    org's real id: on the registry (selfhost) lane ``org_create`` mints its
    own, so the client matches the id OR the intended name (the name is the
    one column the webhook only changes on a collision).
    """
    base = os.environ.get("BILLING_SUCCESS_URL", _billing_default_success_url())
    sep = "&" if "?" in base else "?"
    url = f"{base}{sep}new_org={new_org_id}"
    if org_name:
        from urllib.parse import quote
        url += f"&new_org_name={quote(str(org_name))}"
    return url


def _billing_checkout_new_org_sync(user: dict, name: str, price_id: str) -> dict:
    """#2789 sync body: validate, pre-check the unique name, start Checkout.

    Order matters: the name is globally unique (0011) and the pre-check is the
    ONLY place a collision can be caught before money moves — a collision at
    webhook-provision time would leave a paying customer with no org. (The
    webhook still has a deterministic disambiguating fallback for the
    checkout→payment race the pre-check cannot see.)

    The entitlement is deliberately NOT consulted: the rules table says a user
    at the free cap may PURCHASE a second org ("requests a paid org → allowed"),
    and a user with zero orgs may also buy one.
    """
    from tortoise.billing import (
        BillingConfigError,
        BillingError,
        PriceCatalog,
        StripeClient,
    )
    from tortoise.supabase_control import (
        get_control_plane,
        is_supabase_enabled,
        org_by_name,
    )
    try:
        tier = PriceCatalog().tier_for_price(price_id)
    except BillingConfigError as e:
        raise HTTPException(status_code=503, detail=str(e))  # noqa: B904
    except BillingError as e:
        raise HTTPException(status_code=400, detail=str(e))  # noqa: B904
    if not tier or tier in ("free", "anon"):
        raise HTTPException(
            status_code=400,
            detail="A paid plan is required to purchase a new organization")
    if is_supabase_enabled():
        if org_by_name(get_control_plane(), name):
            raise HTTPException(status_code=409, detail="Organization name already exists")
    else:
        _dup = _make_sdk(namespace="registry")._get_registry().query(
            "MATCH (t:Team {name:$name}) RETURN count(t)", params={"name": name},
        ).result_set[0][0]
        if _dup:
            raise HTTPException(status_code=409, detail="Organization name already exists")

    new_org_id = _new_org_org_id()
    try:
        _sid, url = StripeClient().create_checkout_session_for_new_org(
            new_org_id=new_org_id, price_id=price_id,
            email=user.get("email") or "", user_id=user["user_id"],
            org_name=name, tier=tier,
            success_url=_new_org_success_url(new_org_id, name),
            cancel_url=os.environ.get("BILLING_CANCEL_URL", _billing_default_cancel_url()),
        )
    except Exception as e:
        raise _billing_error_to_http(e) from e
    return {"checkout_url": url, "org_id": new_org_id}


@app.post("/v1/billing/checkout/new-org", response_model=NewOrgCheckoutResponse)
async def billing_checkout_new_org(body: NewOrgCheckoutRequest, user: dict = Depends(get_current_user)):  # noqa: B008
    """#2789: buy a subscription for an organization that does not exist yet.

    SESSION auth (get_current_user), not org auth — the whole point of the
    endpoint is that there is no org yet."""
    name = body.name.strip()
    if not name:
        raise HTTPException(status_code=422, detail="Team name required")
    import re as _re
    # Name rule shared with POST /v1/organizations (spaces allowed; the same charset).
    if not _re.match(r"^[a-zA-Z0-9][a-zA-Z0-9_ -]{0,63}$", name):
        raise HTTPException(status_code=422, detail="Invalid team name")
    return await asyncio.to_thread(_billing_checkout_new_org_sync, user, name, body.price_id)


def _billing_portal_sync(org: dict) -> dict:
    """Sync body of POST /v1/billing/portal — portal session for an existing
    Stripe customer; 404 when the org never checked out (no customer id).

    #4640: the customer binding is read from the SAME store the checkout
    persisted it to. Supabase mode reads the authoritative orgs row through
    the control-plane seam (#669: the registry graph is deleted there — the
    pre-fix registry read missed the row the webhook wrote and 404'd a
    just-subscribed org). Registry mode keeps the Team-node read (selfhost).
    """
    from tortoise.billing import StripeClient
    from tortoise.supabase_control import (
        get_control_plane,
        is_supabase_enabled,
        org_billing_state,
    )
    org_id = org["org_id"]
    if is_supabase_enabled():
        customer_id = org_billing_state(
            get_control_plane(), org_id).get("stripe_customer_id")
    else:
        sdk = _make_sdk(namespace="registry")
        row = sdk._get_registry().query(
            "MATCH (t:Team {id:$id}) RETURN t.stripe_customer_id", params={"id": org_id}
        ).result_set
        customer_id = row[0][0] if row else None
    if not customer_id:
        raise HTTPException(status_code=404, detail="no Stripe customer for this team — start a checkout first")
    try:
        url = StripeClient().create_portal_session(
            customer_id,
            os.environ.get("BILLING_PORTAL_RETURN_URL", _billing_default_portal_return()),
        )
    except Exception as e:
        raise _billing_error_to_http(e) from e
    return {"portal_url": url}


@app.post("/v1/billing/portal", response_model=PortalResponse)
async def billing_portal(request: Request, org: dict = Depends(get_current_org_session)):  # noqa: B008
    """Customer portal for existing subscribers (org auth)."""
    return await asyncio.to_thread(_billing_portal_sync, org)


# #4335: a broken/misconfigured price catalog used to degrade silently — a
# total billing outage looked exactly like a UI preference, and the dashboard
# could only fall back to a marketing link. Emit the failure ONCE per outage at
# WARNING (catalog-load exception class + message, or a parsed catalog that
# resolves no paid tier) and latch the emission so the per-request /v1/team
# call cannot flood the log. A success clears the latch so a NEW breakage after
# a recovery is still reported.
_checkout_catalog_failure_logged = False


def _log_checkout_catalog_failure(exc: Exception) -> None:
    """One visible WARNING per catalog outage (#4335).

    This stays best-effort / non-5xx (registry and selfhost legitimately run
    without Stripe) — but the degradation must be diagnosable. The exception
    message can embed a raw STRIPE_PRICE_IDS value (PriceCatalog validation
    quotes the offending id), so it is scrubbed through the repo's own secret
    scrubber before it reaches the log — the secret value is never emitted.
    """
    global _checkout_catalog_failure_logged
    if _checkout_catalog_failure_logged:
        return
    _checkout_catalog_failure_logged = True
    try:  # the scrubber must never mask the warning it exists to make safe
        from tortoise.billing import _scrub_secrets
        # Composite scrubber — the repo's established billing-log convention
        # (the Stripe-webhook handler's `_safe_log` below): redact_error strips
        # credentials-in-URI / paths and prefixes the exception class,
        # _scrub_secrets redacts Stripe-shaped values. PriceCatalog errors
        # quote the offending STRIPE_PRICE_IDS value, which can be a secret of
        # either shape.
        detail = _scrub_secrets(redact_error(exc))
    except Exception:
        detail = type(exc).__name__
    _logger.warning(
        "checkout price catalog unavailable (%s) — checkout price ids "
        "will be empty until STRIPE_PRICE_IDS is fixed",
        detail,
    )


def _default_checkout_price_id() -> str | None:
    """Server-resolved default checkout price: pro monthly (#310 Task 9).

    The dashboard upgrade CTA uses this so price ids stay env-driven
    (STRIPE_PRICE_IDS) and never leak into the client. Best-effort — None
    when the catalog is unconfigured (missing env → BillingConfigError on
    PriceCatalog() construction; registry/selfhost must not 500 /v1/team).
    """
    global _checkout_catalog_failure_logged
    try:
        from tortoise.billing import PriceCatalog
        catalog = PriceCatalog()
        price = catalog.price_for("pro", "monthly") or None
    except Exception as exc:  # best-effort, never 5xx /v1/team
        _log_checkout_catalog_failure(exc)
        return None
    if price is not None:
        # Only a resolved default proves the catalog is healthy — clearing the
        # latch when pro is merely absent would let the zero-paid-tier warning
        # in _checkout_price_ids() re-fire on every request.
        _checkout_catalog_failure_logged = False
    return price


def _checkout_price_ids() -> dict[str, str]:
    """#1623: tier → monthly price_id for the paid public tiers, server-
    resolved from STRIPE_PRICE_IDS (the Billing page's per-plan Upgrade
    CTAs — never hardcoded in the client). Free/anon ($0) have no checkout.
    Best-effort {} when the catalog is unconfigured. A parsed catalog that
    resolves NO paid tier is a total checkout outage and is reported once
    through the same latch; a legitimately PARTIAL catalog (some paid tiers,
    e.g. solo/team only) is supported by #2789 and stays silent.
    """
    global _checkout_catalog_failure_logged
    try:
        from tortoise.billing import PriceCatalog
        catalog = PriceCatalog()
        ids = {
            tier: pid for tier in ("solo", "pro", "team")
            if (pid := catalog.price_for(tier, "monthly")) is not None
        }
    except Exception as exc:  # best-effort, never 5xx /v1/team
        _log_checkout_catalog_failure(exc)
        return {}
    if not ids:
        # Parsed fine but resolves no paid checkout tier — every paid Upgrade
        # CTA is dead. Report that ONCE (do not clear the latch); a partial
        # catalog keeps ≥1 tier and is not a failure (#2789).
        _log_checkout_catalog_failure(
            LookupError("STRIPE_PRICE_IDS resolved no paid checkout tier (solo/pro/team)"))
        return ids
    _checkout_catalog_failure_logged = False
    return ids



# ── Stripe webhook (#310 Task 7) ────────────────────────────────────────────

def _now_iso() -> str:
    from datetime import datetime
    return datetime.now(UTC).isoformat()


def _org_id_for_stripe_customer(customer_id: str) -> str | None:
    """Org id by stripe_customer_id — control-plane seam (#771 review P1).

    Supabase mode: teams.stripe_customer_id via the service-role seam (the
    webhook is a live registry writer post-#765 — without this branch it
    would silently lose org bindings after the registry delete, or
    recreate the registry graph via an unguarded write). Registry mode:
    Org node lookup (selfhost).
    """
    from tortoise.supabase_control import (
        get_control_plane,
        is_supabase_enabled,
        org_id_for_stripe_customer,
    )
    if is_supabase_enabled():
        try:
            return org_id_for_stripe_customer(get_control_plane(), customer_id)
        except Exception:
            return None
    try:
        sdk = _make_sdk(namespace="registry")
        rows = sdk._get_registry().query(
            "MATCH (t:Team {stripe_customer_id:$cid}) RETURN t.id",
            params={"cid": customer_id},
        ).result_set
        return rows[0][0] if rows else None
    except Exception:
        return None


# #2789: per-org serialization of the paid-new-org provision. Stripe can
# deliver the same (or a racing) event twice concurrently, and the webhook's
# apply runs in a worker thread (asyncio.to_thread) — so this is a threading
# lock, not an asyncio one (contrast _ORG_CREATE_LOCKS, which serializes the
# async create-org lanes). Bounded by the number of paid orgs ever created
# (~100 bytes per entry); uncontended acquisition binds nothing.
_NEW_ORG_PROVISION_LOCKS: dict[str, threading.Lock] = {}
_NEW_ORG_PROVISION_LOCKS_GUARD = threading.Lock()


def _new_org_provision_lock(org_id: str) -> threading.Lock:
    with _NEW_ORG_PROVISION_LOCKS_GUARD:
        lock = _NEW_ORG_PROVISION_LOCKS.get(org_id)
        if lock is None:
            lock = _NEW_ORG_PROVISION_LOCKS.setdefault(org_id, threading.Lock())
        return lock


def _provision_new_org_from_checkout(sdk, org_id: str, meta: dict) -> str:
    """#2789 (design 2): provision the org a completed Checkout paid for.

    Idempotent ON REPLAY, per lane:

    - Supabase: the id was pre-minted at checkout time and echoed back as
      ``client_reference_id``; ``provision_org`` upserts on the primary key,
      and the ``org_by_id`` probe short-circuits a replay entirely (the graph
      init is idempotent too — see ``_eager_provision_org_graph``).
    - Registry (selfhost): ``org_create`` mints its own id, so the pre-minted
      id is passed as ``idempotency_key`` — a replay resolves the SAME org
      (``#1710``) and returns it; no second Org, no second Membership.

    Returns the EFFECTIVE org id, which the caller must use for every
    subsequent billing write (the registry lane's id differs from the
    pre-minted one on first creation).

    Raises on failure so the webhook returns 500 and Stripe retries: a paying
    customer must never be left without an org.
    """
    from tortoise.pricing import tier_limits
    from tortoise.supabase_control import (
        get_control_plane,
        is_supabase_enabled,
        org_by_id,
        provision_org,
    )
    user_id = str(meta.get("user_id") or "")
    org_name = str(meta.get("org_name") or "").strip()
    tier = str(meta.get("tier") or "free")
    if not user_id or not org_name:
        raise RuntimeError(
            "new-org checkout metadata missing user_id/org_name — cannot "
            f"provision (org_id={org_id!r})")
    lim = tier_limits(tier)
    # #1716/#1921 keyless provisioning: no tt_ mint (its plaintext is never
    # returned — a dead credential). The org mints a session key via the normal
    # POST /v1/session/key path.
    keyless = {"p_api_key": None, "p_key_hash": None,
               "p_lookup_hash": None, "p_key_prefix": None}
    with _new_org_provision_lock(org_id):
        if is_supabase_enabled():
            cp = get_control_plane()
            if org_by_id(cp, org_id) is not None:
                return org_id  # replay — the org already exists
            graph_name = _eager_provision_org_graph(cp, org_id, org_name, user_id)
            params = {
                "p_user_id": user_id, "p_identity": None,
                "p_org_id": org_id, "p_org_name": org_name,
                "p_graph_name": graph_name, "p_tier": tier,
                "p_max_users": lim["max_users_per_team"],
                "p_max_graphs": lim["max_graphs_per_team"],
                "p_ops_allowance": lim["included_write_ops_per_month"],
                "p_graph_size_cap": lim["max_graph_nodes"],
                **keyless,
            }
            try:
                provision_org(cp, **params)
            except Exception as e:
                if "HTTP 409" not in str(e):
                    raise
                # A name taken between checkout and payment — the pre-check at
                # checkout time cannot see the future. Deterministic suffix ⇒
                # replay-safe; the org stays fully functional and ops gets a
                # warning (the stale TeamMeta display name is accepted — the
                # org row is the authority).
                params["p_org_name"] = _new_org_collision_name(org_name, org_id)
                _logger.warning(
                    "webhook: org name %r was taken; provisioning as %r (team %s)",
                    org_name, params["p_org_name"], org_id)
                provision_org(cp, **params)
            return org_id

        # Registry (selfhost) lane — sdk is the registry SDK passed by the
        # route (never None in registry mode).
        try:
            result = sdk.org_create(org_name, mint_key=False,
                                     owner_user_id=user_id,
                                     idempotency_key=org_id)
        except Exception as e:
            if "already exists" not in str(e):
                raise
            alt = _new_org_collision_name(org_name, org_id)
            _logger.warning(
                "webhook: org name %r was taken; provisioning as %r (team %s)",
                org_name, alt, org_id)
            result = sdk.org_create(alt, mint_key=False,
                                     owner_user_id=user_id,
                                     idempotency_key=org_id)
        return result["id"]


def _webhook_apply_event(sdk, org_id: str, event: dict) -> tuple[str | None, str]:
    """Apply one verified Stripe event to the control plane (idempotent).

    Supabase mode: PATCH the orgs row via the seam (tier / subscription
    state — 0006 + 0012 columns). Registry mode: SET on the Org node.
    Returns ``(ops kind, effective_org_id)`` — the kind when a
    notification-worthy transition happened:
    billing_upgrade | billing_downgrade | billing_payment_failed |
    billing_cancel.

    #2789: the second element is the org the caller must use for the
    dedup marker / tier read / audit — for a paid-new-org event the org is
    PROVISIONED here, and the registry lane mints its own id, so the
    ``client_reference_id`` the route bound is not always the real one.

    #771 review P1: this is the LAST live registry writer — the webhook
    previously wrote the registry unconditionally (silent billing loss +
    registry-graph resurrection post-delete). Both modes write the same
    fields; only the store differs.
    """
    import json as _json

    from tortoise.billing import (
        PriceCatalog,
        StripeClient,
        _subscription_items,
        apply_limits,
        subscription_period_bounds,
    )
    from tortoise.supabase_control import (
        get_control_plane,
        is_supabase_enabled,
        update_org_billing,
    )

    supabase_mode = is_supabase_enabled()
    etype = event.get("type", "")
    data = event.get("data", {}).get("object", {}) or {}
    notify_kind = None

    def _set(updates: dict) -> None:
        _json.dumps(updates)  # sanity: JSON-safe params
        if supabase_mode:
            update_org_billing(get_control_plane(), org_id, updates)
            return
        sdk._get_registry().query(
            "MATCH (t:Team {id:$id}) SET t += $props",
            params={"id": org_id, "props": updates},
        )

    def _price_id_from(sub: dict) -> str | None:
        """Extract items[0].price.id handling BOTH Stripe shapes: items may be
        a flat list OR {'data': [...]} (FIXTURE_SUB uses the latter).

        EVERY unknown-shape access is guarded so a malformed payload cannot
        raise here — the checkout call site is outside any try, so a raise
        would 500 the route and make Stripe redeliver the same bad event
        forever. Reads ``items`` through ``_subscription_items`` and the
        ``price`` value through an ``isinstance(..., dict)`` check (the sibling
        access in ``billing.subscription_plan`` guards the same shapes) —
        #4216 review.
        """
        rows = _subscription_items(sub)
        if not rows or not isinstance(rows[0], dict):
            return None
        price = rows[0].get("price")
        return price.get("id") if isinstance(price, dict) else None

    def _resolve_tier_from_price(price_id: str | None) -> str | None:
        """price → tier; unknown price → None + ops-notify signal."""
        nonlocal notify_kind
        if not price_id:
            return None
        try:
            return PriceCatalog().tier_for_price(price_id)
        except Exception as e:
            _logger.error(
                "webhook: unknown price %s for team %s (%s)",
                price_id, org_id, redact_error(e))
            notify_kind = "billing_downgrade"  # ops alert; stored tier preserved
            return None

    if etype == "checkout.session.completed":
        # #2789: a paid-new-org session has no org yet — PROVISION it first
        # (before any _set, which PATCHes by id and would silently match 0
        # rows). The org id was pre-minted at checkout time and echoed back as
        # client_reference_id; the registry lane returns its own id, so the
        # effective id is adopted for every later write AND reported back to
        # the caller for the dedup marker / tier read / audit.
        # Guard the nested VALUES read out of ``data`` (``metadata`` /
        # ``customer_details``): a non-dict value would raise AttributeError at
        # ``.get(...)``, before any try, and the route's handler would 500 →
        # Stripe redelivers the same bad event forever — the class this PR
        # hardens for ``items``/``price``.
        meta = data.get("metadata")
        meta = meta if isinstance(meta, dict) else {}
        is_new_org = str(meta.get("new_org") or "") == "1"
        if is_new_org:
            # Sync call: _webhook_apply_event itself already runs in a worker
            # thread (asyncio.to_thread in the route), so the provision —
            # blocking control-plane + graph writes — stays on that thread.
            org_id = _provision_new_org_from_checkout(sdk, org_id, meta)
        cust = data.get("customer")
        customer_details = data.get("customer_details")
        customer_details = (
            customer_details if isinstance(customer_details, dict) else {})
        email = customer_details.get("email")
        sub_id = data.get("subscription")
        updates = {"subscription_status": "active", "stripe_customer_id": cust}
        if email:
            updates["customer_email"] = email
        if sub_id:
            updates["subscription_id"] = sub_id
        _set(updates)
        resolved_tier = None
        window_error = None
        if sub_id:
            try:
                sub = StripeClient().get_subscription(sub_id)
            except Exception as e:
                sub = None
                _logger.warning("webhook: subscription fetch failed: %s", redact_error(e))
            if sub is not None:
                # #4216: checkout is an AUTHORING path for the subscription —
                # it must persist the METER WINDOW ANCHOR, not only
                # ``subscription_id``. ``metering._current_period`` needs a
                # COMPLETE half-open interval
                # ``[current_period_start, current_period_end)``; without it a
                # just-checked-out PAYING org is permanently
                # window-unresolvable — its increments are dropped and the cohort
                # cost cap cannot be enforced for it (absorbed + alerted per
                # #3981, but unenforceable, which is the defect this issue
                # removes). Both bounds come from the SAME authoritative Stripe
                # subscription object the tier is resolved from. Only the bounds
                # the payload CARRIES are written; a bound it omits is left
                # alone (never NULLed).
                #
                # FAILURE ORDER (#4216 review): a window-write failure must not
                # SUPPRESS the tier upgrade (a taken payment must not sit on
                # free limits, #2789) — but it must also not be SWALLOWED as a
                # 200, or the org stays window-unresolvable until the next
                # renewal webhook, which for a checkout-only org may never
                # arrive. So record the failure and carry on: the tier is
                # applied, the new-org metadata fallback below still runs, and
                # the failure is re-raised at the END of this branch. The route
                # then 500s, Stripe redelivers, and every write is idempotent,
                # so the window write is retried.
                #
                # NOTE (#4216 review): a failure of ``apply_limits`` /
                # ``_set({"tier": ...})`` now PROPAGATES (the route 500s and
                # Stripe redelivers) instead of being swallowed as a
                # "subscription fetch failed" 200 — deliberate and consistent
                # with #2789: a taken payment must never sit unretried on free
                # limits. The previous outer except covered the whole block.
                period_start, period_end = subscription_period_bounds(sub)
                window = {k: v for k, v in (
                    ("current_period_start", period_start),
                    ("current_period_end", period_end),
                ) if v}
                window_error = None
                if window:
                    try:
                        _set(window)
                    except Exception as e:
                        window_error = e
                        _logger.warning(
                            "webhook: period window write failed: %s",
                            redact_error(e))
                tier = _resolve_tier_from_price(_price_id_from(sub))
                if tier:
                    apply_limits(sdk, org_id, tier)
                    _set({"tier": tier})
                    notify_kind = "billing_upgrade"
                    resolved_tier = tier
        if is_new_org and resolved_tier is None:
            # The metadata tier was server-resolved from the price at checkout
            # time and provision_org already wrote the matching quotas, so a
            # failed/slow subscription fetch must not leave a PAYING customer
            # on free limits.
            meta_tier = str(meta.get("tier") or "")
            if meta_tier and meta_tier not in ("free", "anon"):
                apply_limits(sdk, org_id, meta_tier)
                _set({"tier": meta_tier})
                notify_kind = "billing_upgrade"
                _logger.warning(
                    "webhook: new org %s fell back to metadata tier %s "
                    "(subscription tier unresolved)", org_id, meta_tier)
            else:
                # #2789 (code-review): RAISE, do not ack. The money was taken
                # and the org now exists on whatever tier `_provision_new_org_
                # from_checkout` defaulted to (free) — a 200 here would tell
                # Stripe "processed" and nothing would ever retry, so a paying
                # customer would sit on free limits with no self-healing. A 500
                # makes Stripe redeliver (and the ops log records the session)
                # so the tier can be applied once the cause is fixed.
                raise RuntimeError(
                    f"new-org checkout for team {org_id} has no resolvable "
                    f"paid tier (metadata tier={meta_tier!r}, subscription "
                    "tier unresolved) — refusing to ack")
        if window_error is not None:
            # The tier upgrade (or the #2789 metadata fallback) above has been
            # applied — every write is idempotent — so surface the window
            # failure LAST: the route 500s and Stripe redelivers, retrying the
            # window write, instead of acking an org left unmeterable.
            raise window_error
        return notify_kind, org_id

    if etype == "invoice.payment_failed":
        from datetime import datetime, timedelta
        period_end = None
        try:
            period_end = (data.get("lines") or {}).get("data", [{}])[0] \
                .get("period", {}).get("end")
        except Exception:
            period_end = None
        now = datetime.now(UTC)
        grace = (datetime.fromtimestamp(period_end, tz=UTC) + timedelta(hours=72)
                 if period_end else now + timedelta(hours=72))
        _set({"subscription_status": "past_due", "grace_until": grace.isoformat()})
        return "billing_payment_failed", org_id

    if etype == "customer.subscription.updated":
        status = data.get("status")
        updates: dict = {}
        if data.get("id"):
            updates["subscription_id"] = data["id"]
        # #4216: read the period through the top-level-then-item helper — a
        # Basil-or-later Stripe account carries the bounds on the subscription
        # ITEMS, and reading only the top level would drop the anchor entirely.
        period_start, period_end = subscription_period_bounds(data)
        if period_end:
            updates["current_period_end"] = period_end
        # #3825 / D10: the METER WINDOW ANCHOR. The cost meter totals usage
        # over the subscription's OWN billing period so it reconciles with the
        # invoice line, and only the period END was persisted — leaving the
        # window half-known, which ``metering._current_period`` refuses to
        # guess at (a derived start is wrong for annual plans and plan
        # changes, and a calendar-month fallback would put a paying org's
        # spend on a row the cap's window read never looks at). This event
        # carries the authoritative start next to the end already written here.
        if period_start:
            updates["current_period_start"] = period_start
        if status:
            updates["subscription_status"] = status
        # review fix 11: canceled surfacing via .updated (deleted event may be
        # dropped) → revert to free, identical to subscription.deleted.
        if status == "canceled":
            _set({**updates, "tier": "free"})
            apply_limits(sdk, org_id, "free")
            return "billing_cancel", org_id
        # cancel_at_period_end → keep tier until period end (mirror status only).
        if data.get("cancel_at_period_end"):
            _set(updates)
            return None, org_id
        _set(updates)
        tier = _resolve_tier_from_price(_price_id_from(data))
        if tier:
            apply_limits(sdk, org_id, tier)
            _set({"tier": tier})
            notify_kind = "billing_upgrade"
        return notify_kind, org_id

    if etype == "customer.subscription.deleted":
        _set({"tier": "free", "subscription_status": "canceled"})
        apply_limits(sdk, org_id, "free")
        return "billing_cancel", org_id

    return None, org_id  # unhandled event type → 200-ack


@app.post("/webhooks/stripe")
async def webhooks_stripe(request: Request):
    """Stripe webhook — signature-verified, event-ID dedup, 4-event semantics.

    Public surface (SKIP + SKIP_AUTH): authenticity is the Stripe-Signature
    HMAC over the RAW body. Idempotency is SET-then-marker: the Org SET is
    idempotent (replays converge), and the :WebhookEvent marker gates
    notify/audit/analytics to FIRST processing only (scoping P1-1 retry-drop
    race: the SET happens regardless, so a retry can never drop an upgrade).
    """
    from tortoise.billing import BillingConfigError, BillingError, StripeClient, _scrub_secrets
    from tortoise.notify import notify_billing_event


    def _safe_log(exc: Exception) -> str:
        """redact_error + scrub known secret values (review fix 9)."""
        return _scrub_secrets(redact_error(exc))

    raw = await _read_capped_body(
        request, _STRIPE_WEBHOOK_MAX_BYTES, _STRIPE_WEBHOOK_413_DETAIL)
    sig = request.headers.get("stripe-signature")
    try:
        event = StripeClient().verify_webhook_signature(raw, sig)
    except BillingConfigError:
        return JSONResponse(status_code=500, content={"detail": "webhook not configured"})
    except BillingError as e:
        _logger.warning("webhook: rejected (%s)", _safe_log(e))
        return JSONResponse(status_code=400, content={"detail": "invalid signature"})

    etype = event.get("type", "")
    event_id = event.get("id") or ""
    data = event.get("data", {}).get("object", {}) or {}
    org_id = data.get("client_reference_id")
    if not org_id and etype in ("customer.subscription.updated", "customer.subscription.deleted",
                                 "invoice.payment_failed"):
        cust = data.get("customer")
        if cust:
            org_id = _org_id_for_stripe_customer(cust)
    if not org_id:
        # No org binding — ack so Stripe stops retrying.
        return JSONResponse(status_code=200, content={"detail": "no team binding"})

    # Lazy registry SDK — ONLY for the registry (selfhost) path. In Supabase
    # mode the apply + marker + tier read go through the seam and this SDK is
    # never constructed (a registry-namespaced SDK would be a write vector
    # post-delete; re-review P1, PR #878).
    from tortoise.supabase_control import is_supabase_enabled as _sb_enabled
    sdk = None if _sb_enabled() else _make_sdk(namespace="registry")

    try:
        # Idempotent apply (SETs converge on replay). The apply itself is
        # seam-aware (#771 re-review P1: _webhook_apply_event's _set branches
        # to the orgs row in Supabase mode; the registry twin for selfhost).
        # #2789: it also returns the EFFECTIVE org id — a paid-new-org event
        # provisions the org during the apply, and the registry lane mints its
        # own id, so the marker/tier/audit below must use the returned id.
        notify_kind, org_id = await asyncio.to_thread(
            _webhook_apply_event, sdk, org_id, event)

        # Marker: first-seen detection (SET-then-marker — the apply ran
        # regardless, so a retry cannot drop the upgrade; only side-effects
        # are dedup'd). Supabase mode: webhook_events table (0013) via the
        # seam — the registry WebhookEvent write would RESURRECT the deleted
        # registry graph (re-review P1, PR #878). Registry mode: WebhookEvent
        # node, as before.
        from tortoise.supabase_control import (
            get_control_plane,
            is_supabase_enabled,
            org_tier,
            webhook_event_marker,
        )
        # #4015: the tier is a READ, so it is taken BEFORE the claim in both
        # branches. The claim is what makes every ``is_first``-gated side
        # effect fire AT MOST ONCE — a retry after a claim sees
        # ``is_first=False`` forever — so an abort between the claim and the
        # notification (a tier-read failure included) drops the notification
        # PERMANENTLY. Read first: a failure leaves the event unclaimed and
        # Stripe's retry reprocesses it.
        if is_supabase_enabled():
            cp = get_control_plane()
            tier = org_tier(cp, org_id)
            is_first = webhook_event_marker(cp, event_id, etype)
        else:
            tier_rows = sdk._get_registry().query(
                "MATCH (t:Team {id:$id}) RETURN t.tier", params={"id": org_id}
            ).result_set
            tier = tier_rows[0][0] if tier_rows else None
            seen_rows = sdk._get_registry().query(
                "MATCH (w:WebhookEvent {event_id:$id}) RETURN w.first_seen",
                params={"id": event_id},
            ).result_set
            is_first = not seen_rows
            if is_first:
                sdk._get_registry().query(
                    "CREATE (w:WebhookEvent {event_id:$id, first_seen:$now, type:$type})",
                    params={"id": event_id, "now": _now_iso(), "type": etype},
                )
        if is_first and notify_kind:
            # #4015: the billing NOTIFICATION is the first side effect after
            # the claim, because it is the unrecoverable one: once claimed, a
            # re-delivery can never re-fire it, and everything downstream of
            # this line is best-effort. ``notify_billing_event`` is documented
            # never-raise (tortoise/notify.py), so it cannot abort itself; the
            # audit and telemetry legs — either of which could otherwise 500
            # the webhook AND strand the notification — follow it. (#4352 had
            # already moved the analytics POST behind ``_cp_offload``; what
            # this change adds here is the notify-first order and the guards.)
            notify_billing_event(
                notify_kind, {"org_id": org_id, "tier": tier},
                {"subscription_status": etype},
            )
            try:
                await _async_audit(
                    request, org_id, notify_kind,
                    resource_type="team", resource_id=org_id,
                )
            except Exception as exc:  # noqa: BLE001, RUF100 — never 500 a webhook
                _logger.warning("webhook: audit failed (non-fatal): %s",
                                _safe_log(exc))
            # The emit's own FAIL-SOFT guard, on top of the offload's
            # best-effort contract: ``_emit_analytics_off_loop`` still
            # re-raises the #3821 strict-mode registration guard (dev/CI only)
            # because the onboarding lane relies on that escape, and a raise
            # here would 500 a delivery whose notification is already spent.
            try:
                await _emit_analytics_off_loop(org_id, notify_kind, {
                    "plan": tier, "tier": tier, "status": etype,
                })
            except Exception as exc:  # noqa: BLE001, RUF100 — never 500 a webhook
                _logger.warning(
                    "webhook: analytics emit failed (non-fatal): %s",
                    _safe_log(exc))
        return JSONResponse(status_code=200, content={"detail": "processed"})
    except Exception as e:
        _logger.error("webhook: processing failed (%s)", _safe_log(e))
        return JSONResponse(status_code=500, content={"detail": "processing failed"})


# ── OAuth 2.1 for remote MCP (#524) ─────────────────────────────────────
# Authorization-code + PKCE server with DCR + RFC 8707 resource indicators,
# Supabase-auth-backed (D2). Locked decisions in
# docs/scoping/2026-08-15-524-oauth-mcp-scoping.md; protocol logic lives in
# tortoise/oauth.py (control-plane seam, OAuthError → RFC 6749 error JSON).
# D3: MCP-only — REST /v1/* keeps tt_ + session-JWT; tt_ stays the permanent
# documented fallback. Selfhost/registry mode: functional endpoints fail
# closed 503 (OAuth is hosted-only); the well-known metadata endpoints still
# serve (they describe the hosted AS; harmless static JSON).

# ── DCR capacity policy (#2866) ────────────────────────────────────────
# RFC 7591 registration is an unauthenticated write surface. The limiter is
# intentionally NOT the shared `_check_ip_bucket_rate_limit` primitive: that
# primitive inserts the bucket (`defaultdict`) BEFORE its 429 check and prunes
# only *stale* buckets, so an attacker-keyed fresh-key flood grows its store
# without bound and every request scans the whole store once over
# `max_entries` (the charge append itself happens after the check; the
# unbounded growth and the O(n) scan are the defects). The primitive is left
# byte-identical; the sibling filing tracks it). This limiter states its
# capacity policy in concrete, falsifiable numbers:
#
#   per bucket (per client IP, or /64 for IPv6) ... 20/hr   (PER_HOUR)
#   anonymous global aggregate ................... 600/hr   (ANON_AGGREGATE)
#   trusted-CIDR aggregate ....................... 1200/hr  (TRUSTED_PER_HOUR)
#   live-bucket store cap ........................ 256      (STORE_CAP)
#   window ....................................... 3600 s
#
# Dimension membership: *trusted ⇒ per-CIDR aggregate only* (no per-key
# bucket, no shared overflow, no anonymous aggregate) and *anonymous ⇒
# per-key bucket (or shared overflow) AND the anonymous global aggregate*.
# The trusted carve-out is evaluated BEFORE any per-key/overflow path, so the
# exemption is reachable under an anonymous flood — otherwise a first-time
# trusted IP is a "new key" and would be denied once STORE_CAP buckets are
# live. STORE_CAP (256) < ANON_AGGREGATE (600) keeps the reject-new/overflow
# branch live at shipped defaults.
#
# Bounded store, deterministic eviction (#2866 D3/D4): a bucket is *active*
# iff it holds an in-window entry. Store order is last-charge (charged hits
# `move_to_end`); reclaim therefore stops at the first active head, because
# every later key was charged no earlier than the head. Reclaim runs ONLY on
# the new-key-at-cap path, so a tracked key's charge stays O(1) and the store
# can never evict an active key. If the cap is still full, the new key is
# denied its own bucket and charged to one shared overflow bucket (bounded by
# the derived overflow cap = PER_HOUR) AND the anonymous aggregate (D9).
#
# Derived ceiling: the distinct-new-anonymous-key rate is bounded by
# STORE_CAP + PER_HOUR = 276/hr (256 live keys + 20 overflow charges) — a
# burst/concurrent-live bound, not a bound tested at shipped scale.
#
# IPv6: the store key is the /IPV6_PREFIX network (default /64) of the
# normalized address, so a single client cannot mint 2**64 buckets; a
# malformed address keys as the single constant "anonymous" (never the raw
# string, so a malformed-identity flood cannot occupy STORE_CAP buckets).
# Out-of-range prefix falls back to 64 (clamping 0 -> 1 would collapse every
# IPv6 address into one bucket). Malformed IP/CIDR never raise; a missing
# client early-returns like the shared primitive.
#
# Accepted limitations (PR body carries the full list): in-process stores ⇒
# real capacity is limit × machines and resets on restart (#1677 / #2853 own
# oauth_clients row pruning — owner @daniel-ospina, date 2026-10-15); the
# limiter runs before body parsing, so invalid-JSON / oversized POSTs DO
# consume budget; the anonymous aggregate is a one-source DoS (trusted CIDRs
# unaffected); the exemption's security rests on the Fly edge stripping
# client `Fly-*` headers (assumption 12 — dated re-verification with an
# operator recipe is #3126, owner @daniel-ospina, 2026-11-15). Sibling
# filings from this work: #3124 (the shared per-IP primitive + the generic
# middleware's store are still unbounded), #3125 (`_check_claim_rate_limit`
# keys on the proxy IP), #3128 (authorize/consent forward an unvalidated
# scope into the minted token), #3134 (dated measurement of real DCR volume —
# the 600/1200 aggregates are not load-validated). #3036 already covers
# oauth_* token-table retention/GC.
#
# CHARGING DOCTRINE DIVERGENCE (tracked, #1719 / #2051): this limiter charges
# at CHECK time, like `_check_ip_bucket_rate_limit` without `defer_charge`,
# not at the TERMINAL outcome the way #1719's `defer_charge=True` callers do.
# Consequence: a control-plane 5xx from `register_client` still consumed the
# caller's budget, so a post-recovery retry can meet a spurious 429 that masks
# the underlying failure. That is the #2051 failure class, and #2051 does not
# currently list DCR. Documented here rather than silently mirrored, per the
# #2038 precedent (PR #2049 review) — see also the docs limitation in
# docs/oauth-mcp.md. The phase-1/phase-2 seam already exists, so moving the
# charge past `register_client` is the follow-up if #2051 is taken up.
_OAUTH_DCR_WINDOW_S = 3600
_OAUTH_DCR_PER_HOUR_DEFAULT = 20
_OAUTH_DCR_ANON_AGGREGATE_PER_HOUR_DEFAULT = 600
_OAUTH_DCR_TRUSTED_PER_HOUR_DEFAULT = 1200
_OAUTH_DCR_STORE_CAP_DEFAULT = 256
_OAUTH_DCR_IPV6_PREFIX_DEFAULT = 64
# Anthropic's published outbound/MCP egress range
# (platform.claude.com/docs/en/api/ip-addresses; whois AP-2440). Comma-
# separated; an EMPTY value means an empty trusted set (the documented lever
# to disable the exemption) — never the default.
_OAUTH_DCR_TRUSTED_CIDRS_DEFAULT = "160.79.104.0/21"
# Singleton store keys for the aggregate dimensions (malformed client IPs
# share the constant below, never a per-raw-string bucket).
_OAUTH_DCR_ANON_KEY = "\x00anon"
_OAUTH_DCR_OVERFLOW_KEY = "\x00overflow"
_OAUTH_DCR_MALFORMED_KEY = "anonymous"

_OAUTH_DCR_BUCKETS: OrderedDict[str, list[float]] = OrderedDict()
_OAUTH_DCR_TRUSTED: OrderedDict[str, list[float]] = OrderedDict()
_OAUTH_DCR_OVERFLOW: OrderedDict[str, list[float]] = OrderedDict()
_OAUTH_DCR_ANON: OrderedDict[str, list[float]] = OrderedDict()
_OAUTH_DCR_LOCK = asyncio.Lock()


def _dcr_prune_window(bucket: list[float], now: float, window_s: int) -> list[float]:
    """In-window entries of `bucket` (pure; the primitive's window contract is
    pinned against this by a parity test, D10)."""
    return [t for t in bucket if now - t < window_s]


def _dcr_retry_after_s(bucket: list[float], now: float, window_s: int) -> int:
    """Seconds until the oldest in-window charge expires (ceil — the caller
    guards against an empty bucket; int() would understate, see #1081 P4)."""
    return math.ceil(bucket[0] + window_s - now)


def _oauth_dcr_trusted_networks() -> list:
    """Parse TORTOISE_OAUTH_DCR_TRUSTED_CIDRS AT CALL TIME (no cache — no
    staleness foot-gun). Whitespace-trimmed, empty items skipped, a malformed
    item skipped without aborting the list. Unset ⇒ default; empty ⇒ empty
    set (fail closed — the disable lever); never `or DEFAULT` falsy-coalescing."""
    raw = os.environ.get("TORTOISE_OAUTH_DCR_TRUSTED_CIDRS")
    if raw is None:
        raw = _OAUTH_DCR_TRUSTED_CIDRS_DEFAULT
    nets: list = []
    for item in raw.split(","):
        item = item.strip()
        if not item:
            continue
        try:
            nets.append(ipaddress.ip_network(item, strict=False))
        except ValueError:
            continue
    return nets


def _oauth_dcr_normalized_addr(client_ip):
    """`ipaddress` address for `client_ip`, normalizing ANY IPv4-mapped IPv6
    spelling (or None for a malformed address).

    `_normalize_mapped_ipv6` (shared primitive helper, byte-identical to
    origin/main) matches the literal lowercase ``::ffff:`` prefix, so the
    structural check here additionally covers ``::FFFF:1.2.3.4`` and
    ``0:0:0:0:0:ffff:1.2.3.4``. Without it one IPv4 address could hold two
    bucket identities (its own plus the shared ``::/64``) and a non-canonical
    mapped client would collapse into ``::/64`` instead of being keyed — or
    trusted — as the address it actually is.
    """
    ip = _normalize_mapped_ipv6(client_ip)
    if not isinstance(ip, str):
        return None
    try:
        addr = ipaddress.ip_address(ip)
    except ValueError:
        return None
    if isinstance(addr, ipaddress.IPv6Address) and addr.ipv4_mapped is not None:
        return addr.ipv4_mapped
    return addr


def _oauth_dcr_trusted_net(client_ip) -> object | None:
    """The trusted network containing `client_ip`, else None. Matches on the
    NORMALIZED address (so every spelling of an IPv4-mapped trusted address is
    trusted) and fails closed on a malformed address/CIDR."""
    addr = _oauth_dcr_normalized_addr(client_ip)
    if addr is None:
        return None
    for net in _oauth_dcr_trusted_networks():
        try:
            if addr.version == net.version and addr in net:
                return net
        except TypeError:  # version mismatch — not trusted
            continue
    return None


def _oauth_dcr_store_key(client_ip) -> str:
    """Per-bucket store key: the /IPV6_PREFIX network for IPv6 (default /64),
    the plain address for IPv4, the constant "anonymous" for a malformed
    address (D6)."""
    addr = _oauth_dcr_normalized_addr(client_ip)
    if addr is None:
        return _OAUTH_DCR_MALFORMED_KEY
    if addr.version != 6:
        return str(addr)
    prefix = _int_env("TORTOISE_OAUTH_DCR_IPV6_PREFIX",
                      _OAUTH_DCR_IPV6_PREFIX_DEFAULT)
    if not 1 <= prefix <= 128:
        prefix = _OAUTH_DCR_IPV6_PREFIX_DEFAULT
    return str(ipaddress.ip_network(f"{addr}/{prefix}", strict=False))


def _oauth_dcr_reclaim(store: OrderedDict, now: float, window_s: int,
                       cap: int) -> None:
    """Pop inactive LRU-head buckets until the store is below `cap` or the
    head is active (D3/D4). By the last-charge ordering invariant an active
    head implies every later key is active too, so this stops at the first
    live bucket — it can never evict an active key. O(1) at the hot cap."""
    while store and len(store) >= cap:
        head_key = next(iter(store))
        head = store[head_key]
        if head and now - head[-1] < window_s:
            break
        del store[head_key]


def _oauth_dcr_deny(retry_after: int) -> None:
    raise HTTPException(
        status_code=429,
        detail=("Too many client registrations from this IP. "
                "Please try again later."),
        headers={"Retry-After": str(max(1, retry_after))},
    )


async def _check_oauth_dcr_rate_limit(request: Request) -> None:
    """DCR capacity limiter — policy block above (#2866).

    Reads every knob AT CALL TIME (testability; no import-time freeze) and
    the four stores dynamically off the module globals (the test fixture
    swaps them). Atomic across dimensions (D5): phase 1 evaluates all
    dimensions — it may evict INACTIVE buckets, but never charges or
    inserts — and phase 2 charges only if every dimension passed, so a 429
    charges nothing and inserts nothing. Does NOT call `_charge_ip_bucket`
    (it re-takes `_OAUTH_DCR_LOCK`; asyncio.Lock is non-reentrant).
    """
    if os.environ.get("RATE_LIMIT_DISABLED") == "1":
        return
    client = getattr(request.state, "client_ip", None)
    if not client:
        client = request.client.host if request.client else None
    if not client:
        return

    now = time.time()
    window_s = _OAUTH_DCR_WINDOW_S
    per_hour = _int_env("TORTOISE_OAUTH_DCR_PER_HOUR",
                        _OAUTH_DCR_PER_HOUR_DEFAULT)
    anon_cap = _int_env("TORTOISE_OAUTH_DCR_ANON_AGGREGATE_PER_HOUR",
                        _OAUTH_DCR_ANON_AGGREGATE_PER_HOUR_DEFAULT)
    trusted_cap = _int_env("TORTOISE_OAUTH_DCR_TRUSTED_PER_HOUR",
                           _OAUTH_DCR_TRUSTED_PER_HOUR_DEFAULT)
    store_cap = _int_env("TORTOISE_OAUTH_DCR_STORE_CAP",
                         _OAUTH_DCR_STORE_CAP_DEFAULT)

    async with _OAUTH_DCR_LOCK:
        # ── trusted carve-out (D2) — evaluated FIRST, before any per-key or
        # overflow path so a first-time trusted IP can never be denied. ──
        net = _oauth_dcr_trusted_net(client)
        if net is not None:
            tkey = str(net)
            tcbucket = _OAUTH_DCR_TRUSTED.get(tkey)
            if tcbucket is None:
                tcbucket = []
            else:
                tcbucket[:] = _dcr_prune_window(tcbucket, now, window_s)
            if trusted_cap <= 0:  # zero rule — deny, never index empty
                _oauth_dcr_deny(window_s)
            if len(tcbucket) >= trusted_cap:
                _oauth_dcr_deny(_dcr_retry_after_s(tcbucket, now, window_s))
            tcbucket.append(now)
            _OAUTH_DCR_TRUSTED[tkey] = tcbucket
            _OAUTH_DCR_TRUSTED.move_to_end(tkey)
            return

        # ── phase 1: evaluate every anonymous dimension (no charge/insert) ──
        key = _oauth_dcr_store_key(client)
        bucket = _OAUTH_DCR_BUCKETS.get(key)
        on_overflow = False
        if bucket is None:
            _oauth_dcr_reclaim(_OAUTH_DCR_BUCKETS, now, window_s, store_cap)
            if len(_OAUTH_DCR_BUCKETS) >= store_cap:
                on_overflow = True  # cap full — no bucket of its own
            else:
                bucket = []  # inserted in phase 2 only
        else:
            bucket[:] = _dcr_prune_window(bucket, now, window_s)

        overflow_bucket = None
        if on_overflow:
            overflow_bucket = _OAUTH_DCR_OVERFLOW.get(_OAUTH_DCR_OVERFLOW_KEY)
            if overflow_bucket is None:
                overflow_bucket = []
            else:
                overflow_bucket[:] = _dcr_prune_window(
                    overflow_bucket, now, window_s)
            if per_hour <= 0:
                _oauth_dcr_deny(window_s)
            if len(overflow_bucket) >= per_hour:  # derived cap = PER_HOUR
                _oauth_dcr_deny(_dcr_retry_after_s(overflow_bucket, now,
                                                   window_s))
        else:
            if per_hour <= 0:
                _oauth_dcr_deny(window_s)
            if len(bucket) >= per_hour:
                _oauth_dcr_deny(_dcr_retry_after_s(bucket, now, window_s))

        # D9: the anonymous aggregate covers per-key AND overflow charges —
        # otherwise the stated "anonymous <= ANON_AGGREGATE/hr" bound is
        # asserted but not enforced.
        anon_bucket = _OAUTH_DCR_ANON.get(_OAUTH_DCR_ANON_KEY)
        if anon_bucket is None:
            anon_bucket = []
        else:
            anon_bucket[:] = _dcr_prune_window(anon_bucket, now, window_s)
        if anon_cap <= 0:
            _oauth_dcr_deny(window_s)
        if len(anon_bucket) >= anon_cap:
            _oauth_dcr_deny(_dcr_retry_after_s(anon_bucket, now, window_s))

        # ── phase 2: every dimension passed — insert + charge ──
        if on_overflow:
            overflow_bucket.append(now)
            _OAUTH_DCR_OVERFLOW[_OAUTH_DCR_OVERFLOW_KEY] = overflow_bucket
            _OAUTH_DCR_OVERFLOW.move_to_end(_OAUTH_DCR_OVERFLOW_KEY)
        else:
            bucket.append(now)
            _OAUTH_DCR_BUCKETS[key] = bucket
            _OAUTH_DCR_BUCKETS.move_to_end(key)
        anon_bucket.append(now)
        _OAUTH_DCR_ANON[_OAUTH_DCR_ANON_KEY] = anon_bucket
        _OAUTH_DCR_ANON.move_to_end(_OAUTH_DCR_ANON_KEY)


def _oauth_control_plane() -> tuple:
    """(cp, is_enabled) — fail-closed: OAuth functions 503 in registry mode."""
    from tortoise.supabase_control import get_control_plane, is_supabase_enabled
    enabled = is_supabase_enabled()
    cp = get_control_plane() if enabled else None
    return cp, enabled


def _oauth_base(request: Request) -> str:
    """Origin for RFC 8707 resource URIs (request.base_url in tests resolves
    to http://testserver — production is https://api.premiselabs.co)."""
    return str(request.base_url).rstrip("/")


def _oauth_error_response(exc: OAuthError) -> JSONResponse:  # noqa: F821
    return JSONResponse(status_code=exc.status, content=exc.body())


@app.get("/.well-known/oauth-protected-resource")
@app.get("/.well-known/oauth-protected-resource/mcp")
async def oauth_protected_resource(request: Request):
    """RFC 9728 Protected Resource Metadata (P1).

    Served at both the root and path-based well-known URI (the MCP SDK tries
    ``/.well-known/oauth-protected-resource/mcp`` first, then the root form).
    """
    from tortoise.oauth import protected_resource_metadata
    return protected_resource_metadata(_oauth_base(request))


@app.get("/.well-known/oauth-authorization-server")
@app.get("/.well-known/oauth-authorization-server/mcp")
async def oauth_authorization_server_metadata(request: Request):
    """RFC 8414 Authorization Server Metadata (P1)."""
    from tortoise.oauth import authorization_server_metadata
    return authorization_server_metadata(_oauth_base(request))


@app.get("/oauth/authorize")
async def oauth_authorize(request: Request):
    """Authorization endpoint (P2) — validates the request and renders the
    branded consent page (D2; the single custom HTML page reusing the
    signup/signin pattern). The browser signs in via supabase-js, then posts
    the session JWT to /oauth/consent which mints the auth code.
    """
    from tortoise.oauth import (
        OAuthError,
        consent_page_html,
        validate_authorize_params,
    )
    cp, enabled = _oauth_control_plane()
    if not enabled or cp is None:
        raise HTTPException(status_code=503, detail="OAuth not configured")
    params = {
        "client_id": request.query_params.get("client_id", ""),
        "redirect_uri": request.query_params.get("redirect_uri", ""),
        "response_type": request.query_params.get("response_type", ""),
        "code_challenge": request.query_params.get("code_challenge", ""),
        "code_challenge_method": request.query_params.get("code_challenge_method", "S256"),
        "state": request.query_params.get("state", ""),
        "scope": request.query_params.get("scope", ""),
        "resource": request.query_params.get("resource", ""),
    }
    try:
        client = await _oauth_offload(
            lambda: validate_authorize_params(
                cp, client_id=params["client_id"],
                redirect_uri=params["redirect_uri"] or None,
                response_type=params["response_type"] or None,
                code_challenge=params["code_challenge"] or None,
                code_challenge_method=params["code_challenge_method"] or None),
            op="oauth_authorize_params")
    except OAuthError as exc:
        # Invalid authorize params → RFC 6749 §4.1.2.1 error to the browser.
        # Open-redirect guard: only redirect when the redirect_uri is
        # REGISTERED for the client — never echo an unvalidated param.
        #
        # #2846 review P2: this must use the SAME matcher as validation, or a
        # native client that registered a PORTLESS loopback URI never receives
        # the error on its ephemeral listener — the strict membership test
        # fails, so we return JSON where the client is waiting for a redirect.
        # Using the relaxed matcher here is safe ONLY because
        # `_redirect_uri_matches` also refuses parse-differential input: this is
        # the one place the raw request param is echoed into a Location header,
        # so relaxing the match without that guard would BE the open redirect.
        #
        # #3669 finding 2: `validate_authorize_params` STAMPS the client it
        # resolved (None when unresolved) on the raised OAuthError, so this
        # handler never re-resolves. Re-resolving here cost a SECOND CIMD
        # fetch and a second rate-limit charge on the FAILURE path (the success
        # path paid nothing — the cache absorbed it), halving the effective
        # failure budget.
        from tortoise.oauth import _redirect_uri_matches
        client = getattr(exc, "client", None)
        registered_uris = (client.get("redirect_uris") or []) if client else []
        if not isinstance(registered_uris, (list, tuple)):
            registered_uris = [registered_uris]
        if (params["redirect_uri"] and client is not None
                and any(_redirect_uri_matches(u, params["redirect_uri"])
                        for u in registered_uris)):
            from urllib.parse import urlencode
            sep = "&" if "?" in params["redirect_uri"] else "?"
            return RedirectResponse(
                params["redirect_uri"] + sep + urlencode(
                    {"error": exc.error, "state": params["state"]}))
        return _oauth_error_response(exc)
    html, nonce = consent_page_html(
        client_name=client.get("client_name") or client["id"],
        scope=params["scope"] or client.get("scope") or "mcp",
        params=params,
        supabase_url=os.environ.get("SUPABASE_URL", ""),
        supabase_anon_key=os.environ.get("SUPABASE_ANON_KEY", ""),
    )
    # CSP (PR #1264 review P1): script-src is nonce-gated so the inline
    # consent logic runs while a payload that somehow escapes the JSON
    # embedding still cannot execute; connect-src allows the supabase-js
    # REST calls; frame-ancestors blocks clickjacking.
    from urllib.parse import urlparse
    supabase_origin = ""
    _u = urlparse(os.environ.get("SUPABASE_URL", ""))
    if _u.scheme and _u.netloc:
        supabase_origin = f"{_u.scheme}://{_u.netloc}"
    csp = (
        "default-src 'none'; "
        f"script-src 'nonce-{nonce}' https://cdn.jsdelivr.net; "
        "style-src 'unsafe-inline'; "
        "img-src 'self' data:; "
        f"connect-src 'self' {supabase_origin}; "
        "base-uri 'none'; frame-ancestors 'none'; form-action 'self'"
    )
    return Response(html, media_type="text/html",
                    headers={"Content-Security-Policy": csp})


@app.get("/oauth/consent/preview")
async def oauth_consent_preview(request: Request):
    """Consent-page org preview (D4): which org a grant would bind, given
    the session JWT + client-declared resource indicator. No state change.
    """
    from tortoise.oauth import OAuthError, consent_preview
    cp, enabled = _oauth_control_plane()
    if not enabled or cp is None:
        raise HTTPException(status_code=503, detail="OAuth not configured")
    user = await verify_session_jwt(request)
    try:
        return consent_preview(cp, user["user_id"], _oauth_base(request),
                               request.query_params.get("resource") or None)
    except OAuthError as exc:
        return _oauth_error_response(exc)


@app.post("/oauth/consent")
async def oauth_consent(request: Request):
    """Consent confirmation (P2): verifies the browser session JWT via the
    shared JWKS path, resolves the org (RFC 8707, D4), mints a single-use
    PKCE-bound authorization code, returns {code, state} for the redirect.
    """
    from tortoise.oauth import (
        OAuthError,
        issue_auth_code,
        validate_authorize_params,
    )
    cp, enabled = _oauth_control_plane()
    if not enabled or cp is None:
        raise HTTPException(status_code=503, detail="OAuth not configured")
    try:
        raw = await _read_capped_body(request, _BODY_MAX_BYTES, _BODY_413_DETAIL)
        body = _json.loads(raw)
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid JSON body")  # noqa: B904
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="Invalid JSON body")
    try:
        client = await _oauth_offload(
            lambda: validate_authorize_params(
                cp, client_id=body.get("client_id", ""),
                redirect_uri=body.get("redirect_uri") or None,
                response_type=body.get("response_type") or None,
                code_challenge=body.get("code_challenge") or None,
                code_challenge_method=body.get("code_challenge_method") or "S256"),
            op="oauth_consent_params")
    except OAuthError as exc:
        return _oauth_error_response(exc)
    # The browser session JWT — same JWKS/ES256+RS256 verification the session
    # endpoints use (D2: reuse session_auth verify; no new auth stack).
    user = await verify_session_jwt(request)
    try:
        code, _org_id = issue_auth_code(
            cp, client_id=client["id"], user_id=user["user_id"],
            base=_oauth_base(request),
            redirect_uri=body["redirect_uri"],
            code_challenge=body["code_challenge"],
            state=body.get("state"),
            scope=body.get("scope") or client.get("scope") or "mcp",
            resource=body.get("resource") or None,
        )
    except OAuthError as exc:
        return _oauth_error_response(exc)
    return {"code": code, "state": body.get("state"),
            "redirect_uri": body["redirect_uri"]}


@app.post("/oauth/token")
async def oauth_token(request: Request):
    """Token endpoint (P2 + P4 + D5): authorization_code exchange and
    refresh_token rotation (RFC 6749 §4.1.3 / §6, RFC 7009 semantics).
    Form-encoded body per OAuth; errors are RFC 6749 §5.2 JSON.
    """
    from tortoise.oauth import (
        OAuthError,
        _log_and_capture,
        exchange_auth_code,
        refresh_grant,
    )
    cp, enabled = _oauth_control_plane()
    if not enabled or cp is None:
        raise HTTPException(status_code=503, detail="OAuth not configured")
    from urllib.parse import parse_qs
    try:
        raw = await _read_capped_body(request, _BODY_MAX_BYTES, _BODY_413_DETAIL)
        body = {k: v[0] for k, v in parse_qs(raw.decode()).items()}
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid form body")  # noqa: B904
    grant = body.get("grant_type")
    base = _oauth_base(request)
    try:
        # #3669: the token grant is offloaded as a UNIT — `_verify_client_auth`
        # resolves the client (a CIMD fetch for an https client_id) and the
        # grant then makes several blocking PostgREST calls. Offloading the
        # grant puts both off the loop and charges the CIMD bounds at BOTH
        # token front doors (auth-code and refresh) as well as the two
        # authorize/consent doors, because all four reach `resolve_client`.
        if grant == "authorization_code":
            out = await _oauth_offload(
                lambda: exchange_auth_code(cp, body, base),
                op="oauth_token_exchange", no_wait_bound=True)
        elif grant == "refresh_token":
            out = await _oauth_offload(
                lambda: refresh_grant(cp, body, base),
                op="oauth_token_refresh", no_wait_bound=True)
        else:
            raise OAuthError(400, "unsupported_grant_type",
                             "grant_type must be authorization_code or refresh_token")
    except OAuthError as exc:
        return _oauth_error_response(exc)
    except Exception as exc:            # last-resort bug detector, NOT a retry signal
        _log_and_capture(exc, where="oauth/token boundary")
        return _oauth_error_response(
            OAuthError(500, "server_error", "Internal error processing the token request."))
    return out


@app.post("/oauth/revoke")
async def oauth_revoke(request: Request):
    """RFC 7009 token revocation (D5 — explicit client-initiated revocation)."""
    from tortoise.oauth import OAuthError, revoke_token
    cp, enabled = _oauth_control_plane()
    if not enabled or cp is None:
        raise HTTPException(status_code=503, detail="OAuth not configured")
    from urllib.parse import parse_qs
    try:
        raw = await _read_capped_body(request, _BODY_MAX_BYTES, _BODY_413_DETAIL)
        body = {k: v[0] for k, v in parse_qs(raw.decode()).items()}
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid form body")  # noqa: B904
    try:
        revoke_token(cp, body)
    except OAuthError as exc:
        return _oauth_error_response(exc)
    return Response(status_code=200, content="")


@app.post("/register")
async def oauth_dcr_register(request: Request):
    """Dynamic Client Registration (P3, RFC 7591, D1) — enables the
    'connectors discover and register' UX (Claude.ai/ChatGPT custom
    connectors) without operator-issued client_ids.
    """
    from tortoise.oauth import OAuthError, register_client
    cp, enabled = _oauth_control_plane()
    if not enabled or cp is None:
        raise HTTPException(status_code=503, detail="OAuth not configured")
    await _check_oauth_dcr_rate_limit(request)
    try:
        raw = await _read_capped_body(request, _BODY_MAX_BYTES, _BODY_413_DETAIL)
        body = _json.loads(raw)
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid JSON body")  # noqa: B904
    try:
        reg = register_client(cp, body)
    except OAuthError as exc:
        return _oauth_error_response(exc)
    return JSONResponse(status_code=201, content=reg)


